var SUBJECTS=["Air Law","Aircraft General Knowledge","Flight Performance and Planning","Human Performance and Limitations","Meteorology","Navigation","Operational Procedures","Principles of Flight","Communications"];
var NOTES=[{s:0,topic:"Operations of Aircraft",num:1,order:10,conf:"weak",status:"draft",
summary:"EASA sorts aviation activity three ways: commercial or non-commercial, air transport or specialised operation, and complex or other-than-complex aircraft. An aircraft is complex if it meets criteria on mass, seating, crew or engines. The Basic Regulation splits into Part-NCO, Part-FCL and SERA. Modern Part-21 aircraft use these, while non-Part-21 aircraft (microlights, gyroplanes, vintage, ex-military and amateur-built) come under ANO 2016.",
sections:[["EASA classifies civil aviation activity",["Commercial or non-commercial, based on the presence of remuneration","Air transport or specialised operation, based on the activity performed","Complex motor-powered or other-than-complex motor-powered, based on the aircraft used"]],
["Definition of complex (air operations)",["Maximum certificated take-off mass exceeding <code>5,700 kg</code>","Certificated for a maximum passenger seating configuration of more than <code>19</code>","Certificated for a minimum crew of at least <code>2</code> pilots","Equipped with at least <code>one</code> turbojet engine or more than <code>one</code> turboprop engine"]],
["Structure of the assimilated EU law",["The <b>Basic Regulation</b> branches into parts for different aspects of aviation","<b>Part-NCO</b> deals with NCO operations","<b>Part-FCL</b> deals with flight crew licensing","<b>SERA</b> (Standardised European Rules of the Air) deals with rules of the air"]],
["Documents for a UK pilot in a G-registered aeroplane",["<b>ANO 2016</b>: enacted by parliament, with safety requirements for all aircraft in UK airspace and persons involved in aircraft operations; airworthiness, operational and flight crew regulations for non-Part-21 aircraft","<b>UK rules of the air regulations 2015</b> (SERA UK): all aircraft in UK airspace must adhere","<b>Part-FCL</b>: licensing requirements for Part-21 aeroplanes","<b>Part-NCO</b>: operational regulations for Part-21 other-than-complex motor-powered aircraft","<b>ANO 2016 Part 6 &amp; Schedule 8</b>: licensing for non-Part-21 aircraft","<b>ANO 2016 Part 5 &amp; Schedule 5</b>: operational regulations for non-Part-21 aircraft"]],
["Part-21 or non-Part-21?",["Most modern factory-built aircraft (not microlights or gyroplanes) are <b>Part-21</b>","Vintage, ex-military, amateur-built aircraft, microlights and gyroplanes are <b>non-Part-21</b>"]]],
cards:[["What three ways does EASA classify civil aviation activity?","Commercial vs non-commercial; air transport vs specialised operation; complex vs other-than-complex motor-powered aircraft."],["What decides commercial vs non-commercial?","The presence of remuneration."],["What decides air transport vs specialised operation?","The activity performed."],["Complex aircraft: take-off mass threshold?","Maximum certificated take-off mass exceeding 5,700 kg."],["Complex aircraft: passenger seating threshold?","Maximum certificated seating of more than 19."],["Complex aircraft: minimum crew?","At least 2 pilots."],["Complex aircraft: engine criterion?","At least one turbojet, or more than one turboprop."],["What does Part-NCO cover?","Operational regulations for Part-21 other-than-complex motor-powered aircraft."],["What does Part-FCL cover?","Licensing requirements for Part-21 aeroplanes."],["What does SERA stand for, and cover?","Standardised European Rules of the Air; the rules of the air."],["What does the Air Navigation Order (ANO) 2016 contain?","Safety requirements for all aircraft in UK airspace and people involved in operating them, including airworthiness, operational and flight crew rules for non-Part-21 aircraft."],["Which ANO 2016 parts cover licensing and operations for non-Part-21 aircraft?","Licensing: Part 6 and Schedule 8. Operations: Part 5 and Schedule 5."],["Which aircraft are non-Part-21?","Vintage, ex-military, amateur-built aircraft, microlights and gyroplanes."],["Which aircraft are Part-21?","Most modern factory-built aircraft, excluding microlights and gyroplanes."]],
quiz:[["Which take-off mass makes an aircraft complex?",["2,730 kg","5,700 kg","5,701 kg","12,500 kg"],2,"The threshold is a maximum certificated take-off mass exceeding 5,700 kg."],["Which maximum seating configuration meets the complex threshold?",["9","12","19","20"],3,"More than 19, so exactly 19 does not qualify."],["What makes an activity commercial?",["Carrying passengers","Using a complex aircraft","Remuneration","Flying for a company"],2,"Commercial vs non-commercial depends on the presence of remuneration."],["Which engine fit meets the complex criterion?",["One piston engine","One turboprop","One turbojet","None of these"],2,"One turbojet is enough; turboprops need to be more than one."],["What separates air transport from specialised operation?",["The aircraft type","The activity performed","Crew size","Remuneration"],1,"It is based on the activity performed."],["Which regulation covers the rules of the air?",["Part-FCL","Part-NCO","SERA","Part-21"],2,"SERA is the Standardised European Rules of the Air."],["Which part covers flight crew licensing for Part-21 aeroplanes?",["Part-FCL","Part-NCO","SERA","ANO Part 5"],0,"Part-FCL contains the licensing requirements."],["Which of these is a non-Part-21 aircraft?",["A modern factory-built aeroplane","A microlight","A Part-21 airliner","A factory-built single"],1,"Microlights, gyroplanes, vintage, ex-military and amateur-built aircraft are non-Part-21."],["Which part covers operations of Part-21 other-than-complex aircraft?",["Part-NCO","Part-FCL","SERA","ANO Part 6"],0,"Part-NCO holds the operational regulations for these aircraft."]]},
{s:0,topic:"Aviation Law and organisations",num:2,order:20,conf:"weak",status:"draft",
summary:"How international and UK aviation law fit together. ICAO and the Chicago Convention set the Articles on sovereignty, registration, documents and licences, with 19 Annexes behind them. EASA and the UK CAA regulate at regional and national level. The UK Aeronautical Information Service covers the AIP and its 28-day AIRAC cycle, colour-coded AICs, NOTAMs and Air Supplements, plus the CAP guides and the layout of the Air Navigation Order 2016.",
sections:[
["International Civil Aviation Organisation (ICAO)",["Civil aviation resumed in <code>1919</code>; overflying other nations' territory and landing safely at prepared airfields had to be solved","<b>Paris Convention</b> <code>1919</code>: first major international aviation meeting (mostly European nations); general principles of air law and procedures agreed","<b>Chicago Convention</b> <code>1944</code>: moral obligation on contracting states to provide safe and efficient ground and flight organisations","<b>ICAO</b> formed <code>1947</code>, based in Montreal, Canada, to promote standards and recommended practices","The UK, like most nations, is an active ICAO member"]],
["Differences between ICAO nations",["Cruising levels: <b>feet</b> in western nations, metres in some eastern European nations","Pressure: the UK uses hectopascals (hPa), an ICAO recommendation; the US uses inches of mercury","Airspace classes are widely adopted with small differences: the UK has no <b>Class B</b>, while the USA allocates it to Terminal Control Areas"]],
["Chicago Convention principles",["The principles are known as <b>Articles</b>","<b>Shall</b> means must (required)","<b>Should</b> means not required, but recommended for good airmanship and flight safety"]],
["Articles 1 to 13: sovereignty and regulations",["<b>1 Sovereignty:</b> each state has complete and exclusive sovereignty over its airspace","<b>2 Territory:</b> land and waters under a state's sovereignty","<b>4 Misuse:</b> civil aviation not to be used contrary to the convention's aims (illegal uses or war)","<b>5 Non-scheduled flight:</b> aircraft of other states may fly into or through, and land, without prior permission; a state may require overflying aircraft to land, or to follow prescribed routes or get permission where terrain is remote","<b>10 Customs airports:</b> a state may require landing at a customs airport on entry, and departure from one","<b>11 Applicability:</b> any aircraft, whatever its nationality, obeys the regulations of the state it is in","<b>12 Rules of the air:</b> apply to aircraft in a state's territory and aircraft carrying its nationality mark anywhere; over the high seas the convention's rules apply; states endeavour to prosecute violators","<b>13 Entry and clearance:</b> immigration, passport, customs and quarantine rules apply to passengers, crew and cargo"]],
["Articles 16 to 26: registration and formalities",["<b>16 Search:</b> a state may search aircraft of other states on landing or before departure and inspect documents","<b>17 Nationality:</b> that of the state of registration","<b>18 Dual registration:</b> not allowed, but registration can be changed from one state to another","<b>19 National laws:</b> registration follows that state's laws","<b>20 Marks:</b> aircraft operating internationally display nationality and registration marks","<b>22 Facilitation:</b> prevent unnecessary delays (customs, immigration, quarantine)","<b>23 Procedures:</b> customs and immigration follow international practice","<b>24 Customs duty:</b> temporary admission duty-free; fuel, oil, spares and regular equipment retained on board on departure are exempt, but not items unloaded; spares imported for an aircraft on international operations are duty-free","<b>25 Distress:</b> states assist aircraft in distress and allow the owner and state of registry to assist","<b>26 Accident investigation:</b> the state where an accident occurs (deaths, serious injury or serious defect) investigates per ICAO procedures; the state of registry may observe"]],
["Articles 28 to 40: facilities, documents and licences",["<b>28 Facilities:</b> radio, met and navigation services to ICAO standards; standard systems for communications, marking, signals and lighting; cooperation on charts","<b>29 Documents:</b> certificate of registration, certificate of airworthiness, licence for each crew member, journey logbook, radio licences, passenger list (names, embarkation, destination) if carrying passengers, cargo manifest and declarations if carrying cargo","<b>30 Radio:</b> only if licensed by the state of registry, used per the regulations of the state flown over, and only by licensed crew","<b>31 Certificate of airworthiness:</b> valid, issued by the state of registry","<b>32 Licences:</b> issued by the state of registry; a state may refuse to recognise its own nationals' licences granted by another state for flights over its territory","<b>33 Recognition:</b> certificates and licences recognised if issued to ICAO standards","<b>34 Journey logbooks:</b> kept on international operations","<b>35 Cargo:</b> weapons or munitions of war only with the state's permission; other items may be prohibited for public order or safety","<b>36 Photography:</b> may be prohibited or regulated","<b>37 Standards:</b> states aim for uniformity; ICAO adopts and amends standards and recommended practices (SARPs)","<b>39 and 40 Endorsements:</b> failures to meet a standard are shown on the certificate or licence; use internationally only if permitted; use in another state is at that state's discretion"]],
["Articles 43 to 47, Annexes",["<b>43:</b> ICAO is formed by the convention, made up of an assembly, a council and other bodies","<b>44 Objectives:</b> safe and orderly growth; peaceful aircraft design and operation; development of airways, airports and navigation facilities; safe, regular, efficient and economical transport; fair competition without discrimination","<b>47:</b> states grant ICAO the legal capacity it needs","<b>19 Annexes</b> supplement the articles and define standards and recommended practices (SARPs)","UK differences from the ICAO system are shown in <b>AIP GEN 1-7</b>"]],
["EASA",["EASA regulates licensing for pilots and aircraft across the EU, with full responsibility for flight operations and crew licensing (including training)","Having left the EU, the UK is again responsible for its own regulation","Key regulations for private pilots: the <b>Basic Regulation</b> and the <b>Aircrew Regulation</b>, both amended regularly","The Basic Regulation has annexes on airworthiness, licensing, medical and air traffic management","Subdivisions are <b>Parts</b> (e.g. <b>Part ORA</b> covers organisations such as training schools), implemented through <b>AMC</b> (Acceptable Means of Compliance) and <b>GM</b> (Guidance Material)"]],
["Aviation law in the UK",["Enacted by Parliament; main sources for a private pilot: the Air Navigation Order, Part-NCO, Part-FCL and the Air Navigation (General) Regulations","The <b>CAA</b> is responsible for civil aviation in the UK, including the <b>Aeronautical Information Service (AIS)</b>"]],
["Aeronautical Information Publication (AIP)",["<b>GEN:</b> national regulations and requirements, services, charges","<b>ENR:</b> en route rules and procedures, ATS information, navigation warnings","<b>AD:</b> information on licensed UK aerodromes","Updated on a fixed 28-day <b>AIRAC</b> cycle (Aeronautical Information Regulation And Control), with information of lasting character"]],
["Aeronautical Information Circulars (AICs)",["Published monthly: administrative matters, advance warning of operational changes, operational and safety advice","Colours: Air Safety <b>pink</b>; Administrative <b>white</b>; Operational and Air Traffic Services <b>yellow</b>; UK Restrictions Chart <b>mauve</b>; Maps/Charts <b>green</b>","The exam may refer to a specific AIC; read the relevant ones, especially pink: Take-off, Climb and Landing Performance (AIC 127/2006, Pink 110), Wake Turbulence (AIC P083/2020), Helicopter Flight in Degraded Visual Conditions (AIC P137/2019)"]],
["NOTAMs and Air Supplements",["<b>NOTAMs</b> are obtained daily before flight: restrictions (temporary controlled airspace, Red Arrows displays), runway closures, temporary obstacles, other vital information","Categories: <b>NOTAMN</b> new, <b>NOTAMR</b> replaces a previous one, <b>NOTAMC</b> cancels a previous one","<b>Air Supplements</b> carry temporary information with too much text or graphics for a NOTAM, e.g. major air shows or aerodrome work","AIP Supplements are issued every 28 days and stay current until no longer valid or notified as such"]],
["AIS delivery and publications",["NATS provides the AIS on behalf of the CAA (NATS AIS Internet Briefing System)","AIS is giving way to the digital <b>Aeronautical Information Management (AIM)</b> system; ICAO Annex 15 covers aeronautical information services","<b>CAP 1535</b> Skyway Code; <b>CAP 637</b> Visual aids handbook; <b>CAP 413</b> Radiotelephony procedures; <b>CAP 804</b> licence requirements (reference only)","CAA General Aviation Safety Leaflets are available at training organisations and aeroclubs"]],
["The Air Navigation Order 2016",["A statutory instrument enacted by Parliament as the basis of UK civil aviation, arranged in <b>Parts</b> (e.g. Part 4 Airworthiness of Aircraft) with consecutively numbered <b>Articles</b>","Further detail is in <b>Schedules</b> (e.g. Schedule 1 Interpretation)","Flight planners refer to it for equipment, licensing, documents, registration and operations, alongside Part-NCO","<b>Schedule 13</b> sets liability and maximum penalties for contraventions","<b>Schedule 1</b> gives the legal definitions and acts as a glossary"]]],
cards:[["What was the Paris Convention of 1919?","The first major international aviation meeting, mostly European nations. It agreed general principles of air law and procedures."],["What did the Chicago Convention (1944) establish?","A moral obligation on contracting states to provide safe and efficient ground and flight organisations."],["When was ICAO formed, and where is it based?","1947, Montreal, Canada."],["What is ICAO's purpose?","To promote aviation standards and recommended practices internationally."],["Cruising level units: west vs some eastern Europe?","Feet in the west; metres in some eastern European nations."],["Pressure units: UK vs US?","UK: hectopascals (hPa). US: inches of mercury."],["How does UK airspace differ on Class B?","The UK has no Class B. In the USA it is allocated to Terminal Control Areas."],["What are ICAO principles from the Chicago Convention called?","Articles."],["ICAO wording: shall vs should?","Shall means must (required). Should means recommended for good airmanship and safety, not required."],["Chicago Convention: which article gives each state complete and exclusive sovereignty over its airspace?", "Article 1 (sovereignty)."],["Chicago Convention: which article lets non-scheduled flights fly into or across a state without prior permission?", "Article 5 (non-scheduled flights). The state may still require the aircraft to land."],["Chicago Convention: which article says an aircraft must obey the laws and regulations of the state it is in, whatever its nationality?", "Article 11 (obey local regulations)."],["Chicago Convention: which article covers rules of the air, including which rules apply over the high seas?", "Article 12 (rules of the air). States keep their rules as close as possible to ICAO's; over the high seas ICAO's rules apply."],["Chicago Convention: which articles say an aircraft takes the nationality of its state of registration, and cannot be registered in two states at once?", "Articles 17 (nationality) and 18 (no dual registration). Registration can still be changed from one state to another."],["Chicago Convention: which article requires aircraft on international flights to display nationality and registration marks?", "Article 20 (display of marks)."],["Chicago Convention: which article makes fuel, oil, spares and regular equipment on board exempt from customs duty on arrival?", "Article 24 (customs duty). Items unloaded are not exempt."],["Chicago Convention: which article says who investigates an accident in another state?", "Article 26 (accident investigation). The state where it happens investigates; the state of registry may send observers."],["Chicago Convention: which article lists the documents carried on international flights, and what are they?", "Article 29. Certificate of registration, certificate of airworthiness, crew licences, journey log book, radio station licence, passenger list and cargo manifest (if carrying them). Not the pilot's personal logbook."],["Chicago Convention: which article requires a certificate of airworthiness for international flights?", "Article 31. Issued or validated by the state of registry."],["Chicago Convention: which articles cover crew licences and their recognition by other states?", "Articles 32 (licences issued or validated by the state of registry) and 33 (other states recognise them if they meet ICAO standards)."],["Chicago Convention: which article sets out ICAO's objectives?", "Article 44. Develop international air navigation and foster safe, orderly growth of international air transport: peaceful use, fair competition, no discrimination."],["How many ICAO Annexes, and where are UK differences shown?","19 Annexes. UK differences are in AIP GEN 1-7."],["Who regulates UK aviation after leaving the EU, and what is the CAA's information role?","The UK regulates itself. The CAA provides the Aeronautical Information Service (AIS), delivered by NATS."],["What are AMC and GM?","Acceptable Means of Compliance and Guidance Material, used to implement the rules in Parts."],["What is Part ORA?","The Part dealing with regulation of organisations, such as training schools."],["Main UK sources of regulation for a private pilot?","The Air Navigation Order, Part-NCO, Part-FCL and the Air Navigation (General) Regulations."],["What do the AIP parts GEN, ENR and AD cover?","GEN: national regulations and services. ENR: en route information. AD: licensed aerodromes."],["How often is the AIP updated?","Every 28 days on the AIRAC cycle."],["How often are AICs published, and what is the colour code?","Monthly. Pink air safety, white administrative, yellow operational/ATS, mauve UK restrictions chart, green maps/charts."],["NOTAM categories?","NOTAMN new, NOTAMR replacing, NOTAMC cancelling."],["What are Air Supplements?","Temporary information with too much text or graphics for a NOTAM, e.g. air shows or aerodrome work. Issued every 28 days."],["What is replacing the AIS concept?","The digital Aeronautical Information Management (AIM) system. ICAO Annex 15 covers aeronautical information services."],["CAP 1535, 637, 413, 804?","Skyway Code; Visual aids handbook; Radiotelephony procedures; licence requirements (reference only)."],["How is the ANO 2016 organised?","Parts containing consecutively numbered Articles, with detail in Schedules."],["ANO Schedule 13 and Schedule 1?","Schedule 13: liability and maximum penalties. Schedule 1: legal definitions (glossary)."]],
quiz:[["Which convention was the first major international aviation meeting?",["Chicago 1944","Paris 1919","Montreal 1947","Geneva 1930"],1,"The Paris Convention of 1919, mostly European nations."],["When was ICAO formed?",["1919","1944","1947","1950"],2,"The Chicago Convention was 1944, ICAO itself was formed in 1947."],["Which unit of pressure does the UK use?",["Inches of mercury","Hectopascals","Millimetres of mercury","Pounds per square inch"],1,"The UK uses hPa; the US uses inches of mercury."],["Which airspace class does the UK not have?",["Class A","Class B","Class C","Class D"],1,"The UK has no Class B; in the USA it covers Terminal Control Areas."],["What does 'shall' mean in ICAO documents?",["Recommended","Required","Optional","Advisory"],1,"Shall means must. Should is a recommendation."],["Which Article gives states exclusive sovereignty over their airspace?",["Article 1","Article 2","Article 11","Article 12"],0,"Article 1 is sovereignty."],["Which Article makes any aircraft obey the regulations of the state it is in?",["Article 5","Article 11","Article 12","Article 13"],1,"Article 11, regardless of nationality."],["What nationality does an aircraft have?",["The operator's","The state of registration","The pilot's","The manufacturer's"],1,"Article 17: the state of registration."],["Can an aircraft be registered in two states at once?",["Yes, if both agree","No, but registration can be changed","Yes, for international flights","Only commercial aircraft"],1,"Article 18 forbids dual registration."],["Which Article lists documents carried on international flights?",["Article 20","Article 29","Article 31","Article 34"],1,"Article 29."],["Which state investigates an accident with deaths in another state?",["State of registry","State where it occurs","ICAO","State of the operator"],1,"Article 26: the state where it occurs investigates; the state of registry may observe."],["How many ICAO Annexes are there?",["12","15","19","24"],2,"There are 19 Annexes."],["Where are UK differences from ICAO shown?",["AIP GEN 1-7","ANO 2016","SERA","Article 37"],0,"AIP GEN 1-7."],["How often is the AIP updated?",["Weekly","Every 28 days","Monthly","Annually"],1,"On the 28-day AIRAC cycle."],["What colour are Air Safety AICs?",["White","Pink","Yellow","Green"],1,"Pink; white is administrative, yellow operational/ATS, mauve restrictions chart, green maps/charts."],["Which AIP part covers licensed aerodromes?",["GEN","ENR","AD","AIC"],2,"AD covers aerodromes."],["What does NOTAMC do?",["Gives new information","Replaces a NOTAM","Cancels a NOTAM","Corrects a chart"],2,"NOTAMN is new, NOTAMR replaces, NOTAMC cancels."],["Which CAP is the radiotelephony procedures guide?",["CAP 637","CAP 413","CAP 1535","CAP 804"],1,"CAP 413. CAP 1535 is the Skyway Code."],["Which ANO schedule covers penalties?",["Schedule 1","Schedule 5","Schedule 8","Schedule 13"],3,"Schedule 13; Schedule 1 is interpretation."],["Which body is responsible for civil aviation in the UK?",["EASA","ICAO","CAA","NATS"],2,"The CAA; NATS provides AIS on its behalf."],["How often are AICs published?",["Daily","Weekly","Monthly","Every 28 days"],2,"AICs are monthly."],["What carries temporary information too long for a NOTAM?",["An AIC","An Air Supplement","The AIRAC cycle","AIP ENR"],1,"Air Supplements, e.g. for major air shows."]]}];
var SUM={"EASA classifies civil aviation activity": "Activity is classified three ways: by payment, by type of operation and by aircraft category.", "Definition of complex (air operations)": "Four tests (mass, seats, crew, engines); meeting any one makes an aircraft complex.", "Structure of the assimilated EU law": "The Basic Regulation splits into Part-NCO (operations), Part-FCL (licensing) and SERA (rules of the air).", "Documents for a UK pilot in a G-registered aeroplane": "Which document applies depends on Part-21 status: Part-FCL and Part-NCO for Part-21 aircraft, ANO 2016 for the rest, with UK SERA for everyone.", "Part-21 or non-Part-21?": "Modern factory-built aircraft are Part-21; microlights, gyroplanes, vintage, ex-military and amateur-built are not.", "International Civil Aviation Organisation (ICAO)": "Post-WW1 flying led to the Paris Convention (1919), the Chicago Convention (1944) and ICAO (1947, Montreal) to set common standards.", "Differences between ICAO nations": "Nations differ on cruising level units, pressure units and airspace classes; the UK uses feet, hPa and has no Class B.", "Chicago Convention principles": "Its principles are called Articles; \"shall\" is mandatory and \"should\" is only recommended.", "Articles 1 to 13: sovereignty and regulations": "States control their own airspace and regulations; any aircraft must obey the rules of the state it is in, and customs and entry rules apply.", "Articles 16 to 26: registration and formalities": "An aircraft has one nationality (its state of registry), shows its marks, benefits from smooth customs, and is investigated by the state where an accident occurs.", "Articles 28 to 40: facilities, documents and licences": "Covers the facilities states provide and the documents, licences and certificates needed for international flights, which are recognised if they meet ICAO standards.", "Articles 43 to 47, Annexes": "Sets up ICAO, its objectives and legal capacity; 19 Annexes hold the detailed standards, with UK differences in AIP GEN 1-7.", "EASA": "EASA regulated licensing and operations across the EU; the UK now regulates itself, but the Parts, AMCs and GM structure remains familiar.", "Aviation law in the UK": "UK law comes from Parliament via the ANO, Part-NCO, Part-FCL and the General Regulations, with the CAA responsible for information through the AIS.", "Aeronautical Information Publication (AIP)": "The AIP has three parts (GEN, ENR, AD) and is revised every 28 days on the AIRAC cycle.", "Aeronautical Information Circulars (AICs)": "Monthly circulars on administration, operations and safety, colour-coded by subject; pink safety AICs matter most for the exam.", "NOTAMs and Air Supplements": "NOTAMs give daily short-notice information (new, replacing or cancelling); Air Supplements carry longer temporary information.", "AIS delivery and publications": "NATS delivers the AIS for the CAA, AIM is replacing it, and the CAPs and safety leaflets explain the rules in simpler form.", "The Air Navigation Order 2016": "The ANO is the UK's main aviation statute: Parts and Articles for the rules, Schedules for detail, penalties in Schedule 13 and definitions in Schedule 1."};
NOTES.push({"s": 0, "topic": "Rules of the Air", "num": 3, "order": 30, "conf": "weak", "status": "draft", "summary": "The rules that keep aircraft apart. SERA and the UK rules apply ICAO Annex 2, and the commander always has to avoid collisions. Head-on aircraft turn right, the overtaker keeps clear, and converging aircraft give way to less manoeuvrable types or to traffic on their right. Near aerodromes you follow the pattern and turn left, the lower or final aircraft has priority, and navigation lights show which way another aircraft is heading. Low flying rules set 1,000 ft over congested areas and 500 ft elsewhere, with defined exemptions. On international flights you must know the interception signals: rock your wings and follow, squawk 7700 and call on 121.50 MHz.", "sections": [["SERA and the UK rules of the air", ["Regulation (EU) No 923/2012 of 26 September 2012, as amended, set common rules of the air and operational provisions for air navigation services across EU states", "On <code>1 January 2021</code> the UK left EASA and the regulations in force passed into UK law as <b>retained EU law</b>, now called <b>assimilated law</b> (EU Withdrawal Act 2018)", "SERA applies ICAO standards and recommended practices and harmonises the ICAO airspace classification, supporting a single EU sky", "The Single European Sky helps states meet their 1944 Chicago Convention obligations through a common interpretation and implementation", "Only differences agreed by EU states are notified to ICAO", "<b>ICAO Annex 2</b> sets the international standards for the rules of the air; the UK and EU both fully endorse them", "<b>SERA</b> applies to every aircraft in EU airspace, whatever its type or state of registry", "SERA does not cover every aspect, so states may keep supplementary rules", "UK rules assimilated under <b>Article 249 of the ANO</b> sit in a separate Statutory Instrument, usually bound with the ANO in <b>CAP 393</b>", "Many permissions and exemptions last only a short period, so check they are still valid on the CAA website (<b>ORS4</b>, Official Record Series 4)"]], ["Scope and departures from the rules", ["The rules apply to all aircraft in the UK (including near offshore installations, where low flying is concerned) and to all UK-registered aircraft wherever they are", "SERA may be departed from as far as necessary to avoid immediate danger, or to comply with the law of the country the aircraft is in", "A departure for safety reasons must be reported in writing to the competent authority within <code>10 days</code>"]], ["Collision avoidance (SERA.3201)", ["A collision risk exists when another aircraft is at the same level or approaching, its range is decreasing and its relative bearing stays constant", "Regardless of any ATC clearance, the commander must take all possible measures to avoid colliding with any other aircraft", "Do not fly so close to another aircraft as to create a danger of collision", "No formation flying unless the commanders have agreed", "An aircraft that must give way avoids passing over, under or crossing ahead of the other, unless passing well clear", "An aircraft with right of way maintains its heading and speed", "A glider and its tug count as one aircraft under the command of the tug; aeroplanes and helicopters must give way to aircraft towing gliders"]], ["Right of way (SERA.3210)", ["<b>Head-on:</b> if there is danger of collision, each aircraft turns <b>right</b>", "<b>Overtaking:</b> the aircraft being overtaken has right of way; the overtaker, whether climbing, descending or level, keeps out of the way by turning right", "An overtaking situation can be taken as approaching within <code>70°</code> of the other aircraft's centreline", "<b>Converging, by category:</b> power-driven heavier-than-air aircraft give way to airships, sailplanes and balloons; airships give way to sailplanes and balloons; sailplanes give way to balloons", "<b>Converging, same category at about the same altitude:</b> the aircraft with the other on its <b>right</b> gives way", "Power-driven aircraft give way to those towing other aircraft or objects such as banners"]], ["Flights near an aerodrome (SERA.3225)", ["Unless ATC authorises otherwise, conform to the pattern formed by other landing aircraft or keep clear of the airspace where it is formed", "Make all turns to the <b>left</b> unless ground signals direct otherwise", "If ATC approves a straight-in approach, the pilot normally reports <b>long final</b> at <code>8 nm</code> and <b>final</b> at <code>4 nm</code> from the runway"]], ["Order of landing and take-off (Rules 9 and 10)", ["An aircraft landing or on final approach has right of way over others in flight or on the surface", "When two or more aircraft approach to land, the <b>lower</b> aircraft has right of way, but must not cut in front of or overtake one on final approach", "If ATC sets a landing order, follow it. If another aircraft is making an emergency landing, give way, and at night do not land until given further instruction", "Power-driven heavier-than-air aircraft give way to sailplanes in all cases", "Take off and land in the direction shown by ground signals or, without them, into wind, unless good aviation practice demands otherwise", "Do not land on a runway that is not clear unless ATC authorises it. <b>Land after</b> is not a landing clearance: the decision is yours, based on whether separation is sufficient (never given at night)", "Where take-offs and landings are not confined to a runway, leave clear on your left any aircraft which has landed, is landing or is about to take off (keep right of other aircraft)", "When taxiing on a landing area, turn left once you are satisfied it will not interfere with other traffic", "A flying machine about to take off leaves clear on its left any aircraft which has taken off or is about to", "After landing, move clear of the landing area as soon as possible unless ATC authorises otherwise"]], ["Radio in the ATZ and the right-hand traffic rule", ["In an <b>Aerodrome Traffic Zone (ATZ)</b>, maintain appropriate radio or other communication with the aerodrome authority (ATC, Aerodrome Flight Information Service or Air/Ground Radio)", "Before SERA, an aircraft following a road, railway, canal, coast or other line feature in sight of the ground had to keep it on its left, except in controlled airspace or when told otherwise", "This is <b>no longer</b> a legal requirement, but the CAA strongly recommends it to keep separation from aircraft flying the opposite way along the same feature"]], ["Lights on aircraft (Rule 14, SERA.3215)", ["Aircraft must show the lights specified for their category so others can judge position and heading at night; the requirements generally apply when moving on the ground, and no other lights may be shown that impair them", "If any required light fails in flight and cannot be repaired or replaced at once, the aircraft <b>must land</b> as soon as it is safe, unless ATC authorises continuing (Rule 15)", "Flying machines and airships: <b>green</b> navigation light on the <b>right (starboard)</b> wing, <b>red</b> on the <b>left (port)</b> wing, each showing <code>110°</code> from dead ahead", "The <b>white</b> tail light shows through <code>70°</code> either side of dead astern", "The anti-collision light is a flashing red light visible in all directions", "Red out to your left means your paths will not cross (<b>red to red = safe</b>); red out to your right may mean a collision risk (<b>red to green = unsafe</b>)", "Green is the reverse: <b>green to green = safe</b>, <b>green to red = unsafe</b>", "Red and green both visible: the other aircraft is heading straight at you. White visible: it is flying away from you", "Airships also show a white nose light through <code>110°</code> either side of dead ahead; gliders show the basic flying machine lights or a steady red light in all directions; free balloons show a steady red light in all directions", "In the UK, night runs from <code>30 minutes after sunset</code> to <code>30 minutes before sunrise</code>"]], ["Low flying prohibitions (SERA.3105 and .5005(f))", ["Minimum heights are set in both EASA SERA and UK SERA, with some differences", "<b>UK and EASA, congested areas:</b> not below <code>1,000 ft</code> above the highest fixed object within <code>600 m</code>, and able to land clear without undue hazard to persons or property if an emergency arises. Being able to land clear is the pilot's responsibility, not ATC's", "<b>EASA:</b> not below <code>500 ft</code> above the ground or water, or 500 ft above the highest obstacle within <code>150 m</code> of the aircraft", "<b>UK, day only:</b> not closer than <code>500 ft</code> to any person, vehicle, vessel or structure", "<b>UK, at night:</b> not below 500 ft above the ground or water, or 500 ft above the highest obstacle within 150 m", "Exempt from the 500 ft and congested area rules when landing or taking off by normal aviation practice; the UK also exempts practising approaches to land or checking navigation aids or procedures at an aerodrome (under EASA a state authority may grant that exemption)"]], ["Open-air assemblies", ["<b>EASA:</b> except for take-off or landing, or with permission, do not fly over an organised open-air assembly of persons below the higher of 1,000 ft above the highest obstacle within 600 m, or a height that allows a landing without undue hazard if an emergency arises", "<b>UK:</b> the same heights apply over assemblies of more than <code>1,000</code> persons, and flying lower needs written permission from the CAA", "<b>UK:</b> do not land or take off within <code>1,000 m</code> of an assembly of more than 1,000 persons, except at an aerodrome using CAA-notified procedures, or at another landing site using notified procedures and the organiser's written permission"]], ["Exceptions to the low flying prohibitions", ["<b>Take-off and landing:</b> exempt when flying by normal aviation practice to take off, land, practise approaches or check navigation aids or procedures at an aerodrome; exempt from the 500 ft rule when landing, taking off or air-taxiing", "<b>Captive balloons and kites:</b> no low flying prohibitions apply", "<b>Special VFR and notified routes:</b> exempt from the 1,000 ft rule, but landings under this exemption only at a licensed or government aerodrome unless the CAA gives written permission", "<b>Balloons and helicopters:</b> a balloon landing because it is becalmed is exempt from the 1,000 ft rule; a helicopter over a congested area is exempt from the land-clear rule", "<b>Police air operator's certificate:</b> exempt from the 500 ft rule, the 1,000 ft rule and the open-air assembly prohibitions", "<b>Flying displays, air races and contests:</b> exempt from the 500 ft rule within <code>1,000 m</code> horizontally of the gathering", "<b>Glider hill-soaring:</b> exempt from the 500 ft rule", "<b>Picking up or dropping tow ropes, banners or similar at an aerodrome:</b> exempt from the 500 ft rule", "<b>Manoeuvring helicopters:</b> exempt from the 500 ft rule within a licensed or government aerodrome (or elsewhere with written CAA permission), but not closer than <code>60 m</code> to persons, vessels, vehicles or structures outside the site"]], ["Other rules: hazards, aerobatics and instrument practice", ["Exempt from the 500 ft rule: dropping articles with CAA permission for public health or against weather conditions, or under a CAA <b>aerial application certificate</b>", "The CAA <b>prosecutes</b> alleged low flying", "Report hazardous flight conditions to ATC <b>as soon as possible</b>, with details that matter to other aircraft: severe windshear or turbulence, rapidly worsening visibility, an unserviceable runway", "<b>Aerobatics</b> (Rule 4): not over a congested area (any city, town or settlement used for residential, industrial, commercial or recreational purposes); in controlled airspace only with the controlling authority's approval", "<b>Simulated instrument flight</b> (SERA.3220): fully working dual controls and a qualified <b>safety pilot</b> in the other control seat. A student pilot cannot be the safety pilot. Carry a third person as observer if needed for an adequate lookout", "<b>Practice instrument approaches</b> in VMC: inform ATC and carry a <b>competent observer</b>", "<b>Misuse of signals</b> (Rule 18): use specified signals and markings only for their meaning; never make signals that could be confused with them, and use military signals only with lawful authority"]], ["Interception: what to do (AIP ENR 1.12)", ["On international flights carry the interception procedures; they are in <b>AIP ENR 1.12</b>. Interception may be for military necessity, public safety, or to stop flight over restricted or danger areas", "Stay calm and follow the intercepting aircraft's visual signals and instructions precisely", "Tell the ATS unit you are working, if possible", "Call the interceptor or intercept control on <code>121.50 MHz</code>, giving your callsign and the nature of your flight", "Squawk <code>7700</code> unless the ATS unit tells you otherwise", "If another source (for example ATC) contradicts the interceptor, ask for clarification at once but <b>obey the interceptor's visual instructions</b>", "Avoid hand signals: they are easily misread", "If you are ever intercepted abroad, report it to the CAA"]], ["Interception signals", ["<b>\"Follow me\"</b>: interceptor rocks its wings from slightly above and ahead (normally on your left), then makes a slow level turn, normally left. You: rock your wings and follow <b>immediately</b>; at night also flash your navigation lights at irregular intervals", "Too slow to keep up? The interceptor flies racetrack patterns and rocks its wings each time it passes you", "<b>\"You may proceed\"</b>: an abrupt break-away climbing turn of <code>90°</code> or more without crossing your line of flight. You: rock your wings", "<b>\"Land at this aerodrome\"</b>: interceptor circles, lowers its gear and overflies the runway in the landing direction (steady landing lights at night). You: lower gear if possible, follow, and land if, after overflying the runway, you judge it safe", "<b>\"Aerodrome is inadequate\"</b> (from you): raise gear if possible while passing over the runway between <code>1,000 ft</code> and <code>2,000 ft</code> above aerodrome level, and keep circling", "<b>\"I cannot comply\"</b> (from you): switch all lights on and off at <b>regular</b> intervals, distinct from flashing lights", "<b>\"I am in distress\"</b> (from you): switch all lights on and off at <b>irregular</b> intervals", "The interceptor answers \"cannot comply\" and \"distress\" with an abrupt break-away climbing turn, meaning \"understood\""]], ["Interception radio phrases and ground signals", ["Without a common language, use the standard phrases. From you: <b>CALLSIGN</b> (my callsign is), <b>WILCO</b> (will comply), <b>CAN NOT</b> (unable to comply), <b>REPEAT</b>, <b>AM LOST</b> (position unknown), <b>MAYDAY</b>, <b>HIJACK</b>, <b>LAND</b> (place) (I request to land at), <b>DESCEND</b> (I require descent)", "From the interceptor: <b>FOLLOW</b> (follow me), <b>YOU LAND</b> (land at this aerodrome), <b>PROCEED</b> (you may proceed)", "<b>Warning from the ground</b>: projectiles fired every <code>10 seconds</code>, each bursting into <b>red and green</b> lights or stars, by day or night. You are in, or about to enter, a restricted, prohibited or danger area: take remedial action"]]], "cards": [["Which regulation introduced SERA, and when?", "Regulation (EU) No 923/2012 of 26 September 2012, as amended."], ["What happened to EASA rules in the UK on 1 January 2021?", "They passed into UK law as retained EU law, now called assimilated law."], ["Which ICAO Annex sets the international rules of the air?", "Annex 2."], ["Where are the UK-assimilated rules of the air found?", "Under Article 249 of the ANO, in a separate Statutory Instrument usually bound with the ANO as CAP 393."], ["Where do you check that a permission or exemption is still valid?", "The CAA website, ORS4 (Official Record Series 4)."], ["Which aircraft do the UK rules of the air apply to?", "All aircraft in the UK, and all UK-registered aircraft wherever they are."], ["When may you depart from the rules of the air?", "As far as necessary to avoid immediate danger, or to comply with the law of the country you are in."], ["How soon must a safety departure from the rules be reported?", "In writing to the competent authority within 10 days."], ["When does a collision risk exist?", "Another aircraft is at the same level or approaching, its range is decreasing and its relative bearing stays constant."], ["Who must avoid collisions, whatever ATC has cleared?", "The commander (pilot in command)."], ["What should an aircraft with right of way do?", "Maintain its heading and speed."], ["How are a glider and its tug treated?", "As one aircraft under the command of the tug. Aeroplanes and helicopters give way to aircraft towing gliders."], ["Head-on with a risk of collision: what does each aircraft do?", "Turn right."], ["Overtaking: who has right of way, and what does the overtaker do?", "The aircraft being overtaken. The overtaker keeps clear by turning right."], ["What counts as an overtaking situation?", "Approaching from within 70° of the other aircraft's centreline."], ["Converging: who gives way, by category?", "Power-driven heavier-than-air aircraft give way to airships, sailplanes and balloons; airships to sailplanes and balloons; sailplanes to balloons."], ["Converging in the same category at about the same altitude: who gives way?", "The aircraft that has the other on its right."], ["Near an aerodrome, which way do you turn?", "Left, unless ground signals direct otherwise."], ["On a straight-in approach, where are 'long final' and 'final' reported?", "Long final at 8 nm, final at 4 nm from the runway."], ["Two aircraft approach to land: who has priority?", "The lower aircraft, but it must not cut in front of or overtake one on final. An aircraft on final has right of way over others."], ["What does ATC's 'land after' mean?", "It is not a clearance to land. You decide whether separation is sufficient. It is never given at night."], ["Is the right-hand traffic rule still a legal requirement?", "No. Keeping a line feature on your left is only strongly recommended by the CAA."], ["Which colour navigation light is on which wing?", "Green on the right (starboard) wing, red on the left (port) wing, each showing 110° from dead ahead."], ["How much of the sky does the white tail light cover?", "70° either side of dead astern."], ["Red to red, green to green: safe or unsafe?", "Safe. Red to green and green to red are unsafe."], ["You see both red and green lights on another aircraft. What does it mean?", "It is heading straight at you. A white light means it is flying away."], ["What must you do if a required light fails in flight?", "Land as soon as it is safe, unless ATC authorises continuing."], ["When does night start and end in the UK?", "From 30 minutes after sunset to 30 minutes before sunrise."], ["Minimum height over a congested area?", "1,000 ft above the highest fixed object within 600 m, and able to land clear in an emergency. Landing clear is the pilot's responsibility."], ["UK 500 ft rule by day?", "Not closer than 500 ft to any person, vehicle, vessel or structure."], ["EASA 500 ft rule?", "Not below 500 ft above the ground or water, or 500 ft above the highest obstacle within 150 m."], ["How close may you take off or land to an open-air assembly of more than 1,000 persons?", "Not within 1,000 m, except at an aerodrome using CAA procedures or at an approved site with the organiser's written permission."], ["Do the low flying prohibitions apply to captive balloons and kites?", "No."], ["How close may a manoeuvring helicopter under the exemption get to people and property outside the site?", "Not closer than 60 m."], ["Which low flying exemption covers crop spraying and similar work?", "Dropping articles with CAA permission, or under a CAA aerial application certificate (exempt from the 500 ft rule)."], ["Which hazardous conditions must you report to ATC, and when?", "As soon as possible: things like severe windshear or turbulence, rapidly worsening visibility, or an unserviceable runway."], ["Where may you not fly aerobatics?", "Over a congested area. In controlled airspace only with the controlling authority's approval."], ["What do you need for simulated instrument flight?", "Working dual controls and a qualified safety pilot in the other control seat (not a student pilot), plus an observer if needed for lookout."], ["Practising instrument approaches in VMC: what two things are required?", "Inform ATC and carry a competent observer."], ["Where are the interception procedures published?", "AIP ENR 1.12."], ["Intercepted: which frequency and which squawk?", "Call on 121.50 MHz with your callsign and nature of flight; squawk 7700 unless the ATS unit says otherwise."], ["ATC and the interceptor give conflicting instructions. What do you do?", "Ask for clarification at once, but obey the interceptor's visual instructions."], ["Interceptor rocks its wings from ahead, then turns slowly left. Meaning and your reply?", "\"Follow me.\" Rock your wings and follow immediately (at night, also flash navigation lights at irregular intervals)."], ["Interceptor makes an abrupt climbing turn of 90° or more without crossing your path. Meaning?", "\"You may proceed.\" Reply by rocking your wings."], ["Interceptor lowers its gear and overflies the runway. Meaning and reply?", "\"Land at this aerodrome.\" Lower gear if possible, follow, and land if it looks safe."], ["How do you signal \"this aerodrome is inadequate\"?", "Raise gear (if possible) while passing over the runway between 1,000 and 2,000 ft above aerodrome level, and keep circling."], ["Lights switched on and off at regular vs irregular intervals?", "Regular = I cannot comply. Irregular = I am in distress."], ["What do WILCO, CAN NOT and AM LOST mean in interception phrases?", "Will comply; unable to comply; position unknown."], ["Red and green stars fired from the ground every 10 seconds?", "You are in, or about to enter, a restricted, prohibited or danger area. Take remedial action."], ["Night, steady relative bearing of 330°, you see the other aircraft's green light. What now?", "Collision risk (green to red). It has you on its right so it must give way: you hold heading and speed."]], "quiz": [["Which ICAO Annex sets the international standards for the rules of the air?", ["Annex 1", "Annex 2", "Annex 11", "Annex 15"], 1, "Annex 2. Annex 1 covers licensing, Annex 11 air traffic services and Annex 15 aeronautical information services."], ["Which CAA publication usually binds the ANO with the assimilated rules of the air?", ["CAP 393", "CAP 413", "CAP 637", "CAP 1535"], 0, "CAP 393. CAP 413 is the radiotelephony guide, CAP 637 the visual aids handbook and CAP 1535 the Skyway Code."], ["Within how many days must a safety departure from the rules be reported in writing?", ["24 hours", "7 days", "10 days", "30 days"], 2, "Ten days, to the competent authority."], ["Two aircraft approach head-on with a danger of collision. What does each do?", ["Climb", "Turn left", "Turn right", "Descend"], 2, "Each turns right."], ["An aircraft is being overtaken. Who has right of way?", ["The overtaking aircraft", "The aircraft being overtaken", "The higher aircraft", "The faster aircraft"], 1, "The aircraft being overtaken. The overtaker keeps clear by turning right."], ["Two aeroplanes converge at about the same altitude. Who gives way?", ["The one with the other on its left", "The one with the other on its right", "The lower one", "The slower one"], 1, "The aircraft that has the other on its right gives way."], ["A power-driven aeroplane converges with a balloon. Who gives way?", ["The balloon", "The aeroplane", "Whichever is lower", "Whichever is slower"], 1, "Power-driven heavier-than-air aircraft give way to airships, sailplanes and balloons."], ["Within what angle of the other aircraft's centreline is an approach treated as overtaking?", ["30°", "70°", "110°", "140°"], 1, "Within 70° of the overtaken aircraft's centreline."], ["Which way do you turn near an aerodrome, unless told otherwise?", ["Right", "Left", "Away from the circuit", "Either way"], 1, "Left, unless ground signals direct otherwise."], ["Where is 'long final' reported on a straight-in approach?", ["2 nm", "4 nm", "8 nm", "10 nm"], 2, "Long final at 8 nm, final at 4 nm."], ["ATC says 'land after'. What does this mean?", ["You are cleared to land", "You decide whether separation is sufficient", "You must go around", "You must hold"], 1, "It is not a landing clearance. The decision is yours, based on whether you judge separation sufficient."], ["Which main navigation light is on the left (port) wing?", ["Green", "Red", "White", "Flashing red"], 1, "Red on the left, green on the right."], ["Through what angle does the white tail light show?", ["70° either side of dead astern", "110° either side of dead ahead", "360°", "180° to the rear"], 0, "70° either side of dead astern. The red and green lights show 110° from dead ahead."], ["You see an approaching aircraft's red light out to your left. What does this suggest?", ["A collision risk", "Your paths will not cross", "It is flying away", "It is a glider"], 1, "Red to red is safe. Red to green is unsafe."], ["A required light fails in flight and cannot be repaired. What must you do?", ["Continue to your destination", "Land as soon as it is safe, unless ATC authorises continuing", "Climb above cloud", "Switch on the landing light"], 1, "Rule 15: land as soon as it is safe unless ATC authorises you to continue."], ["When does night begin in the UK?", ["At sunset", "30 minutes after sunset", "1 hour after sunset", "At the end of civil twilight"], 1, "Night runs from 30 minutes after sunset to 30 minutes before sunrise."], ["What is the minimum height over a congested area?", ["500 ft above the highest obstacle within 150 m", "1,000 ft above the highest fixed object within 600 m", "1,500 ft above the ground", "500 ft above the ground"], 1, "1,000 ft above the highest fixed object within 600 m, and you must be able to land clear in an emergency."], ["Who is responsible for being able to land clear over a congested area?", ["ATC", "The pilot", "The aerodrome", "The CAA"], 1, "The pilot, not ATC."], ["What is the UK daytime 500 ft rule?", ["Not below 500 ft above the ground", "Not closer than 500 ft to any person, vehicle, vessel or structure", "Not below 500 ft over water", "Not within 500 ft of an aerodrome"], 1, "By day, not closer than 500 ft to any person, vehicle, vessel or structure."], ["How close may you take off or land to an open-air assembly of more than 1,000 persons, outside an approved procedure?", ["Not within 150 m", "Not within 500 m", "Not within 1,000 m", "Not within 2,000 m"], 2, "Not within 1,000 m, except at an aerodrome using CAA procedures or an approved site with written permission."], ["Which of these is exempt from the low flying prohibitions?", ["A captive balloon or kite", "Any glider", "Any helicopter", "Any aircraft over water"], 0, "No low flying prohibitions apply to captive balloons and kites. Gliders are exempt only when hill-soaring, and only from the 500 ft rule."], ["How close may a manoeuvring helicopter under the exemption get to people outside the site?", ["20 m", "60 m", "150 m", "500 ft"], 1, "Not closer than 60 m to persons, vessels, vehicles or structures outside the aerodrome or site."], ["Who is ultimately responsible for taking every possible measure to avoid a collision?", ["Air traffic control", "The pilot in command", "The most qualified pilot on board", "The air/ground radio operator"], 1, "The commander (pilot in command), whatever clearance ATC has given. ATC and A/G can help but the duty stays with the commander."], ["When converging, what must the aircraft with right of way do?", ["Maintain heading and height", "Maintain speed and height", "Maintain heading and speed", "Maintain heading, speed and height"], 2, "SERA says heading (course) and speed. Height is not mentioned, which is the usual trap."], ["What is the minimum height over a congested area of a city, town or settlement?", ["300 m (1,000 ft) above the highest obstacle within 300 m", "300 m (1,000 ft) above the highest obstacle within 600 m", "600 m (2,000 ft) above the highest obstacle within 600 m", "150 m (500 ft) above the highest obstacle within 150 m"], 1, "1,000 ft (300 m) above the highest obstacle within 600 m, and high enough to land clear. 500 ft within 150 m is the rule elsewhere."], ["Two aircraft approach to land at the same place. Neither has an emergency and ATC has set no order. Who has priority?", ["The faster aircraft", "The aircraft closest to the threshold", "The lower aircraft", "The lower aircraft, but it must not cut in front of or overtake one on final"], 3, "The lower aircraft, with the caveat that it must not cut in front of or overtake an aircraft on final. The plain 'lower aircraft' option misses that caveat."], ["Which right-of-way order for converging aircraft is correct?", ["Balloons give way to airships and sailplanes", "Sailplanes give way to power-driven aircraft, airships and balloons", "Power-driven aircraft give way to airships, sailplanes and balloons", "Airships give way to power-driven aircraft, sailplanes and balloons"], 2, "The least manoeuvrable has priority: power-driven aircraft give way to airships, sailplanes and balloons; airships to sailplanes and balloons; sailplanes to balloons."], ["At night you see another aircraft's green light on a steady relative bearing of 330°, at a similar level. What should you do?", ["Collision risk: hold your heading and speed", "No risk of collision", "Collision risk: climb or descend", "Collision risk: turn right"], 0, "330° is at your 11 o'clock. Its green light faces your red wing (green to red = unsafe) and the bearing is steady, so there is a risk. It has you on its right, so it gives way: you keep heading and speed."], ["At night you see another aircraft's red light on a steady relative bearing of 030°, at a similar level. What should you do?", ["No action: red means it is moving away", "Collision risk: hold heading and speed", "Collision risk: you give way, normally by turning right to pass behind it", "Collision risk: turn left"], 2, "It is at your 1 o'clock showing red (red to green = unsafe). It is on your right, so you give way, avoiding passing ahead of it. A right turn takes you behind it."], ["At night you see only a steady white light ahead of you, getting closer at your level. What is happening?", ["It is heading straight at you", "You are overtaking it, so you must keep clear by turning right", "It is overtaking you", "It is a balloon, which has right of way"], 1, "A white light alone is the tail light, so it is flying away from you. If it is getting closer you are the overtaker: keep clear and turn right."], ["At night you see both the red and the green light of another aircraft, dead ahead at your level. What do you do?", ["Turn left", "Turn right", "Climb", "Hold heading and speed"], 1, "Seeing both wing lights means it is heading straight at you. Head-on: both aircraft turn right."], ["You are flying an aeroplane and converging with a tug that is towing a glider. Who gives way?", ["The tug, because it is power-driven", "You, because aircraft towing gliders have priority", "Whichever is lower", "The glider, which must release"], 1, "A glider and its tug count as one aircraft. Aeroplanes and helicopters give way to aircraft towing gliders, banners or other objects."], ["A helicopter and an aeroplane converge at about the same altitude, with the aeroplane on the helicopter's right. Who gives way?", ["The aeroplane, because helicopters are more manoeuvrable", "The helicopter", "Whichever is faster", "Both turn right"], 1, "Both are power-driven heavier-than-air, so the same-category rule applies: the aircraft with the other on its right gives way."], ["An aircraft is landing on final, and you are lower but on base leg. What should you do?", ["Turn final ahead of it, as the lower aircraft", "Let it land first; do not cut in front of an aircraft on final", "Climb above it", "Go around immediately"], 1, "The lower aircraft normally has priority, but must never cut in front of or overtake one on final approach."], ["Who may act as the safety pilot during simulated instrument flight?", ["Any passenger with a good view", "A student pilot with at least 20 hours", "A qualified pilot in a control seat with working dual controls", "Anyone, if ATC is informed"], 2, "SERA.3220 needs fully working dual controls and a qualified safety pilot in the other control seat. A student pilot cannot do it."], ["You want to practise an instrument approach in VMC, without screens. What is required?", ["Nothing extra", "Inform ATC and carry a competent observer", "File an IFR flight plan", "Carry a qualified instructor"], 1, "Inform ATC and carry a competent observer."], ["Where may aerobatics not be flown?", ["Inside an ATZ", "Over a congested area", "Above 5,000 ft", "Over the sea"], 1, "Not over a congested area. In controlled airspace you need the controlling authority's approval."], ["You meet severe windshear on approach. What must you do?", ["Note it in the tech log after landing", "Report it to ATC as soon as possible", "Report it to the CAA within 10 days", "Nothing, unless you go around"], 1, "Report hazardous conditions to ATC as soon as possible so they can warn others."], ["You are being intercepted. Which squawk do you select?", ["7000", "7500", "7600", "7700"], 3, "7700, unless the ATS unit tells you otherwise. 7500 is unlawful interference and 7600 radio failure."], ["On which frequency do you try to contact the intercepting aircraft?", ["121.50 MHz", "123.45 MHz", "118.00 MHz", "Your current ATC frequency only"], 0, "121.50 MHz, giving your callsign and the nature of your flight."], ["The interceptor rocks its wings from slightly above and ahead, then makes a slow level turn to the left. What does it mean, and how do you reply?", ["You may proceed; rock your wings", "Follow me; rock your wings and follow", "Land here; lower your gear", "You are in distress; flash your lights"], 1, "That is \"follow me\". Rock your wings and follow immediately (at night, also flash your navigation lights at irregular intervals)."], ["The interceptor makes an abrupt break-away climbing turn of 90° or more without crossing your flight path. What does it mean?", ["Follow me", "Land at this aerodrome", "You may proceed", "Change frequency"], 2, "You may proceed. Rock your wings to acknowledge."], ["The interceptor circles an aerodrome, lowers its gear and overflies the runway. What should you do?", ["Continue on your planned route", "Lower your gear if possible, follow it and land if it looks safe", "Circle at 2,000 ft", "Squawk 7600"], 1, "It means \"land at this aerodrome\". Lower your gear, follow, and land if, after overflying the runway, you judge it safe."], ["How do you tell an interceptor that the aerodrome it has chosen is inadequate?", ["Rock your wings", "Flash all lights at irregular intervals", "Raise your gear while passing over the runway between 1,000 and 2,000 ft above aerodrome level, and keep circling", "Use a hand signal"], 2, "Raise gear (if possible) over the runway between 1,000 and 2,000 ft above aerodrome level and keep circling. Avoid hand signals."], ["You switch all your lights on and off at regular intervals. What are you telling the interceptor?", ["I am in distress", "I cannot comply", "Understood, will comply", "I am lost"], 1, "Regular = cannot comply. Irregular = distress."], ["ATC tells you to turn right, but the intercepting aircraft is signalling you to follow it left. What do you do?", ["Follow ATC, since you are on their frequency", "Follow the interceptor's visual instructions and ask for clarification", "Hold your heading until it is resolved", "Squawk 7600"], 1, "Request clarification at once, but obey the interceptor's visual instructions."], ["In the interception phrases, what does \"CAN NOT\" mean?", ["Repeat your instruction", "Unable to comply", "Position unknown", "I require descent"], 1, "CAN NOT = unable to comply. REPEAT, AM LOST and DESCEND are the others."], ["By day you see projectiles fired from the ground every 10 seconds, bursting into red and green stars. What does it mean?", ["Cleared to land", "You are in or about to enter a restricted, prohibited or danger area", "Return to the aerodrome", "A display is in progress"], 1, "It warns an unauthorised aircraft that it is in, or about to enter, a restricted, prohibited or danger area. Take remedial action."], ["Where are the interception procedures you must carry on international flights published?", ["AIP GEN 1.7", "AIP ENR 1.12", "AIP AD 2", "CAP 413"], 1, "AIP ENR 1.12. GEN 1.7 lists UK differences from ICAO."]]});
Object.assign(SUM,{"SERA and the UK rules of the air": "SERA applies ICAO Annex 2 standards across the EU; since Brexit the UK applies them as assimilated law, with its own supplementary rules in the ANO and CAP 393.", "Scope and departures from the rules": "The rules cover all aircraft in the UK and UK-registered aircraft anywhere; you may depart from them to avoid immediate danger, then report within 10 days.", "Collision avoidance (SERA.3201)": "The commander is always responsible for avoiding collisions; the aircraft giving way keeps well clear and the one with right of way holds course and speed.", "Right of way (SERA.3210)": "Head-on, both turn right; the overtaker keeps clear by turning right; when converging, give way to the less manoeuvrable category, or to the aircraft on your right.", "Flights near an aerodrome (SERA.3225)": "Follow or stay clear of the traffic pattern and turn left, unless told otherwise.", "Order of landing and take-off (Rules 9 and 10)": "The lower aircraft, or the one on final, has priority; land and take off into wind, and 'land after' is not a clearance.", "Radio in the ATZ and the right-hand traffic rule": "Keep radio contact in an ATZ; keeping line features on your left is now only a recommendation.", "Lights on aircraft (Rule 14, SERA.3215)": "Green on the right wing, red on the left, white at the tail, plus a red anti-collision light; a failed light means landing as soon as safe, and UK night starts 30 minutes after sunset.", "Low flying prohibitions (SERA.3105 and .5005(f))": "1,000 ft over congested areas and 500 ft elsewhere, with different UK and EASA wording; being able to land clear is the pilot's job.", "Open-air assemblies": "Stay above the 1,000 ft or land-clear height over assemblies, and keep take-off and landing 1,000 m away unless an approved procedure applies.", "Exceptions to the low flying prohibitions": "Take-off, landing, special VFR, displays, hill-soaring and similar activities have defined exemptions from the 500 ft and 1,000 ft rules.", "Other rules: hazards, aerobatics and instrument practice": "Report hazards to ATC at once, no aerobatics over congested areas, a qualified safety pilot for simulated IF and a competent observer for practice approaches.", "Interception: what to do (AIP ENR 1.12)": "Follow the interceptor, call on 121.50 MHz, squawk 7700, and obey its visual signals over any conflicting instruction.", "Interception signals": "Rock your wings to say understood; regular light flashing means cannot comply, irregular means distress.", "Interception radio phrases and ground signals": "Short standard phrases (WILCO, CAN NOT, AM LOST) when there is no common language; red and green stars every 10 seconds warn you off a restricted area."});
NOTES.push({"s": 0, "topic": "Aerodromes", "num": 4, "order": 40, "conf": "weak", "status": "draft", "summary": "Aerodromes are listed in AIP AD. Get prior permission (PPR) before you go; tell your destination if you divert or will be 45 minutes or more late. Green Morse beacons mark civil aerodromes, red military. On the ground give way to landing traffic, turn right head-on, give way to traffic on your right. Declared distances: TORA, TODA (plus clearway), ASDA (plus stopway), LDA. Runway markings are white, taxiway yellow; threshold lights green, end lights red. Learn the signals-area symbols, holding point lines (broken side towards the runway), displaced thresholds, ATC light signals in flight and on the ground, and the main marshalling signals.", "sections": [["What an aerodrome is", ["An <b>aerodrome</b> is any area of land or water used for aircraft to take off and land", "Aerodromes fall into categories depending on their use", "The <b>AD</b> (Aerodromes) section of the UK <b>AIP</b> holds the aerodrome directory: physical characteristics, local hazards and flying restrictions"]], ["Prior permission (PPR) and limits on use", ["<b>Military</b> aerodromes and civil aerodromes with an <b>ordinary licence</b>: prior permission to land from the aerodrome authority", "<b>Unlicensed</b> aerodromes: permission from the <b>owner or person in charge</b>", "<b>PPR</b> = prior permission required. Contact the operator or owner <b>before departure</b>, especially if no radio frequency is published", "Landing without PPR is trespass. You may also miss safety information: a strip usable only one way or in certain winds, waterlogging, noise abatement procedures", "Ignoring PPR can lead to an accident and the insurer refusing to pay, because you breached the ANO", "Military aerodromes: PPR always before departure, and expect to need higher insurance cover", "Civil use of military aerodromes is limited to their <b>normal hours of watch</b> and to aircraft on <b>inland</b> flights; some also limit the class of traffic (scheduled, charter or private)", "None of these restrictions apply in an <b>in-flight emergency</b>. Aerodromes not listed in AIP AD may be used in an emergency or with the owner's or operator's permission"]], ["ANO rules at aerodromes: instruction, fuel, arrival and customs", ["<b>Flying instruction</b> (Article 209): at an unlicensed (or non-certified) aerodrome, instruction towards a pilot's licence or a flight test for one needs the operator to be satisfied the facilities are adequate, and the commander must not take off unless they are also satisfied", "<b>Fuel</b> (Article 220): never use fuel you know or suspect is unfit; aerodrome fuel must be stored and sampled as the rules require", "Avgas equipment at aerodromes is usually marked in <b>red</b>", "<b>Arrival</b>: if you are expected somewhere, tell that aerodrome as soon as possible if you change destination or will be <code>45 minutes</code> or more late, to avoid needless overdue action", "Where possible, report to the aerodrome authority on arrival and before departure", "<b>Customs</b> airports for international flights, with hours and special requirements, are listed in the <b>GEN</b> section of the AIP"]], ["Security (ICAO Annex 17)", ["<b>Annex 17</b> covers aviation security", "Aims: prevent unlawful interference with civil aviation, keep people safe, protect passengers and staff, and respond rapidly to any increased threat", "Know the local security arrangements where you fly. Security is everyone's responsibility"]], ["Aeronautical light beacons", ["Fitted at various civil and military aerodromes. Expect them on at night, and by day in poor visibility, whenever the aerodrome is operating", "<b>Identification beacon</b>: flashes a two-letter Morse group every <code>12 seconds</code>, <b>green</b> at civil aerodromes and <b>red</b> at military ones", "<b>Aerodrome beacon</b>: alternating flashes, usually <b>white/white</b>, less often <b>white/green</b>", "An aerodrome beacon is not normally provided as well as an identification beacon"]], ["Moving on the aerodrome (Rules 12 and 13)", ["Do not taxi on the apron or manoeuvring area without the aerodrome authority's permission", "<b>Manoeuvring area</b>: the part used for take-off, landing and taxiing, <b>excluding</b> aprons and maintenance areas", "<b>Apron</b>: the paved area for loading and unloading, turn-rounds, maintenance and repair, and other approved uses that are not flight operations", "Nobody may go onto any part of an aerodrome provided for aircraft without permission, unless it is a public right of way"]], ["Right of way on the ground (SERA.3210)", ["Whatever ATC has cleared, the commander must do everything possible to avoid colliding with other aircraft, vehicles or obstacles. The onus is on you", "If an aircraft is being towed with its commander not on board, that duty falls on the person in charge of the towing vehicle", "Aircraft on the ground give way to aircraft <b>taking off or landing</b>", "<b>Head-on</b>: each turns <b>right</b>", "<b>Converging</b>: the aircraft with the other on its <b>right</b> gives way, and does not cross ahead unless well clear (stop, or pass behind)", "<b>Overtaking</b>: the aircraft being overtaken has right of way; the overtaker keeps out of the way until past and well clear (your textbook: keep clear on the <b>left</b> of it, so its pilot can see you)"]], ["Aerodrome Traffic Zones (ATZs)", ["Airspace around most UK aerodromes is designated an <b>Aerodrome Traffic Zone</b>, usually because of the amount of flying there", "In an ATZ, keep radio (or other) contact with the aerodrome unit: ATC, AFIS or Air/Ground (see Rules of the Air)", "The dimensions of an ATZ and the airspace around it are in the Airspace topic"]], ["Declared distances (TORA, TODA, ASDA, LDA)", ["Declared distances are agreed by the relevant authority (the <b>CAA</b> in the UK) and published in the AD section of the AIP", "<b>TORA</b> (take-off run available): the runway length declared available and suitable for the <b>ground run</b> of an aeroplane taking off", "<b>TODA</b> (take-off distance available): TORA <b>plus the clearway</b>, if there is one", "<b>ASDA</b> (accelerate-stop distance available): TORA <b>plus the stopway</b>, if there is one. No stopway: ASDA = TORA", "<b>LDA</b> (landing distance available): the runway length declared available and suitable for the ground run of an aeroplane <b>landing</b>. A displaced threshold shortens it", "Trap: clearway goes with TODA (it is airspace you climb over), stopway goes with ASDA (it is ground you can stop on)"]], ["Aerodrome standards (ICAO Annex 14)", ["<b>Annex 14</b> sets ICAO's standards and recommended practices for aerodromes: physical characteristics, layout, equipment, people and procedures", "Contracting states try to conform to them under the <b>Chicago Convention</b>", "Worth reading: <b>CAP 637</b> (Visual Aids Handbook) and <b>CAP 1535</b> (the Skyway Code)"]], ["Runway surface condition (GRF and SNOWTAM)", ["The <b>Global Reporting Format (GRF)</b> gives pilots runway surface conditions in one standard format worldwide", "<b>Dry</b>: no visible moisture and not contaminated in the area to be used", "<b>Wet</b>: any visible dampness or water up to and including <code>3 mm</code> deep", "<b>Slippery wet</b>: a wet runway where friction over a significant part has been found to be degraded", "<b>Contaminated</b>: a significant part of the surface in use is covered by one of the eight contaminants: compacted snow, dry snow, frost, ice, slush, standing water, wet ice, wet snow", "Reported for <b>each third</b> of the runway. A runway is contaminated when <b>more than a quarter</b> of at least one third is covered", "For each third: a <b>runway condition code</b> from <code>0</code> (worst) to <code>6</code> (best), coverage (<code>25</code>, <code>50</code>, <code>75</code> or <code>100</code>%), depth in mm, and a description", "Used <b>all year</b>: a <b>SNOWTAM</b> (a special NOTAM) reports or cancels hazardous snow, ice, slush <b>or standing water</b>, even with no winter weather", "Reading a SNOWTAM, e.g. <code>EGGP 03150045 09 2/5/5 50/75/75 04/NR/NR SLUSH/WET/WET</code>: aerodrome; assessed 15 March 00:45 (MMDDhhmm); the <b>lower</b> runway number (09, so the report also covers 27 in use); codes, coverage %, depth (NR = not reported) and description for each third"]], ["Indicators, markings and signs (Annex 14 ch. 5)", ["Every aerodrome has <b>at least one wind direction indicator</b>, visible from aircraft in flight and on the movement area, and sited clear of disturbed air from nearby objects", "A <b>landing direction indicator</b>, if provided, sits in a conspicuous place", "Runway markings are <b>white</b>. Taxiway and aircraft stand markings are <b>yellow</b>", "<b>Mandatory instruction signs</b> are <b>white on a red background</b>"]], ["Runway lights (Annex 14 5.3)", ["<b>Threshold</b> and <b>wingbar</b> lights: fixed, unidirectional, <b>green</b> towards the approach", "A runway with edge lights also has <b>runway end lights</b>, ideally at least <code>6</code>", "End lights sit at right angles to the runway, as near the end as possible and no more than <code>3 m</code> outside it", "End lights are fixed, unidirectional, showing <b>red</b> along the runway (towards an aircraft rolling towards them)", "Trap: green threshold lights face the <b>approach</b>, not the runway; the red end lights face the runway"]], ["Obstacle lights and marking (Annex 14 6.3)", ["Low-intensity obstacle lights on vehicles: <b>flashing yellow</b> (emergency and security vehicles excepted)", "High-intensity obstacle lights: <b>flashing white</b>", "Obstacles within <code>15 km</code> of an aerodrome are normally lit at night", "A fixed obstacle <code>45 m</code> or less in height, width and length: a single <b>steady red</b> light on its highest point. Larger ones get extra red lights outlining them", "Obstacles hard to see by day are painted in alternating bands or a chequered pattern of <b>red or orange and white</b>"]], ["Signals area: direction and surfaces", ["Some aerodromes have a <b>signals area</b> near the tower, for messages without radio: signals laid on the ground are read <b>in flight</b>; signals hoisted on a mast are read <b>on the ground</b>", "<b>White T</b>: take off and land parallel with the shaft, <b>towards the cross-arm</b> (into wind), unless ATC authorise otherwise", "<b>White disc</b> at the head of the T: the directions of landing and take-off <b>do not necessarily coincide</b>. A <b>black ball</b> on the mast means the same", "<b>White dumb-bell</b>: on the ground, keep to paved, metalled or similar hard surfaces", "Dumb-bell with a <b>black strip</b> across each disc: take off and land <b>on a runway</b>, but other ground movement is not confined to hard surfaces", "Dumb-bell with a <b>red L</b>: light aircraft may take off and land on a runway or on the area marked by a <b>white L</b>"]], ["Signals area: circuit direction and warnings", ["<b>Red and yellow striped arrow</b>, bent through 90° round the edge of the signals area and pointing clockwise: turns before landing and after take-off are to the <b>right</b>", "Variable circuit: a rectangular <b>red flag</b> on the mast = <b>left-hand</b> circuit, <b>green flag</b> = <b>right-hand</b> (the same as navigation lights: red port, green starboard)", "<b>Red square with one yellow diagonal</b>: the manoeuvring area is in poor state; take special care approaching and landing", "<b>Red square with a yellow diagonal cross</b>: landing is <b>prohibited</b>, and likely to stay so", "<b>White H</b>: helicopters take off and land only in the designated area (marked by a much larger white H)", "<b>Double white cross</b> and/or <b>two red balls</b> on the mast, one above the other: <b>glider flying</b> is taking place. A much larger double cross marks an area for gliders only", "<b>Yellow cross</b>: the tow-rope dropping area. Tow-ropes, banners and the like are picked up or dropped only at an aerodrome, as the aerodrome authority directs, or in that area flying in the landing direction"]], ["Signals on paved runways and taxiways", ["Two or more <b>crosses</b>, arms at <code>45°</code> to the centreline, no more than <code>300 m</code> apart: that section is <b>unfit</b> for aircraft. <b>White</b> on a runway, <b>yellow</b> on a taxiway", "<b>Orange and white markers</b> no more than <code>15 m</code> apart mark the boundary of an unfit part of a paved runway, taxiway or apron (a base board with a slatted upright board, striped orange-white-orange)", "<b>Holding point</b>: parallel yellow lines across the taxiway, usually two continuous and two broken. No part of an aircraft or vehicle goes beyond them towards the runway without <b>ATC permission</b>", "The <b>broken</b> lines are on the <b>runway side</b>. Coming off the runway you meet the broken lines first, and need no clearance to cross", "Older holding points may be white, or one continuous and one broken line"]], ["Markers on unpaved manoeuvring areas", ["<b>Aerodrome boundary</b>: orange and white striped <b>wedge-shaped</b> markers (like long wheel chocks) no more than <code>45 m</code> apart, with flat orange and white markers on structures on the boundary", "<b>Unserviceable unpaved area</b>: the same wedges alternating with square <b>flags</b> of orange and white triangles; the bad ground inside is marked with white crosses", "<b>Unpaved runway or stopway boundary</b>: flat white rectangles, flush with the surface, no more than <code>90 m</code> apart", "A <b>stopway</b> is a prepared rectangle beyond the runway end, in the take-off direction, where an aircraft can stop after an abandoned take-off", "<b>White L</b>: part of the manoeuvring area for light aircraft only", "<b>White T</b> on the <b>left</b> of a runway (seen from the landing direction): the runway to be used. With no runway, it gives the take-off and landing direction", "<b>White cross at each end</b> of a runway: landing is dangerous and the aerodrome is for <b>storage only</b>", "<b>White cross and a single white bar</b> at each end, at a <b>disused</b> aerodrome: fit for <b>emergency use only</b>. Such runways are not safeguarded and may be obstructed"]], ["Displaced thresholds", ["The threshold marks the start of the usable runway for landing. It is normally <b>piano keys</b>; the runway number is the direction rounded to the nearest 10° (<code>09</code> = 090°)", "A threshold may be displaced up the runway, <b>temporarily</b> (e.g. works) or <b>permanently</b>", "Permanent, <b>arrows</b> before the threshold: the pre-threshold area may be used to <b>taxi and take off</b>, but <b>not to land</b>", "Permanent, <b>crosses</b> before the threshold: the area is <b>unfit</b> for any aircraft movement and unsuitable as a stopway", "Temporary: <b>chevrons</b> are added, with arrows (taxi and take-off, not landing) or crosses (unfit)", "Rule of thumb: arrows = you may roll on it; crosses = keep off it; never land short of the threshold bar"]], ["Signals seen only on the ground", ["<b>Black ball</b> on the mast: take-off and landing directions are not necessarily the same", "<b>Two red balls</b> on the mast: gliding in progress", "Rectangular <b>red and yellow chequered</b> flag or board: aircraft may move on the manoeuvring area and apron <b>only with ATC permission</b>", "Variable circuit: <b>red flag</b> = left-hand, <b>green flag</b> = right-hand", "Away from the signals area: a <b>black C on a yellow board</b> marks where to <b>report to ATC</b> or the aerodrome authority"]], ["Light signals from ATC", ["The same light means different things <b>in flight</b> and <b>on the ground</b>", "<b>Steady green</b>: in flight, cleared to land; on the ground, cleared to take off (in both cases if you are satisfied there is no risk of collision)", "<b>Flashing green</b>: in flight, return to this aerodrome and wait for permission to land; on the ground, cleared to taxi on the manoeuvring area (if no collision risk)", "<b>Steady red</b>: in flight, give way to other aircraft and continue circling; on the ground, <b>stop</b>", "<b>Flashing red</b>: in flight, do not land, the aerodrome is not available (go elsewhere); on the ground, move clear of the landing area", "<b>Red flare</b> (from the ground): do not land for the time being, wait for permission, whatever earlier instructions said", "<b>Flashing white</b>: in flight, land here after a steady green, then await further instructions; on the ground, return to your starting point on the aerodrome", "Trap: a steady green on the ground is take-off, not taxi; a flashing green is taxi"]], ["Light signals from aircraft", ["Pyrotechnics are rarely carried. The signal nearly any aircraft can make is switching the landing or navigation lights on and off (usually visible only at night)", "<b>Flashing landing and/or navigation lights</b>: I am compelled to land", "<b>Red flare</b>: immediate assistance required", "<b>Green flare</b>: by night, may I land? By day, may I land in a different direction from the one the landing T shows?"]], ["Marshalling signals: marshaller to pilot", ["<b>Move ahead</b>: arms repeatedly moved upward and backward, beckoning", "<b>Turn to port</b> (open up starboard engine): right arm down, left arm beckoning. <b>Turn to starboard</b>: left arm down, right arm beckoning. The faster the arm, the tighter the turn", "<b>Stop</b>: arms repeatedly crossed above the head; speed shows urgency", "<b>Slow down</b>: arms down, palms to the ground, moved up and down. One arm only: slow the engines on that side", "<b>Start engine</b>: circular motion of the right hand at head level, the left arm pointing to (or the left hand's fingers showing) the engine", "<b>Cut engines</b>: arm and hand level with the chest, moved sideways, palm down", "<b>Chocks inserted</b>: arms out, palms in, swung inwards. <b>Chocks away</b>: arms down, palms out, swung outwards", "<b>Engage brakes</b>: hand raised in front of the body, fingers out, then fist clenched. <b>Release brakes</b>: fist raised, then fingers extended", "<b>This bay</b>: arms vertical above the head. <b>Proceed to the next marshaller</b>: one arm down, the other across the body pointing to them", "<b>All clear, marshalling finished</b>: right arm raised at the elbow, palm forward", "<b>Back the tail</b> to starboard or port: one arm pointing down, the other repeatedly brought down from overhead to horizontal forward"]], ["Marshalling signals: helicopters", ["<b>Hover</b>: arms horizontal out to the sides", "<b>Land</b>: arms down and crossed in front of the body", "<b>Move upwards</b> / <b>downwards</b>: arms out to the sides, palms up beckoning up, or palms down beckoning down; speed shows the rate", "<b>Move horizontally</b>: one arm out to the side, the other swept across the body towards it, repeated", "<b>Move back</b>: arms down, palms forward, swept up to shoulder level and back down", "<b>Release load</b>: left arm forward horizontally, right arm slicing horizontally below it"]], ["Signals from pilot to marshaller", ["<b>Brakes engaged</b>: hand raised in front of the face, fingers out, then fist clenched. <b>Brakes released</b>: fist raised, then fingers extended", "<b>Insert chocks</b>: arms out, palms out, hands moved in to cross in front of the face. <b>Remove chocks</b>: hands crossed in front of the face, moved outwards", "<b>Ready to start</b>: hold up the number of fingers for the engine to be started", "Engines are numbered from the <b>marshaller's right to left</b> as they face the aircraft: No. 1 port outer, No. 2 port inner, No. 3 starboard inner, No. 4 starboard outer"]], ["Emergency hand signals", ["Used by the fire and rescue service to the flight crew. At night the same signals are made with wands", "<b>Recommend evacuation</b>: one arm out horizontally, hand at eye level, beckoning backwards; the other arm against the body", "<b>Recommend stop</b> (halt the evacuation or movement): arms in front of the head, crossed at the wrists", "<b>Emergency contained</b> (all clear, nothing dangerous seen outside): arms out and down at 45°, brought in to cross below the waist, then out again", "<b>Fire</b>: right hand fanning from shoulder to knee while the left hand points at the fire"]]], "cards": [["Which AIP section is the aerodrome directory?", "AD (Aerodromes): characteristics, local hazards and restrictions."], ["Who gives permission to land at a military or ordinary-licence aerodrome?", "The aerodrome authority (prior permission, PPR)."], ["Who gives permission to land at an unlicensed aerodrome?", "The owner or person in charge."], ["When should you get PPR?", "Before departure, especially if no radio frequency is published."], ["Two consequences of landing without PPR?", "It is trespass, and an insurer may refuse a claim because you breached the ANO (plus you miss safety information)."], ["What limits civil use of military aerodromes?", "Normal hours of watch and inland flights only; some limit the class of traffic. Not in an emergency."], ["Can you land at an aerodrome not in AIP AD?", "Yes, in an emergency or with the owner's or operator's permission."], ["Flying instruction at an unlicensed aerodrome: who must be satisfied?", "The operator that the facilities are adequate, and the commander before take-off (Article 209)."], ["What does Article 220 say about fuel?", "Do not use fuel you know or suspect is unfit; it must be stored and sampled as required."], ["What colour marks Avgas equipment?", "Red, usually."], ["When must you tell your destination you are late?", "As soon as possible if you will be 45 minutes or more late, or change destination."], ["Where are customs airports listed?", "AIP GEN, with hours and special requirements."], ["Which ICAO Annex covers security?", "Annex 17."], ["Green Morse identification beacon?", "Civil aerodrome: two-letter group every 12 seconds."], ["Red Morse identification beacon?", "Military aerodrome: two-letter group every 12 seconds."], ["Alternating white/white or white/green flashes?", "An aerodrome beacon (civil)."], ["When are light beacons usually on?", "At night, and by day in poor visibility, while the aerodrome is operating."], ["Manoeuvring area vs apron?", "Manoeuvring area: take-off, landing and taxiing (no aprons). Apron: loading, turn-rounds and maintenance."], ["What do you need before taxiing on the apron or manoeuvring area?", "The aerodrome authority's permission."], ["On the ground, who gives way to aircraft taking off or landing?", "Everyone on the ground."], ["Two aircraft taxi head-on. What does each do?", "Turn right."], ["Converging while taxiing: who gives way?", "The one with the other on its right: stop or pass behind."], ["Overtaking while taxiing: who has right of way?", "The aircraft being overtaken. The overtaker keeps clear until past and well clear."], ["Why is an ATZ established?", "Usually because of the amount of flying around the aerodrome."], ["What does TORA mean?", "Take-off run available: runway declared suitable for the ground run of a take-off."], ["TODA = ?", "TORA plus clearway (if provided)."], ["ASDA = ?", "TORA plus stopway (if provided). No stopway: ASDA = TORA."], ["What is LDA?", "Landing distance available: runway declared suitable for the landing ground run."], ["What is a stopway?", "A prepared area beyond the runway end, in the take-off direction, for stopping after an abandoned take-off."], ["Which Annex covers aerodromes?", "ICAO Annex 14."], ["Wet runway: how deep can the water be?", "Up to and including 3 mm."], ["When is a runway third reported as contaminated?", "When more than 25% of it is covered by a contaminant."], ["Runway condition code range?", "0 (worst) to 6 (best), one for each runway third."], ["What carries GRF runway reports, even for standing water?", "A SNOWTAM."], ["Which runway number does a SNOWTAM give?", "The lower one (09 for runway 09/27)."], ["Colour of runway and taxiway markings?", "Runway white, taxiway and stand markings yellow."], ["Colour of mandatory instruction signs?", "White on a red background."], ["Threshold lights?", "Fixed, unidirectional, green towards the approach."], ["Runway end lights?", "Fixed, unidirectional, red towards the runway; ideally at least six, no more than 3 m beyond the end."], ["Obstacle light on a vehicle (not emergency)?", "Flashing yellow (low intensity)."], ["Small obstacle (45 m or less) lit how?", "A single steady red light on its highest point."], ["White T in the signals area?", "Take off and land parallel with the shaft, towards the cross-arm."], ["White disc at the head of the T (or black ball on the mast)?", "Landing and take-off directions do not necessarily coincide."], ["White dumb-bell?", "Keep to hard surfaces on the ground."], ["Dumb-bell with black strips across the discs?", "Take off and land on a runway; other ground movement need not be on hard surfaces."], ["Red and yellow striped arrow bent clockwise?", "Right-hand circuit."], ["Red flag / green flag on the signals mast?", "Left-hand circuit / right-hand circuit."], ["Red square, one yellow diagonal?", "Manoeuvring area in poor state: take special care landing."], ["Red square, yellow diagonal cross?", "Landing prohibited, likely for a long time."], ["Double white cross or two red balls?", "Glider flying in progress."], ["Yellow cross on the aerodrome?", "Tow-rope dropping area."], ["Crosses on a runway (white) or taxiway (yellow)?", "That section is unfit for aircraft; crosses no more than 300 m apart."], ["Holding point: which lines face the runway?", "The broken lines."], ["Orange and white wedges 45 m apart?", "Aerodrome boundary (unpaved)."], ["Flat white rectangles 90 m apart?", "Boundary of an unpaved runway or stopway."], ["White cross at each end of a runway?", "Landing dangerous; storage only."], ["White cross plus a white bar at each end?", "Disused aerodrome: emergency use only."], ["Arrows before a displaced threshold?", "Pre-threshold area usable for taxi and take-off, not landing."], ["Crosses before a displaced threshold?", "Pre-threshold area unfit for any movement."], ["Red and yellow chequered flag or board?", "Move on the manoeuvring area and apron only with ATC permission."], ["Black C on a yellow board?", "Where to report to ATC or the aerodrome authority."], ["Steady green: in flight / on the ground?", "Cleared to land / cleared to take off."], ["Flashing green: in flight / on the ground?", "Return and wait for permission to land / cleared to taxi."], ["Steady red: in flight / on the ground?", "Give way and keep circling / stop."], ["Flashing red: in flight / on the ground?", "Do not land, aerodrome not available / move clear of the landing area."], ["Flashing white: in flight / on the ground?", "Land here after a steady green, then await instructions / return to starting point."], ["Aircraft flashing its landing or nav lights?", "I am compelled to land."], ["Green flare from an aircraft by day?", "May I land in a different direction from the landing T?"], ["Marshaller: arms repeatedly crossed above the head?", "Stop (speed shows urgency)."], ["Marshaller: right arm raised at the elbow, palm forward?", "All clear, marshalling finished."], ["How are engines numbered for the marshaller?", "From the marshaller's right to left: No. 1 port outer to No. 4 starboard outer."], ["Emergency signal: arms crossed at the wrists in front of the head?", "Recommend stop."]], "quiz": [["At a civil aerodrome, what does the identification beacon show?", ["A green two-letter Morse group every 12 seconds", "A red two-letter Morse group every 12 seconds", "Alternating white and green flashes", "A green two-letter Morse group every 10 seconds"], 0, "Green Morse every 12 seconds is civil. Red is military, and alternating white/green is an aerodrome beacon, not an identification beacon."], ["You see a red two-letter Morse group flashed from the ground. What is it?", ["A civil aerodrome identification beacon", "A military aerodrome identification beacon", "A warning that you are entering a danger area", "An aerodrome beacon"], 1, "Red Morse identifiers are military; civil ones are green. Danger-area warnings are red and green stars fired every 10 seconds."], ["What does an aerodrome beacon usually show?", ["A green Morse group", "Alternating white/white or white/green flashes", "A steady red light", "Alternating red/green flashes"], 1, "Usually white/white, less often white/green. It is not normally fitted as well as an identification beacon."], ["How often does an identification beacon flash its Morse group?", ["Every 6 seconds", "Every 10 seconds", "Every 12 seconds", "Every 15 seconds"], 2, "Every 12 seconds. The 10-second interval belongs to the red and green warning stars."], ["You are expected at another aerodrome. When must you tell them you are running late?", ["If you will be 15 minutes or more late", "If you will be 30 minutes or more late", "If you will be 45 minutes or more late", "Only if you change destination"], 2, "Forty-five minutes or more, or any change of destination, as soon as possible, so nobody starts overdue action."], ["Who gives permission to land at an unlicensed aerodrome?", ["The CAA", "The nearest ATC unit", "The owner or person in charge", "No permission is needed"], 2, "The owner or person in charge. At military and ordinary-licence aerodromes it is the aerodrome authority."], ["When should you get PPR?", ["On first radio contact", "Before departure", "Within the ATZ", "After landing"], 1, "Before you set off, especially where no radio frequency is published."], ["Civil use of a military aerodrome is normally restricted to:", ["Its normal hours of watch and aircraft on inland flights", "Any time, with PPR", "International flights only", "Aircraft with a radio"], 0, "Normal hours of watch and inland flights, sometimes also by class of traffic. These limits do not apply in an emergency."], ["Can you land at an aerodrome that is not listed in AIP AD?", ["Never", "Only if it is licensed", "In an emergency, or with the owner's or operator's permission", "Only with CAA permission"], 2, "Yes, in an emergency or with the owner's or operator's permission."], ["Before flying instruction towards a licence at an unlicensed aerodrome, who must be satisfied that the facilities are adequate?", ["The CAA", "The aerodrome operator only", "Both the aerodrome operator and the commander", "The student's instructor only"], 2, "Article 209: the operator must be satisfied, and the commander must not take off unless they are too."], ["What colour is Avgas equipment at aerodromes usually marked?", ["Black", "Red", "Green", "Yellow"], 1, "Red. Black is the usual marking for Jet A-1, a common trap."], ["Where are the UK customs airports for international flights listed?", ["AIP AD", "AIP ENR", "AIP GEN", "An AIC"], 2, "AIP GEN, with hours of attendance and special requirements."], ["Which ICAO Annex covers aviation security?", ["Annex 2", "Annex 11", "Annex 14", "Annex 17"], 3, "Annex 17. Annex 2 is rules of the air, Annex 11 air traffic services, Annex 14 aerodromes."], ["What is the manoeuvring area of an aerodrome?", ["The part used for take-off, landing and taxiing, excluding aprons", "The runways only", "The aprons and maintenance areas", "The whole aerodrome including aprons"], 0, "Take-off, landing and taxiing, but not aprons or maintenance areas. Add the aprons and you have the movement area."], ["What is an apron used for?", ["Take-off and landing", "Loading, unloading, turn-rounds and maintenance", "Holding before entering the runway", "Engine run-ups only"], 1, "Aprons are for loading, unloading, turn-rounds, maintenance and repair: anything other than flight operations."], ["You are taxiing and an aircraft is landing. Who gives way?", ["The landing aircraft", "You", "Whichever is on the other's right", "Whoever ATC cleared first"], 1, "Aircraft on the ground give way to those taking off or landing."], ["Two aircraft are taxiing head-on. What does each do?", ["Stop", "Turn left", "Turn right", "The one on the taxiway centreline holds course"], 2, "Each turns right, the same as in the air."], ["You are taxiing and another aircraft converges from your right. What do you do?", ["Continue: you have right of way", "Give way, stopping or passing behind it", "Cross ahead quickly", "Turn left"], 1, "It is on your right, so you give way and avoid crossing ahead unless well clear."], ["You are taxiing faster than an aircraft ahead of you on the same taxiway. Who has right of way?", ["You, as the faster aircraft", "The aircraft being overtaken", "Whichever ATC names", "Neither: both stop"], 1, "The aircraft being overtaken. As the overtaker you keep out of the way until past and well clear."], ["ATC has cleared you to taxi, but a vehicle pulls out ahead. Whose duty is it to avoid a collision?", ["ATC's, because they cleared you", "The vehicle driver's", "Yours, as commander", "Whoever is on the other's right"], 2, "Regardless of any ATC clearance, the commander must do everything possible to avoid a collision on the ground."], ["Whose permission do you need to taxi on an apron?", ["The CAA's", "The aerodrome authority's", "The aircraft owner's", "None"], 1, "The aerodrome authority's permission is needed for the apron and the manoeuvring area (Rule 12)."], ["Apart from trespass, what risk do you run by landing without PPR?", ["None", "Your insurer may refuse a claim because you breached the ANO", "Automatic licence suspension", "A landing fee surcharge only"], 1, "You may miss safety information and, after an accident, the insurer may refuse to pay because you breached the ANO."], ["You told your destination you were coming. You are now running 50 minutes late. What must you do?", ["Tell that aerodrome as soon as possible", "Nothing, unless the delay reaches 60 minutes", "Nothing, unless you change destination", "Tell them on arrival"], 0, "Tell them as soon as possible if you change destination or will be 45 minutes or more late, so they do not start overdue action. 60 and 30 minutes are the usual distractors."], ["Which is the take-off run available (TORA)?", ["The runway declared suitable for the ground run of an aeroplane taking off", "The runway declared suitable for the take-off ground run, plus any clearway", "The runway plus stopway", "The clearway and stopway together"], 0, "TORA is the ground-run length only. Adding the clearway gives TODA; adding the stopway gives ASDA."], ["Which declared distance includes the clearway?", ["TORA", "TODA", "ASDA", "LDA"], 1, "TODA = TORA + clearway. The stopway belongs to ASDA, not TODA."], ["A runway has no stopway. What is its ASDA?", ["Equal to the TORA", "Equal to the TODA", "TORA plus clearway", "Zero"], 0, "ASDA = TORA + stopway, so with no stopway it equals TORA."], ["A runway third has standing water covering 20% of it. How is that third reported?", ["Not contaminated: coverage must be more than 25%", "Contaminated, because there is standing water", "Slippery wet", "Contaminated if it is deeper than 3 mm"], 0, "A third is contaminated only when more than a quarter of it is covered. Depth alone does not make it contaminated."], ["Up to what depth of water is a runway reported as wet rather than contaminated?", ["Up to and including 3 mm", "Up to 3 mm, not including 3 mm", "Up to and including 6 mm", "Up to 1 mm"], 0, "Wet = visible dampness or water up to and including 3 mm (given enough coverage, deeper water is a contaminant)."], ["In the GRF, a runway condition code of 0 means:", ["The worst conditions", "The best conditions", "No report made", "A dry runway"], 0, "Codes run from 0 (worst) to 6 (best)."], ["Standing water is reported on a runway in July. How is it notified?", ["By SNOWTAM", "By an ordinary NOTAM only", "By METAR only", "It is not notified outside winter"], 0, "The GRF runs all year; a SNOWTAM reports standing water too, not only snow and ice."], ["A SNOWTAM shows 09 for runway 09/27 with 27 in use. Why?", ["SNOWTAMs give the lower runway number", "09 is the runway in use", "It is the wind direction", "It is the runway condition code"], 0, "The lower designator is always given; the report covers the runway whichever way it is used."], ["ICAO recommends which marking colours?", ["White on runways, yellow on taxiways", "Yellow on runways, white on taxiways", "White on runways and taxiways", "Blue on runways, yellow on taxiways"], 0, "Runway markings white; taxiway and stand markings yellow."], ["Runway threshold lights are:", ["Fixed green, showing towards the approach", "Fixed green, showing along the runway", "Fixed white, showing towards the approach", "Flashing green in all directions"], 0, "Fixed unidirectional green towards the approach. The red end lights are the ones that face along the runway."], ["Runway end lights show:", ["Fixed red, towards the runway", "Fixed green, towards the approach", "Flashing red, all directions", "Fixed white, towards the runway"], 0, "Fixed unidirectional red in the direction of the runway, ideally at least six of them."], ["A mandatory instruction sign is:", ["White on red", "Red on white", "Black on yellow", "Yellow on black"], 0, "White inscription on a red background."], ["A tug towing an airliner shows a low-intensity obstacle light. What colour?", ["Flashing yellow", "Flashing blue", "Steady red", "Flashing white"], 0, "Ordinary vehicles flash yellow. Emergency and security vehicles are excepted; high-intensity obstacle lights flash white."], ["How is a 40 m mast near an aerodrome normally lit at night?", ["A single steady red light at the top", "A flashing white light at the top", "Red lights outlining its whole height", "It is not lit"], 0, "Fixed obstacles 45 m or less in height, width and length get one steady red light at the highest point."], ["In the signals area you see a white T with a white disc at the head. It means:", ["Landing and take-off directions do not necessarily coincide", "Land towards the disc", "Gliding is in progress", "The manoeuvring area is in poor state"], 0, "The disc (or a black ball on the mast) warns that the two directions may differ."], ["You land using the white T in the signals area. Which way do you land?", ["Parallel with the shaft, towards the cross-arm", "Parallel with the shaft, away from the cross-arm", "Along the cross-arm", "Towards the signals area"], 0, "Towards the cross-arm, i.e. into wind, unless ATC say otherwise."], ["A white dumb-bell with a black strip across each disc means:", ["Take off and land on a runway, but ground movement need not be on hard surfaces", "Use hard surfaces only, on the ground and for take-off and landing", "Light aircraft may use the grass", "Landing prohibited"], 0, "Plain dumb-bell: hard surfaces only on the ground. The black strips relax that for taxiing but keep take-off and landing on the runway."], ["A red and yellow striped arrow, bent clockwise round the edge of the signals area, means:", ["Right-hand circuit", "Left-hand circuit", "Landing prohibited", "Taxi clockwise around the apron"], 0, "Turns before landing and after take-off are to the right."], ["A green rectangular flag flies from the signals mast. The circuit is:", ["Right-hand", "Left-hand", "Closed", "At the pilot's discretion"], 0, "Green = right-hand, red = left-hand, as with nav lights (green starboard, red port)."], ["A red square with a single yellow diagonal means:", ["The manoeuvring area is poor: take special care on approach and landing", "Landing is prohibited", "Glider flying in progress", "Use hard surfaces only"], 0, "One diagonal = take special care. A yellow diagonal cross = landing prohibited."], ["A red square with a yellow diagonal cross means:", ["Landing prohibited, likely to be prolonged", "Special precautions on landing", "Tow-rope dropping area", "Disused aerodrome"], 0, "The cross means landing is prohibited. A single diagonal only calls for special care; a yellow cross alone is the tow-rope area."], ["Two red balls hang one above the other on the signals mast. This means:", ["Glider flying is taking place", "Landing and take-off directions may differ", "Landing prohibited", "ATC permission needed to move"], 0, "Two red balls (or a double white cross) = gliding. One black ball = directions may differ."], ["Crosses with arms at 45° to the centreline appear on a taxiway. What colour are they and what do they mean?", ["Yellow; that section is unfit for aircraft", "White; that section is unfit for aircraft", "Yellow; holding point", "White; emergency use only"], 0, "Yellow on a taxiway, white on a runway, no more than 300 m apart."], ["You have landed and are vacating the runway. You meet two broken yellow lines, then two continuous ones. Do you need a clearance to cross?", ["No: you meet the broken lines first, so you are leaving the runway side", "Yes, always", "Only at night", "Yes, because the continuous lines are beyond"], 0, "The broken lines face the runway. Approaching from the runway, the holding point does not need a clearance."], ["Taxiing out towards the runway, you reach a holding point with continuous lines on your side. What applies?", ["Do not cross without ATC permission", "Cross if you see no traffic", "Cross after the power checks", "Stop only at night"], 0, "No part of the aircraft may pass the holding point towards the runway without permission."], ["Orange and white wedge-shaped markers no more than 45 m apart show:", ["The aerodrome boundary", "The edge of an unpaved runway", "A holding point", "An unfit part of a paved runway"], 0, "Wedges mark the boundary (or, alternating with flags, an unserviceable unpaved area). Unpaved runway edges are flat white markers 90 m apart."], ["Flat white rectangles flush with the ground, no more than 90 m apart, mark:", ["The boundary of an unpaved runway or stopway", "The aerodrome boundary", "A light aircraft area", "An unfit area"], 0, "Flat white = runway or stopway edge. Orange and white wedges at 45 m = aerodrome boundary."], ["A white cross and a single white bar at each end of a runway at a disused aerodrome means:", ["Fit for emergency use only", "Landing dangerous; storage only", "Landing prohibited", "Light aircraft only"], 0, "Cross plus bar = emergency only (and the runway is not safeguarded). A cross alone = dangerous, storage only."], ["Before a permanently displaced threshold there are white arrows. The area may be used for:", ["Taxi and take-off, not landing", "Landing only", "Nothing: it is unfit", "Taxiing only"], 0, "Arrows = usable for taxi and take-off. Crosses would mean unfit for any movement."], ["On the ground you see a red and yellow chequered board. It means:", ["Move on the manoeuvring area and apron only with ATC permission", "Glider flying in progress", "Report to ATC here", "Do not taxi on grass"], 0, "Chequered = ATC permission needed to move. A black C on yellow shows where to report."], ["A steady red light is aimed at you (i) in flight and (ii) on the ground. It means:", ["(i) Give way to other aircraft and continue circling (ii) stop", "(i) Aerodrome closed (ii) return to starting point", "(i) Wait for permission to land (ii) cleared to take off", "(i) Do not land (ii) move clear of the landing area"], 0, "Steady red: keep circling, or stop. Flashing red means aerodrome unavailable, or move clear of the landing area."], ["Holding at the runway, you get a steady green light. It means:", ["Cleared to take off, if no collision risk", "Cleared to taxi", "Return to the apron", "Cleared to cross the runway only"], 0, "Steady green on the ground is take-off. A flashing green is taxi."], ["Flying near the aerodrome with a radio failure, you see green flashes from the tower. They mean:", ["Return to this aerodrome and wait for permission to land", "Cleared to land", "Land and await instructions", "Do not land"], 0, "Flashing green in flight = come back and wait; steady green = cleared to land."], ["You are taxiing and receive a series of white flashes. You should:", ["Return to your starting point on the aerodrome", "Stop", "Move clear of the landing area", "Continue to the holding point"], 0, "Flashing white on the ground = return to starting point. In flight it means land here after a steady green, then await instructions."], ["In flight you see a flashing red light from the tower. You should:", ["Not land: the aerodrome is not available", "Continue circling and give way", "Land and clear the runway", "Return and wait for permission"], 0, "Flashing red in flight = do not land here. Steady red = give way and keep circling."], ["At night, a pilot flashes the landing lights on and off over the aerodrome. This means:", ["I am compelled to land", "May I land?", "I need immediate assistance", "I am leaving the circuit"], 0, "Flashing landing or nav lights = compelled to land. A green flare by night asks 'may I land?', a red flare asks for immediate help."], ["By day, an aircraft fires a green flare. It asks:", ["May I land in a different direction from that shown by the landing T?", "May I land?", "Immediate assistance required", "Permission to taxi"], 0, "By night a green flare asks 'may I land?'; by day it asks to land in a different direction from the T."], ["A marshaller holds the right arm down and repeatedly beckons with the left arm. You should:", ["Turn to port", "Turn to starboard", "Move straight ahead", "Slow down"], 0, "Right arm down, left arm beckoning = turn to port (open up the starboard engine). The faster the arm, the tighter the turn."], ["A marshaller raises the right arm at the elbow, palm facing forwards. It means:", ["All clear, marshalling finished", "Stop", "This bay", "Engage brakes"], 0, "All clear. Arms crossed above the head is stop; both arms vertical is 'this bay'."], ["The marshaller faces a four-engined aircraft. Which is No. 1 engine?", ["Port outer", "Starboard outer", "Port inner", "Starboard inner"], 0, "Numbering runs from the marshaller's right to left: No. 1 port outer, through to No. 4 starboard outer."], ["A fire crew member crosses both arms at the wrists in front of the head. It means:", ["Recommend stop", "Recommend evacuation", "Emergency contained", "Fire"], 0, "Arms crossed in front of the head = recommend stop. Arms swept down and crossed below the waist = emergency contained."], ["Which ICAO Annex sets the standards for aerodromes?", ["Annex 14", "Annex 17", "Annex 2", "Annex 11"], 0, "Annex 14 is aerodromes. Annex 17 is security, Annex 2 the rules of the air, Annex 11 air traffic services."], ["Taxiing on the manoeuvring area, ATC have cleared you along a taxiway and another aircraft approaches head-on. Who must avoid the collision?", ["You, as commander, whatever the clearance", "ATC, because they cleared you", "The other aircraft", "The aircraft with the greater speed"], 0, "The commander must do everything possible to avoid a collision regardless of ATC. Head-on, both turn right."]]});
Object.assign(SUM,{"What an aerodrome is": "Any land or water used for take-off and landing; details are in the AIP AD directory.", "Prior permission (PPR) and limits on use": "Get permission before departure: from the aerodrome authority, or the owner at unlicensed sites. Military aerodromes have extra limits, lifted in an emergency.", "ANO rules at aerodromes: instruction, fuel, arrival and customs": "Adequate facilities for training, fit fuel only, report delays of 45 minutes or more, and customs airports are in AIP GEN.", "Security (ICAO Annex 17)": "Annex 17 aims to prevent unlawful interference; security is everyone's job.", "Aeronautical light beacons": "Green Morse every 12 seconds is civil, red is military; aerodrome beacons flash white/white or white/green.", "Moving on the aerodrome (Rules 12 and 13)": "You need permission to taxi or to walk onto aircraft areas; the manoeuvring area excludes aprons.", "Right of way on the ground (SERA.3210)": "Give way to landing and departing aircraft; head-on turn right, give way to traffic on your right, overtaker keeps clear. The onus is on you.", "Aerodrome Traffic Zones (ATZs)": "Airspace around busy aerodromes where you must keep radio contact; dimensions in chapter 5.", "Declared distances (TORA, TODA, ASDA, LDA)": "TORA is the ground run; add clearway for TODA, stopway for ASDA; LDA is for landing.", "Aerodrome standards (ICAO Annex 14)": "Annex 14 sets aerodrome standards; CAP 637 and CAP 1535 explain them.", "Runway surface condition (GRF and SNOWTAM)": "Dry, wet (up to 3 mm), slippery wet or contaminated, reported per third with codes 0 to 6, by SNOWTAM all year.", "Indicators, markings and signs (Annex 14 ch. 5)": "At least one windsock; runway markings white, taxiway yellow; mandatory signs white on red.", "Runway lights (Annex 14 5.3)": "Threshold green towards the approach; end lights red towards the runway.", "Obstacle lights and marking (Annex 14 6.3)": "Vehicles flash yellow, high-intensity lights flash white, small obstacles get one steady red.", "Signals area: direction and surfaces": "Land towards the T's cross-arm; disc or black ball = directions differ; dumb-bell = hard surfaces.", "Signals area: circuit direction and warnings": "Striped arrow or green flag = right-hand circuit; one yellow diagonal = care, yellow cross = no landing; double cross = gliding.", "Signals on paved runways and taxiways": "Crosses mark unfit sections; at a holding point the broken lines face the runway.", "Markers on unpaved manoeuvring areas": "Orange/white wedges 45 m apart = boundary; flat white 90 m apart = runway edge; crosses at the ends = storage or emergency only.", "Displaced thresholds": "Arrows before the threshold = taxi and take-off but no landing; crosses = unfit.", "Signals seen only on the ground": "Black ball, two red balls, chequered board (ATC permission to move), red/green flags, black C for reporting.", "Light signals from ATC": "Green steady: land or take off; green flashing: return or taxi; red steady: circle or stop; red flashing: don't land or clear the runway; white flashing: land after green or go back.", "Light signals from aircraft": "Flashing lights = compelled to land; red flare = help; green flare = may I land (by day: in another direction).", "Marshalling signals: marshaller to pilot": "Beckon = come ahead; one arm down = turn the other way; crossed above head = stop.", "Marshalling signals: helicopters": "Arms out = hover, crossed low = land, palms show up or down.", "Signals from pilot to marshaller": "Fist and open hand for brakes, crossed hands for chocks; engines numbered from the marshaller's right.", "Emergency hand signals": "Evacuate, stop, contained, fire: the four fire-crew signals."});
NOTES.push({"s": 0, "topic": "Altimeter Setting Procedures", "num": 5, "order": 50, "conf": "weak", "status": "draft", "summary": "The altimeter is a barometer: what it reads depends on the pressure you set. QNH gives altitude (amsl) for terrain, QFE gives height above the aerodrome for the circuit, and 1013 gives flight levels for separation. En route below 3,000 ft use the Regional Pressure Setting, the lowest forecast QNH for each hour in your Altimeter Setting Region. Above the transition altitude (3,000 ft over most of the UK) use flight levels; under a TMA use an aerodrome QNH from beneath it. Flying into low pressure or cold air puts you lower than indicated: high to low, beware below. Semicircular levels go by magnetic track: east odd, west even, VFR plus 500.", "sections": [["How the altimeter works", ["Pressure falls as you climb. The altimeter is a <b>barometer</b> with its scale marked in feet instead of pressure", "Static pressure from the <b>static vent</b> fills the sealed instrument case. Inside is an <b>aneroid capsule</b>: sealed, with most of the air removed and a spring stopping it collapsing. As you climb, static pressure falls, the capsule expands, and linkage and gearing turn the pointers (the textbook simplifies this as \"a fixed amount of air in the capsule\")", "Three pointers: <b>100 ft</b>, <b>1,000 ft</b> and <b>10,000 ft</b>. A <b>striped sector</b> shows when you are below 10,000 ft", "The <b>subscale knob</b> sets the datum pressure, shown in the <b>pressure window</b>. The altimeter reads height or altitude above whatever pressure level is set", "Units: <b>hectopascals</b> (hPa) replaced millibars in the UK on 17 November 2011. 1 hPa = 1 mb", "Below 5,000 ft, <code>1 hPa</code> is roughly <code>30 ft</code>"]], ["QNH, QFE and standard pressure", ["<b>QNH</b>: mean sea level pressure. The altimeter reads <b>altitude</b>, above mean sea level (amsl). Use it for terrain and obstacles, because charts give elevations amsl", "QNH changes with time and place, so keep updating it as the day goes on and as you fly from region to region", "<b>QFE</b>: the pressure at aerodrome elevation (the <b>highest point on the landing area</b>). The altimeter reads <b>height</b> above aerodrome level (aal), so a 1,000 ft circuit shows 1,000 ft. Common for take-off, circuits and landing", "ATC pass QFE changes. Different aerodromes have different QFEs, depending on elevation and the pressure pattern", "<b>Standard pressure</b>: <code>1013.2 hPa</code> (1013). The altimeter reads <b>pressure altitude</b>; drop the last two zeros for a <b>flight level</b> (PA 3,500 ft = FL35)", "1013 is used for vertical separation between aircraft on the same setting, at higher levels where terrain is no longer the concern, and saves updating QNH", "Example, high-pressure day (QNH 1030, aerodrome 1,500 ft, QFE 980): an aircraft at <b>4,000 ft altitude</b> is at <b>FL35</b> on 1013 and <b>2,500 ft height</b> on QFE"]], ["Altimeter Setting Regions and the RPS", ["The UK is divided into <b>20 Altimeter Setting Regions</b> (ASRs). Everyone on the same region's setting has the same datum, which keeps them vertically separated", "The <b>Regional Pressure Setting</b> (RPS, often called the regional QNH) is the <b>lowest forecast QNH</b> in the region for each hour, so you are at, or slightly above, the altitude shown", "No aerodrome QNH in the region should be lower than the RPS", "ATS update the RPS every hour. Change it when you cross into another region", "The ASR chart is in the UK AIP (ENR 6). Names: Portree, Skerry, Belfast, Holyhead, Scillies, Shetland, Orkney, Marlin, Petrel, Rattray, Tyne, Skua, Puffin, Barnsley, Humber, Wessex, Cotswold, Chatham, Portland, Yarmouth", "Ask for it by name: \"Chatham regional pressure setting\""]], ["Transition altitude, layer and level", ["<b>Transition altitude</b> (TA): at and below it, vertical position is controlled by <b>altitude</b> on QNH. It is <code>3,000 ft amsl</code> over most of the UK; exceptions under some controlled airspace are in AIP ENR 1.7", "Above TA you use <b>flight levels</b> on 1013: all aircraft in controlled airspace, and above 3,000 ft outside it (subject to the AIP's exceptions)", "<b>Transition level</b> (TL): the lowest flight level available above the transition altitude. The space between TA and TL is the <b>transition layer</b>", "Climbing through TA, give your position as a <b>flight level</b>; descending through TL, give it as an <b>altitude</b>", "Flight plans: altitudes below TA, flight levels above TL", "Pick a cruising level that clears terrain, meets any ATS requirement, and follows the semicircular rule where it applies"]], ["A typical cross-country", ["Most PPL cross-countries stay outside controlled airspace and below 3,000 ft amsl", "<b>In the circuit</b>, at either end: aerodrome <b>QFE</b> (height aal) or aerodrome <b>QNH</b> (altitude), as you prefer", "<b>En route</b>: the <b>Regional Pressure Setting</b>, so the altimeter shows altitude amsl"]], ["Take-off and climb", ["Two useful readings: <b>height aal</b> on QFE (for the circuit) and <b>altitude</b> on QNH (for terrain, obstacles and airspace)", "<b>Inside controlled airspace</b>: take off on aerodrome QNH or QFE. With two altimeters, set one to <b>aerodrome QNH</b> (the other to QNH or QFE)", "Climb on aerodrome QNH up to the TA, reporting altitude. Once cleared above the TA and climbing, report a <b>flight level</b>, provided you are no more than <code>2,000 ft</code> below the TA (unless ATC ask otherwise)", "<b>Outside controlled airspace</b>: QNH or QFE for take-off and climb; report <b>altitude</b>. Under IFR, report a flight level once through the TA", "Departing from under a <b>TMA or CTA</b>: use <b>aerodrome QNH</b> below the TA beneath it. QFE may still be used in the circuit"]], ["En route: high to low, beware below", ["Update the RPS periodically and whenever you enter a new region", "Flying into <b>lower pressure</b> with the old setting, the altimeter over-reads: you gradually descend while it shows the same figure", "E.g. cruising at 1,000 ft on 1020 into an area where the QNH is 1010: the 1020 level is about 300 ft below sea level, so you are really at about <b>700 ft</b>", "<b>Colder air</b> is denser, so a pressure level is lower in cold air than warm. Flying from warm to cold, you descend in real terms", "In very cold air you can be up to about <code>10%</code> lower than indicated. Still fly by the altimeter, but allow for it", "<b>\"High to low, beware below\"</b>: applies to both low pressure and low temperature"]], ["Choosing a flight level when the QNH is low", ["When QNH is below 1013, the 1013 hPa level is <b>below</b> sea level, so a flight level is lower than its number suggests", "QNH 996: 17 hPa × 30 ft ≈ <code>500 ft</code>. FL40 is only about <b>3,500 ft amsl</b>", "Traffic at 3,000 ft would be only 500 ft below you at FL40; a 2,800 ft hill only 700 ft below", "To be 1,000 ft above something at 3,000 ft amsl that day, the lowest suitable level is <b>FL45</b> (about 4,000 ft amsl)", "Quick conversion: altitude ≈ flight level × 100 + (QNH − 1013) × 30 ft"]], ["Inside controlled airspace", ["Above <code>3,000 ft amsl</code> or the TA, whichever is higher, en-route aircraft fly <b>flight levels</b> on 1013", "The RPS goes on the second altimeter en route for checking terrain clearance", "In a <b>CTR or TMA</b>, at or below the TA, ATC give you the QNH in your clearance to enter"]], ["Outside controlled airspace", ["<b>At or below 3,000 ft amsl</b>: the RPS, or the QNH of an aerodrome nearby", "<b>Beneath a TMA or CTA</b>: the QNH of an aerodrome <b>under</b> it. It is what the traffic above is using, and stops you climbing into the airspace by mistake if it differs from the RPS", "<b>MATZ</b> penetration: normally the aerodrome <b>QFE</b>. In a combined MATZ (CMATZ) you get the lowest of its QFEs, the <b>clutch QFE</b>. Sometimes QNH is given instead. CAP 413 has the procedure", "Report vertical position as <b>altitude</b>. On an advisory route at or below 3,000 ft, use the RPS", "<b>IFR</b> in level flight above 3,000 ft (or the TA if higher): 1013 set, semicircular levels, report flight levels; RPS for terrain checks", "<b>VFR</b> above 3,000 ft may stay on the RPS (useful with changing headings and heights). Semicircular levels are not required, but if you choose them you <b>must</b> set 1013"]], ["The semicircular rule", ["Separates traffic going opposite ways. Required for IFR; strongly recommended for VFR", "Based on <b>magnetic track</b>, not heading: in a strong crosswind, fast and slow aircraft on the same track have different headings", "Track <code>000°–179°</code> (eastbound): IFR at <b>odd</b> thousands (FL30, FL50, FL70); VFR at <b>odd + 500</b> (FL35, FL55, FL75)", "Track <code>180°–359°</code> (westbound): IFR at <b>even</b> thousands (FL40, FL60); VFR at <b>even + 500</b> (FL45, FL65)", "Memory aid: east is odd, west is even; VFR adds 500", "Common trap: a question gives a <b>heading</b>. The rule uses track; with no wind information, treat the heading as the track"]], ["Approach, landing and missed approach", ["Descending from a flight level to an altitude, ATC pass the <b>aerodrome QNH</b>. It may differ slightly from the RPS but should never be lower", "Set QNH as you leave your cruising level, unless more flight-level reports are wanted (then set it after the last one)", "Stay on aerodrome QNH until approaching the circuit or established on final, then QFE if you wish", "Radar approach: the controller assumes <b>QNH</b> and gives altitudes, with a reminder in the phraseology. Tell them if you are on QFE and they will give heights instead. QNH is recommended", "Landing beneath a TMA or CTA: aerodrome QNH below the TA; QFE may be used in the circuit", "<b>Missed approach</b>: you may keep the final-approach setting, but report <b>altitude on aerodrome QNH</b> unless ATC say otherwise"]]], "cards": [["What is the altimeter, really?", "A barometer (aneroid capsule) with a scale in feet."], ["Below 5,000 ft, 1 hPa is about how many feet?", "30 ft."], ["What does a striped sector on the altimeter show?", "You are below 10,000 ft."], ["QNH set: the altimeter reads?", "Altitude (above mean sea level)."], ["QFE set: the altimeter reads?", "Height above aerodrome level."], ["1013 set: the altimeter reads?", "Pressure altitude, given as a flight level."], ["What is aerodrome elevation?", "The highest point on the landing area."], ["PA 3,500 ft as a flight level?", "FL35."], ["How many UK Altimeter Setting Regions?", "20."], ["What is the Regional Pressure Setting?", "The lowest forecast QNH in the region for each hour."], ["Can an aerodrome QNH be lower than the RPS?", "It should not be: the RPS is the lowest forecast value."], ["How often is the RPS updated?", "Every hour."], ["Where is the ASR chart?", "UK AIP, ENR 6."], ["Usual UK transition altitude?", "3,000 ft amsl (exceptions in AIP ENR 1.7)."], ["What is the transition level?", "The lowest flight level available above the transition altitude."], ["What is the transition layer?", "The airspace between the transition altitude and the transition level."], ["Climbing through TA, report as?", "A flight level."], ["Descending through TL, report as?", "An altitude."], ["Two altimeters in controlled airspace on take-off?", "At least one on aerodrome QNH."], ["Departing beneath a TMA, which setting below TA?", "Aerodrome QNH (QFE allowed in the circuit)."], ["En-route setting on a typical VFR cross-country?", "The Regional Pressure Setting."], ["Effect of flying into lower pressure without resetting?", "You are lower than indicated."], ["Effect of flying into colder air?", "You are lower than indicated (up to about 10% in very cold air)."], ["Memory aid for pressure and temperature errors?", "High to low, beware below."], ["QNH 996: roughly what altitude is FL40?", "About 3,500 ft amsl."], ["QNH 996: lowest FL to clear 3,000 ft amsl by 1,000 ft?", "FL45."], ["Under a TMA outside controlled airspace, which setting?", "QNH of an aerodrome beneath the TMA."], ["MATZ penetration: usual setting?", "Aerodrome QFE (clutch QFE in a combined MATZ)."], ["What is the clutch QFE?", "The lowest QFE of the aerodromes in a combined MATZ."], ["VFR above 3,000 ft on semicircular levels: which setting?", "1013 hPa (it must be)."], ["Semicircular rule is based on?", "Magnetic track."], ["VFR, track 000–179°M: which levels?", "Odd thousands + 500 (FL35, 55, 75...)."], ["VFR, track 180–359°M: which levels?", "Even thousands + 500 (FL45, 65...)."], ["IFR, track 000–179°M: which levels?", "Odd thousands (FL30, 50, 70...)."], ["Radar approach: which setting does the controller assume?", "QNH."], ["Missed approach: report vertical position as?", "Altitude on aerodrome QNH, unless ATC say otherwise."]], "quiz": [["With QNH set on the subscale, you report vertical position as:", ["Altitude", "Height", "Flight level", "Elevation"], 0, "QNH gives altitude amsl. QFE gives height, 1013 gives a flight level, and elevation is a fixed point on the ground, not your level."], ["The Regional Pressure Setting is:", ["The lowest forecast QNH in the region for each hour", "The lowest actual QNH in the region for each hour", "The highest forecast QNH in the region for each hour", "The average QNH of aerodromes in the region"], 0, "It is the lowest forecast value, so you are at or slightly above the altitude shown. 'Actual' is the usual trap."], ["The main purpose of (i) QFE and (ii) QNH is:", ["(i) Height above the aerodrome (ii) terrain and obstacle clearance", "(i) Height above the aerodrome (ii) separation from other traffic", "(i) Separation from other traffic (ii) terrain clearance", "(i) Terrain clearance (ii) height above the aerodrome"], 0, "QFE tells you your height aal for the circuit; QNH relates you to charted elevations amsl. Separation from other traffic at higher levels is what 1013 is for."], ["If you don't update the altimeter setting, which is the dangerous direction to fly?", ["High to low pressure, or warmer to colder air", "Low to high pressure, or colder to warmer air", "High to low pressure, or colder to warmer air", "Low to high pressure, or warmer to colder air"], 0, "Both lower pressure and colder air put you lower than indicated: high to low, beware below. The distractors mix one correct half with one wrong half."], ["A VFR flight cruising above 3,000 ft amsl:", ["Should consider the semicircular rule as good practice; the lowest westbound level is FL45", "Must follow the semicircular rule; the lowest westbound level is FL45", "Should consider the semicircular rule; the lowest westbound level is FL35", "Must follow the semicircular rule; the lowest westbound level is FL35"], 0, "For VFR the rule is recommended, not required. Westbound VFR levels are even + 500, so the lowest above 3,000 ft is FL45; FL35 is eastbound."], ["Flying beneath a TMA outside controlled airspace, which setting should you use?", ["The QNH of an aerodrome beneath the TMA", "The Regional Pressure Setting", "The QFE of an aerodrome beneath the TMA", "Whichever is lower, the RPS or an aerodrome QNH"], 0, "Use the QNH of an aerodrome under the TMA: it matches the traffic above and protects the TMA base. The RPS may differ slightly."], ["The transition altitude is:", ["The altitude at and below which vertical position is controlled by reference to altitude on QNH", "Always 3,000 ft amsl", "The altitude above which you must fly a flight level on QFE", "The lowest flight level available for cruising"], 0, "It is defined by QNH and altitude. It is 3,000 ft over most of the UK but not everywhere; the lowest usable flight level is the transition level."], ["A VFR aircraft is on a magnetic track of 055°. Which semicircular level is correct?", ["FL55", "FL50", "FL45", "FL40"], 0, "Track 000–179° is odd thousands; VFR adds 500, so FL35, FL55, FL75. FL50 is the IFR level; FL40 and FL45 are westbound."], ["The semicircular rule is based on:", ["Magnetic track", "Magnetic heading", "True track", "True heading"], 0, "Magnetic track. In a crosswind two aircraft on the same track can have very different headings."], ["An IFR flight on a magnetic track of 250°. Which is a correct cruising level?", ["FL60", "FL50", "FL65", "FL55"], 0, "Westbound IFR flies even thousands (FL40, FL60...). Plus 500 is for VFR; odd thousands are eastbound."], ["A VFR flight on a magnetic track of 180°. Which level?", ["FL45", "FL35", "FL40", "FL55"], 0, "180° is in the westbound half (180–359°), so VFR uses even + 500."], ["QNH is 996 hPa. Roughly what altitude is FL40?", ["3,500 ft amsl", "4,500 ft amsl", "4,000 ft amsl", "3,000 ft amsl"], 0, "17 hPa × 30 ft ≈ 500 ft. The 1013 level is 500 ft below sea level, so FL40 ≈ 3,500 ft. Low QNH makes flight levels lower, not higher."], ["QNH 996. You need 1,000 ft clearance above traffic at 3,000 ft amsl. Lowest suitable level?", ["FL45", "FL40", "FL35", "FL50"], 0, "FL45 ≈ 4,000 ft amsl that day. FL40 is only about 3,500 ft, giving 500 ft separation."], ["Cruising at 1,000 ft with 1020 set, you fly into an area where the QNH is 1010. Your actual altitude is about:", ["700 ft", "1,300 ft", "1,000 ft", "300 ft"], 0, "The 1020 level is about 300 ft below sea level there (10 × 30 ft), so 1,000 ft above it is about 700 ft amsl."], ["In very cold air, how much lower than indicated could you be?", ["Up to about 10%", "Up to about 1%", "Up to about 25%", "Not at all if QNH is correct"], 0, "Cold dense air lowers the pressure levels; the error can reach about 10% even with the correct QNH set."], ["The transition level is:", ["The lowest flight level available above the transition altitude", "The highest altitude at which QNH is used", "The level at which QFE changes to QNH", "Always FL30"], 0, "TL is a flight level, the first usable one above TA; between them is the transition layer."], ["Climbing through the transition altitude, you give your vertical position as:", ["A flight level", "An altitude", "A height", "A pressure altitude in feet"], 0, "Climbing, change to flight levels at TA; descending, change to altitude at TL."], ["Inside controlled airspace with two altimeters, for take-off you should have:", ["At least one on aerodrome QNH", "Both on QFE", "One on 1013 and one on QFE", "Both on the RPS"], 0, "One on aerodrome QNH for terrain and traffic; the other on QNH or QFE."], ["How is the aircraft's vertical position reported outside controlled airspace?", ["As altitude", "As height", "As a flight level", "As pressure altitude"], 0, "Outside controlled airspace, communications and flight plans use altitude (IFR above the TA excepted)."], ["Crossing a combined MATZ, what setting are you usually given?", ["The clutch QFE: the lowest QFE of the aerodromes", "The highest QFE of the aerodromes", "The RPS", "1013"], 0, "The lowest QFE is given, the clutch QFE. Sometimes QNH is passed instead when crossing."], ["A VFR pilot above 3,000 ft chooses to fly semicircular levels. Which setting?", ["1013 hPa must be set", "The RPS", "Aerodrome QNH", "Either RPS or 1013"], 0, "VFR may stay on the RPS, but semicircular levels are flight levels, so 1013 must be set if you fly them."], ["How often is the Regional Pressure Setting updated?", ["Every hour", "Every 30 minutes", "Every 3 hours", "Only when it changes by 2 hPa"], 0, "Hourly, as the lowest forecast QNH for each hour."], ["On a radar approach, which setting does the controller assume you have?", ["QNH", "QFE", "1013", "The RPS"], 0, "QNH is assumed and altitudes are given. If you say you are on QFE, the controller gives heights instead."], ["During a missed approach, vertical position should be reported as:", ["Altitude on aerodrome QNH, unless ATC instruct otherwise", "Height on QFE", "A flight level", "Height on QNH"], 0, "You may keep the final-approach setting, but report altitude on aerodrome QNH."], ["Below 5,000 ft, a 1 hPa change in setting moves the altimeter reading by about:", ["30 ft", "10 ft", "100 ft", "3 ft"], 0, "About 30 ft per hPa low down (often rounded to 27–30 ft)."], ["On a high-pressure day (QNH 1030), an aircraft is at 4,000 ft altitude. Its flight level is about:", ["FL35", "FL45", "FL40", "FL30"], 0, "QNH is 17 hPa above 1013, so the 1013 level is about 500 ft above sea level, making the aircraft about FL35. High QNH makes the flight level lower than the altitude."], ["Aerodrome elevation 1,500 ft. With QFE set on the ground, the altimeter reads:", ["Zero", "1,500 ft", "3,000 ft", "The pressure altitude"], 0, "QFE is the pressure at aerodrome level, so on the ground it reads zero. QNH would read 1,500 ft."], ["Which statement about the RPS and an aerodrome QNH in the same region is right?", ["The aerodrome QNH should not be lower than the RPS", "The aerodrome QNH should not be higher than the RPS", "They are always identical", "The RPS is the aerodrome QNH of the largest airport"], 0, "The RPS is the lowest forecast QNH, so aerodrome QNHs should be equal or higher."], ["Outside controlled airspace at or below 3,000 ft amsl, which settings may you use?", ["The RPS or the QNH of an aerodrome nearby", "Only the RPS", "Only 1013", "Only QFE"], 0, "Either the RPS or a nearby aerodrome's QNH; under a TMA or CTA, the QNH of an aerodrome beneath it."], ["Since when has the UK used hectopascals instead of millibars?", ["17 November 2011", "1 January 2021", "17 November 2001", "They were never replaced"], 0, "Hectopascals replaced millibars in the UK on 17 November 2011. 1 hPa = 1 mb, so the numbers are the same."]]});
Object.assign(SUM,{"How the altimeter works": "A pressure gauge in feet: capsule, static vent, three pointers and a subscale; 1 hPa ≈ 30 ft.", "QNH, QFE and standard pressure": "QNH = altitude amsl, QFE = height aal, 1013 = flight level.", "Altimeter Setting Regions and the RPS": "20 regions; the RPS is the lowest forecast QNH each hour.", "Transition altitude, layer and level": "Altitudes up to TA (usually 3,000 ft), flight levels from TL; the gap is the transition layer.", "A typical cross-country": "QFE or QNH in the circuit, RPS en route.", "Take-off and climb": "QNH or QFE for take-off; one altimeter on QNH in controlled airspace; aerodrome QNH under a TMA.", "En route: high to low, beware below": "Lower pressure or colder air puts you lower than indicated.", "Choosing a flight level when the QNH is low": "Low QNH drags flight levels down: FL40 on QNH 996 is about 3,500 ft.", "Inside controlled airspace": "Flight levels above 3,000 ft or TA; QNH given with CTR and TMA clearances.", "Outside controlled airspace": "RPS or local QNH; aerodrome QNH under a TMA; QFE in a MATZ; 1013 for semicircular levels.", "The semicircular rule": "By magnetic track: east odd, west even, VFR plus 500.", "Approach, landing and missed approach": "Aerodrome QNH on descent, QFE in the circuit if wanted; report altitude on a missed approach."});
NOTES.push({"s": 0, "topic": "Airspace", "num": 6, "order": 60, "conf": "weak", "status": "draft", "summary": "UK airspace is the London and Scottish FIRs (surface to FL245). Classes A to E are controlled; F and G are not. Control Zones start at the surface; Control Areas, TMAs and airways start at a base. Class A is closed to VFR, B and F are unused, most CTRs are D, and everything above FL195 is C. ATZs run from the surface to 2,000 ft aal with a 2 or 2.5 nm radius; MATZs to 3,000 ft aal and 5 nm, with 4 nm by 5 nm stubs. Special VFR lets you fly in a CTR below VMC. Know how Danger Areas are drawn and labelled, and the hazards that live in Class G.", "sections": [["Flight Information Regions", ["UK airspace has two <b>Flight Information Regions</b>: <b>London</b> and <b>Scottish</b>", "The FIRs run from the <b>surface to FL245</b>. Above that is upper airspace: the London and Scottish <b>UIRs</b>, <code>FL245</code> to <code>FL660</code> (in Europe the UIR starts at FL195)", "On the 1:500,000 chart the boundary is labelled SCOTTISH FIR EGPX / LONDON FIR EGTT, near <code>55°N</code> in the east", "Airspace is subdivided by the amount and type of flying: tightly regulated round London, little regulation over the Outer Hebrides"]], ["Controlled and uncontrolled airspace", ["Two categories: <b>controlled</b> and <b>uncontrolled</b>", "ICAO classes <b>A to G</b>: A is the busiest controlled airspace; B, C, D and E are other controlled airspace; <b>F and G are uncontrolled</b>", "Each class has its own VMC minima and level of air traffic service", "In controlled airspace <b>ATC is provided to all flights</b>. UK controlled airspace is made of CTRs, TMAs, CTAs and Airways", "Class A is closed to VFR and Class B is not used in the UK, so UK VFR in controlled airspace is usually in <b>C, D or E</b>"]], ["Control Zones, TMAs, CTAs and Airways", ["<b>Control Zone (CTR)</b>: around certain aerodromes, <b>from the surface</b> to a specified altitude or FL; at least <code>5 nm</code> either side of the aerodrome centre along the approach path. Most UK CTRs are <b>Class D</b> (even Heathrow)", "<b>Control Area (CTA)</b>: controlled airspace from a specified <b>base</b> up to an upper limit. UK CTAs are Class A, C or D", "<b>Terminal Control Area (TMA)</b>: a CTA at the <b>confluence of ATS routes</b> near one or more major aerodromes. Four in the UK: <b>London, Manchester, Scottish, Belfast</b> (Class A, C, D or E). TCA is another abbreviation; TMA comes from Terminal Manoeuvring Area", "<b>Airway</b>: a CTA shaped as a corridor, <code>5 nm</code> each side of the centreline, with set vertical limits, e.g. A25 (Alpha Two Five), R8 (Romeo Eight). Class A, E or C. The base steps down near aerodromes", "Trap: surface upwards = <b>Control Zone</b>; from a base upwards = <b>Control Area</b>"]], ["Controlled airspace on charts", ["<b>1:500,000</b> chart: controlled airspace up to <b>FL195</b>, with its class", "<b>1:250,000</b> chart: all controlled airspace with a base <b>at or below <code>3,000 ft</code> amsl</b>", "Class D boundaries are blue dashed lines. A <b>+</b> after a limit (e.g. FL55+) means up to FL195", "Examples: Leeds Bradford CTR, Class D, surface to FL85; London TMA, Class A, 5,500 ft to FL195; Southampton CTR, Class D, surface to 2,000 ft; Solent CTA, Class D, 2,000 ft to FL55; Airway R37, Class A, FL115 to FL195", "Full descriptions in AIP ENR; Pooley's lists controlling units and frequencies"]], ["Special VFR", ["<b>Special VFR</b> (SERA.5010): an ATC authorisation to fly in a <b>Control Zone</b> in weather below VMC without full IFR", "Stay <b>clear of cloud</b> and <b>in sight of the surface</b>; you are responsible for obstacle clearance", "Flight visibility at least <code>1,500 m</code>; speed <code>140 kt</code> or less", "No take-off, landing, or entering the ATZ or circuit if the reported <b>ground visibility is below <code>1,500 m</code></b> or the <b>cloud ceiling below <code>600 ft</code></b>", "Under ATC instruction the 1,000 ft congested-area rule may be relaxed, but you must be able to <b>glide clear</b>, stay <code>500 ft</code> from people, vessels, vehicles and structures, and land only at a licensed or Government aerodrome (unless the CAA agrees)", "Only in Control Zones. May be requested to transit a Class A CTR (none in the UK), never other Class A", "<b>No flight plan</b> needed, but <b>ATC approval</b> is. ATC separate you from other SVFR and IFR traffic; their instructions must be followed"]], ["Crossing an airway", ["A pilot without an IMC or instrument rating may fly <b>at right angles</b> across the <b>base</b> of an en-route airway whose lower limit is a <b>flight level</b>, in VMC, but <b>must not enter</b> it", "E.g. Airway B1, base <b>FL75</b>: cross beneath it, north or south, not above FL75", "With a valid <b>Instrument Rating</b> you may <b>cross through</b> an airway in VMC by day if you file a flight plan and request a crossing clearance at least <code>10 minutes</code> before the crossing point, and receive it before crossing", "Cross by the shortest route (normally at right angles), in level flight at the cleared level"]], ["Uncontrolled airspace: the Open-FIR", ["Class G, the <b>Open-FIR</b>, is about <b>50%</b> of UK airspace and includes MATZs and the ATZs outside controlled airspace", "<b>FIS</b> is available from <b>London Information</b> and <b>Scottish Information</b> (e.g. 124.75 MHz in the south-west): weather, nav aid serviceability, aerodrome conditions, alerting, proximity warnings and other advisory information", "<b>Radar services</b> (Traffic or Deconfliction) from ATSUs, including <b>LARS</b> units", "ATZs and MATZs have their own frequencies", "Flight in an ATZ is regulated by <b>Rule 11</b>, so ATZs, like controlled airspace, are <b>regulated airspace</b>"]], ["Aerodrome Traffic Zones (ATZ)", ["At most UK civil and military aerodromes. An ATZ has <b>no class of its own</b>: it takes the class of the airspace it is in", "From the <b>surface to <code>2,000 ft</code> aal</b>, a circle centred on the <b>mid-point of the longest runway</b>", "Radius <b><code>2 nm</code></b> if the longest runway is <code>1,850 m</code> or less; <b><code>2.5 nm</code></b> if it is longer", "Some 2 nm ATZs are enlarged to 2.5 nm to give at least <code>1.5 nm</code> beyond every runway end", "Listed in AIP AD 2 and on 1:500,000 and 1:250,000 charts, plus an ATZ list on the 1:500,000. ATZs wholly inside regulated airspace (e.g. Birmingham) are not drawn on the 1:500,000"]], ["Rule 11: flying in an ATZ", ["Do not fly in an ATZ unless you have <b>permission from ATC</b>; or, with no ATC, enough <b>information from the AFIS</b> unit; or, with neither, enough <b>information from the A/G radio</b> station", "Keep a <b>continuous watch</b> on the frequency (or watch for visual signals)", "With a radio, report <b>position and height</b> on <b>entering and leaving</b>, and make any other standard or requested calls", "Applies at a <b>Government</b> aerodrome at notified times (usually H24); at an aerodrome with <b>ATC or AFIS</b> during its hours of watch; at a <b>licensed</b> aerodrome with A/G radio during its notified hours", "If the ATZ is inside stricter airspace (e.g. Class D), the <b>stricter rules</b> apply", "Trap: the report is position and <b>height</b>, not heading or intentions"]], ["Military Aerodrome Traffic Zones (MATZ)", ["<b>Surface to <code>3,000 ft</code> aal</b>, radius <b><code>5 nm</code></b>", "Usually one or more <b>stubs</b> along the final approach of the main instrument runway(s): <code>4 nm</code> <b>wide</b>, extending a further <code>5 nm</code>, from <code>1,000 ft</code> to <code>3,000 ft</code> aal", "Civil pilots are <b>strongly advised</b> to enter under the control of the MATZ unit (AIP ENR 2.2, Pooley's)", "A MATZ is not regulated airspace, but the <b>ATZ inside it must always be observed</b> (most are H24)"]], ["UK airspace classes", ["<b>Class A</b>: airways, London and Manchester TMAs, Cotswold, Daventry and Worthing CTAs. <b>No VFR</b>", "<b>Class B</b>: not allocated in the UK", "<b>Class C</b>: all airspace <b>above FL195</b>, plus some CTAs below it (e.g. Daventry 21 and 22, Severn 1 and 2, Clacton 10-12)", "<b>Class D</b>: less busy airspace: most CTRs and CTAs, the Scottish TMA, and ATZs inside Class D CTRs", "<b>Class E</b>: below FL195, e.g. parts of the Scottish TMA below 6,000 ft, parts of the Farnborough CTA, Doncaster Sheffield CTA 13, Holyhead CTAs 15 and 16, Argyll and Moray CTAs, some airways", "<b>Class F</b>: not allocated in the UK. <b>Class G</b>: everything else (the Open-FIR)", "VFR in <b>Class C and D</b> needs flight notification and an <b>ATC clearance</b>"]], ["Prohibited, Restricted and Danger Areas", ["<b>Prohibited Area</b>: flight is prohibited (e.g. <b>P611/2.2</b>, surface to 2,200 ft)", "<b>Restricted Area</b>: flight is restricted according to certain conditions", "<b>Danger Area</b>: activities dangerous to flight may happen (AIP ENR 5). <b>Solid red</b> outline: active in published hours. <b>Pecked red</b>: inactive unless notified by NOTAM", "Reading <b>D129/1.75</b>: the first digit is the latitude band (1 = between 51°N and 52°N); after the slash, the upper limit in thousands of ft amsl (1,750 ft, from the surface). \"1-2.5\" would be 1,000 to 2,500 ft amsl", "An <b>asterisk (*)</b> means by-laws <b>prohibit entry</b> while the area is active", "<b>DACS</b> (Danger Area Crossing Service) and <b>DAAIS</b> (Danger Area Activity Information Service) are listed on the 1:500,000 chart", "<b>Weapon Range Danger Areas</b>: get a radar service near them. <b>Pilotless aircraft</b> (orange or red, up to 60,000 ft, mainly West Wales): avoid the recovery part of their areas", "All of these are on the AIP's Chart of UK Airspace Restrictions and Hazardous Areas; changes by NOTAM and AIC"]], ["Obstructions", ["Structures <b><code>100 m</code> agl</b> or more are in AIP ENR 5.4 and on certain charts", "Beyond <code>15 km</code> of an aerodrome, obstacles over <code>150 m</code> are en-route obstacles: <b>steady red</b> lights at night, some with high-intensity <b>flashing white</b> lights", "Obstructions may or may not be lit; windfarms are often unlit. Charts show amsl with agl in brackets, e.g. 840 (380)", "Aerodrome obstructions: AIP AD and instrument approach charts"]], ["Other hazards", ["<b>Winch-launched gliders</b>: cable up to <code>2,000 ft</code> agl (higher at a few sites). <b>Aerotow</b>: glider and tug joined by up to <code>150 m</code> of cable", "<b>Parachute training balloons</b>: no notification; up to <code>1,000 ft</code> agl, in visibility of 5 km or more and 1,000 ft from cloud", "<b>Parachuting</b>: free-fall up to <b>FL150</b>; expect parachutists within <code>1.5 nm</code> of the drop zone. Also by day at any Government or licensed aerodrome", "<b>Parascending and hang-gliders</b>: up to cloud base or the base of controlled airspace (whichever is lower); cables to <code>2,000 ft</code> agl", "<b>Military low flying</b> up to <code>2,000 ft</code> agl, busiest <code>250</code> to <code>500 ft</code> agl: avoid that band. Avoid <b>AIAAs</b> if you can", "<b>Gas venting sites</b>: severe turbulence; magenta circle with the hazard altitude. <b>Small arms ranges</b>: hazard below 500 ft agl, not Danger Areas", "<b>Target towing</b>: up to 2,000 ft of cable, by day in VMC, up to 10,000 ft", "<b>Birds</b>: keep above the effective altitude over sanctuaries and above <code>1,500 ft</code> agl over other concentrations. Strike risk rises with speed", "<b>HIRTA</b> (High Intensity Radio Transmission Areas): interference with radios and nav equipment; some can endanger health"]], ["Royal Flights", ["A Royal Flight carries members of the Royal Family (others such as heads of state may get the status)", "Fixed-wing: where possible within the normal route structure; otherwise temporary <b>Class D</b> controlled airspace, <b>CAS-T</b>, notified by <b>NOTAM</b>", "Enter CAS-T only with an <b>ATC clearance</b>, whatever the weather", "Temporary Control Zones: radius <code>5</code> to <code>10 nm</code>, active from 15 minutes before to 30 minutes after ETD and ETA. Temporary airways: 5 nm each side of track", "Helicopters: no CAS-T normally; a Royal Low-Level Corridor is notified by NOTAM"]]], "cards": [["How many UK FIRs?", "Two: London and Scottish."], ["Vertical extent of the UK FIRs?", "Surface to FL245."], ["UK UIRs?", "FL245 to FL660."], ["Which classes are controlled airspace?", "A, B, C, D and E."], ["Which classes are uncontrolled?", "F and G."], ["Which UK classes can VFR flights use in controlled airspace?", "Usually C, D and E (A is closed to VFR; B is not used)."], ["Control Zone: lower limit?", "The surface."], ["Control Area: lower limit?", "A specified base altitude or flight level."], ["What is a TMA?", "A Control Area at the confluence of ATS routes near one or more major aerodromes."], ["The four UK TMAs?", "London, Manchester, Scottish, Belfast."], ["Airway width?", "5 nm each side of the centreline."], ["Most UK CTRs are which class?", "Class D."], ["1:500,000 chart shows controlled airspace up to?", "FL195."], ["1:250,000 chart shows controlled airspace with a base at or below?", "3,000 ft amsl."], ["SVFR flight visibility?", "At least 1,500 m."], ["SVFR speed limit?", "140 kt."], ["SVFR: no take-off or landing if ground visibility is below / ceiling below?", "1,500 m / 600 ft."], ["Where does SVFR exist?", "Only in Control Zones."], ["SVFR: flight plan?", "Not required, but ATC approval is."], ["Crossing an airway without an instrument rating?", "Only beneath its base (where the base is a FL), at right angles, in VMC."], ["Airway crossing with an IR: how early to request clearance?", "At least 10 minutes before the crossing point."], ["Share of UK airspace that is Class G?", "About 50%."], ["ATZ vertical extent?", "Surface to 2,000 ft aal."], ["ATZ radius, longest runway 1,850 m or less?", "2 nm."], ["ATZ radius, longest runway over 1,850 m?", "2.5 nm."], ["ATZ centre?", "The mid-point of the longest runway."], ["ATZ class?", "None of its own: it takes the class of the surrounding airspace."], ["Radio report in an ATZ?", "Position and height, entering and leaving."], ["Rule 11 with no ATC or AFIS?", "Get enough information from the A/G station to fly safely."], ["MATZ vertical extent and radius?", "Surface to 3,000 ft aal, 5 nm radius."], ["MATZ stub dimensions?", "4 nm wide, 5 nm long, 1,000 to 3,000 ft aal."], ["Is a MATZ regulated airspace?", "No, but the ATZ inside it is."], ["Class C in the UK?", "All airspace above FL195, plus certain CTAs."], ["Solid red Danger Area outline?", "Active in published hours."], ["Pecked red Danger Area outline?", "Inactive unless notified by NOTAM."], ["D129/1.75: what does 1.75 mean?", "Upper limit 1,750 ft amsl."], ["Asterisk before a Danger Area number?", "By-laws prohibit entry while active."], ["P611/2.2?", "Prohibited Area, surface to 2,200 ft."], ["Glider winch cable height?", "Up to 2,000 ft agl."], ["Free-fall parachuting: height and radius?", "Up to FL150, within 1.5 nm of the drop zone."], ["Military low flying busiest band?", "250 to 500 ft agl."], ["Birds: minimum height over concentrations?", "1,500 ft agl (above the effective altitude over sanctuaries)."], ["Structures listed as air navigation obstructions?", "100 m agl or more."], ["Royal Flight temporary airspace?", "CAS-T, Class D, notified by NOTAM; enter only with a clearance."]], "quiz": [["A Danger Area on the 1:500,000 chart has a pecked red outline. It is:", ["Inactive unless notified by NOTAM", "Active only in published hours", "Always active", "Inactive in daylight"], 0, "Pecked = inactive unless NOTAMed. A solid red outline is active in its published hours."], ["Controlled airspace from the surface to a specified upper limit is a:", ["Control Zone", "Control Area", "Aerodrome Traffic Zone", "Airway"], 0, "Surface upwards is a CTR. A CTA (and an airway) starts at a base above the surface; an ATZ is not controlled airspace in itself."], ["A Terminal Control Area is:", ["A Control Area at the confluence of ATS routes near one or more major aerodromes", "A Control Zone at the confluence of ATS routes near one or more major aerodromes", "A Control Area for arriving flights only", "A Control Area for departing flights only"], 0, "It is a Control Area (it has a base), not a Control Zone. It serves both arrivals and departures."], ["\"P611/2.2\" on a chart is:", ["A Prohibited Area, surface to 2,200 ft", "A Danger Area, surface to 2,200 ft", "A Restricted Area, surface to 2,200 ft", "A Prohibited Area, surface to 22,000 ft"], 0, "P is Prohibited; 2.2 is the upper limit in thousands of feet: 2,200 ft."], ["The dimensions of a MATZ stub are:", ["1,000 to 3,000 ft aal, 4 nm wide, extending 5 nm", "1,000 to 3,000 ft aal, 5 nm wide, extending 4 nm", "2,000 to 3,000 ft aal, 4 nm wide, extending 5 nm", "1,000 to 2,000 ft aal, 5 nm wide, extending 4 nm"], 0, "Stubs: 4 nm wide, 5 nm long, from 1,000 to 3,000 ft aal. The traps swap the 4 and the 5."], ["An aerodrome's longest runway is 2,000 m. Its ATZ is:", ["2.5 nm radius, surface to 2,000 ft aal", "2 nm radius, surface to 2,000 ft aal", "5 nm radius, surface to 3,000 ft aal", "2.5 km radius, surface to 2,000 ft aal"], 0, "Over 1,850 m gives 2.5 nm (nautical miles, not km). 5 nm and 3,000 ft are MATZ figures."], ["Flying in an ATZ with a radio, you must:", ["Keep a continuous listening watch and report position and height entering and leaving", "Keep a continuous watch and report position and heading entering and leaving", "Report position, intentions and height entering and leaving", "Report position and heading entering and leaving"], 0, "Position and height, plus a continuous watch. Heading and intentions are the distractors."], ["A Special VFR flight is:", ["A VFR flight cleared by ATC to operate in a Control Zone in conditions below VMC", "A VFR flight cleared to operate in any controlled airspace below VMC", "A VFR flight cleared to operate in a Control Area below VMC", "A VFR flight cleared to operate below IMC"], 0, "SVFR exists only in Control Zones. 'Below IMC' is meaningless: SVFR is used below VMC."], ["Under SVFR, which minimum flight visibility applies?", ["1,500 m", "5 km", "800 m", "3,000 m"], 0, "SVFR needs a flight visibility of at least 1,500 m, clear of cloud and in sight of the surface."], ["You may not take off under SVFR if the reported conditions at the aerodrome are:", ["Ground visibility below 1,500 m or cloud ceiling below 600 ft", "Ground visibility below 1,500 m or cloud ceiling below 1,000 ft", "Ground visibility below 5 km or cloud ceiling below 600 ft", "Flight visibility below 1,500 m or cloud ceiling below 1,500 ft"], 0, "The limits are ground visibility 1,500 m and ceiling 600 ft."], ["Which statement about SVFR is correct?", ["No flight plan is needed, but ATC approval is", "A full flight plan must be filed", "It can be used in any Class A airspace", "It can be used in Class G outside a Control Zone"], 0, "SVFR needs ATC approval but no flight plan. It exists only in Control Zones and never in Class A outside a CTR."], ["The speed limit under SVFR is:", ["140 kt", "250 kt", "120 kt", "100 kt"], 0, "140 kt. 250 kt is the speed limit below FL100 for VFR in some airspace classes."], ["Without an instrument rating, how may you cross an airway whose base is FL75?", ["Beneath it, at right angles, not above FL75, in VMC", "Through it at FL80 in VMC", "Through it with a crossing clearance", "Not at all"], 0, "You may pass under the base at right angles but must not enter. Entering needs an IR and a crossing clearance."], ["With an instrument rating, a crossing clearance for an airway should be requested at least:", ["10 minutes before the crossing point", "5 minutes before", "30 minutes before", "Before departure only"], 0, "At least 10 minutes before, and the clearance must be received before crossing."], ["Which UK airspace class is NOT available to VFR flights?", ["Class A", "Class C", "Class D", "Class E"], 0, "Class A is IFR only. VFR may use C and D with a clearance, and E."], ["All UK airspace above FL195 is:", ["Class C", "Class A", "Class D", "Class G"], 0, "Above FL195 the London and Scottish FIR airspace is Class C."], ["Most UK Control Zones, including Heathrow's, are:", ["Class D", "Class A", "Class C", "Class E"], 0, "Most UK CTRs are Class D."], ["What class is an ATZ?", ["It takes the class of the airspace it sits in", "Always Class D", "Always Class G", "Class F"], 0, "An ATZ has no class of its own."], ["Where is the centre of an ATZ?", ["The mid-point of the longest runway", "The aerodrome reference point", "The control tower", "The threshold of the main runway"], 0, "The circle is centred on the notified mid-point of the longest runway."], ["At an aerodrome with no ATC or AFIS, Rule 11 lets you fly in the ATZ if you have:", ["Enough information from the A/G radio station to fly safely", "Permission from the A/G operator", "Permission from London Information", "A clearance from the nearest ATC unit"], 0, "A/G stations give information, not permission; ATC gives permission; AFIS gives information."], ["Where an ATZ lies within Class D airspace:", ["The stricter Class D rules apply", "Only the ATZ rules apply", "Neither applies to VFR", "The pilot chooses"], 0, "The more stringent rules take precedence."], ["A Danger Area is labelled D129/1.75. It lies:", ["Between 51°N and 52°N, from the surface to 1,750 ft amsl", "Between 52°N and 53°N, up to 1,750 ft agl", "Between 51°N and 52°N, up to 17,500 ft", "At 12.9°E, up to 1,750 ft"], 0, "The first digit is the latitude band (1 = 51 to 52°N); after the slash the top is in thousands of ft amsl."], ["An asterisk before a Danger Area number means:", ["By-laws prohibit entry while it is active", "It is never active", "A crossing service is available", "It contains pilotless aircraft"], 0, "By-law areas may not be entered during their activity."], ["The 1:250,000 chart shows all controlled airspace with a base:", ["At or below 3,000 ft amsl", "Up to FL195", "At or below 5,000 ft amsl", "Below FL100"], 0, "The half-million shows up to FL195; the quarter-million shows everything with a base at or below 3,000 ft amsl."], ["Free-fall parachuting can be expected up to:", ["FL150, within 1.5 nm of the drop zone", "FL100, within 1 nm", "5,000 ft, within 2 nm", "FL150, within 5 nm"], 0, "Up to FL150 within a 1.5 nm radius of the DZ."], ["Winch-launched gliders may carry the cable up to about:", ["2,000 ft agl", "1,000 ft agl", "3,000 ft agl", "500 ft agl"], 0, "2,000 ft agl, and higher at a few sites."], ["Military low flying is concentrated between:", ["250 and 500 ft agl", "500 and 1,000 ft agl", "1,000 and 2,000 ft agl", "Surface and 250 ft agl"], 0, "Low flying happens up to 2,000 ft agl but is busiest at 250 to 500 ft agl."], ["Over areas where birds concentrate (not sanctuaries) you should avoid flying below:", ["1,500 ft agl", "500 ft agl", "1,000 ft agl", "3,000 ft agl"], 0, "Below 1,500 ft agl; over sanctuaries, keep above the listed effective altitude."], ["Is a MATZ regulated airspace?", ["No, but the ATZ within it must always be observed", "Yes, always", "Only when the aerodrome is open", "Only for military aircraft"], 0, "Entering under MATZ control is strongly advised, not required, but the ATZ inside applies (usually H24)."], ["The upper limit of the UK FIRs is:", ["FL245", "FL195", "FL660", "FL100"], 0, "FIRs run from the surface to FL245; the UIRs from FL245 to FL660."], ["CAS-T for a Royal Flight is:", ["Temporary Class D airspace; enter only with an ATC clearance", "Temporary Class A airspace closed to all", "Advisory airspace you may enter freely", "A Prohibited Area"], 0, "CAS-T is Class D and notified by NOTAM; you need a clearance whatever the weather."]]});
Object.assign(SUM,{"Flight Information Regions": "London and Scottish FIRs, surface to FL245; UIRs above.", "Controlled and uncontrolled airspace": "A to E controlled, F and G uncontrolled; UK VFR usually in C, D, E.", "Control Zones, TMAs, CTAs and Airways": "CTR from the surface; CTA, TMA and airways from a base. Airways 5 nm each side.", "Controlled airspace on charts": "Half-million to FL195; quarter-million for bases at or below 3,000 ft.", "Special VFR": "In a CTR below VMC: clear of cloud, sight of surface, 1,500 m, 140 kt; ATC approval, no flight plan.", "Crossing an airway": "Without an IR, only beneath a FL base at right angles; with an IR, clearance 10 minutes ahead.", "Uncontrolled airspace: the Open-FIR": "Class G, about half the UK; FIS from London or Scottish Information.", "Aerodrome Traffic Zones (ATZ)": "Surface to 2,000 ft aal; 2 nm (runway up to 1,850 m) or 2.5 nm.", "Rule 11: flying in an ATZ": "Permission from ATC or information from AFIS or A/G; listen out; report position and height.", "Military Aerodrome Traffic Zones (MATZ)": "Surface to 3,000 ft aal, 5 nm; stubs 4 nm wide, 5 nm long, 1,000 to 3,000 ft.", "UK airspace classes": "A: no VFR; B and F unused; C above FL195; D most CTRs; G the rest.", "Prohibited, Restricted and Danger Areas": "Solid red active, pecked red only by NOTAM; D129/1.75 decoded.", "Obstructions": "100 m agl and over listed; en-route obstacles lit red.", "Other hazards": "Cables to 2,000 ft, parachuting to FL150, low flying 250-500 ft, birds below 1,500 ft.", "Royal Flights": "Temporary Class D (CAS-T) by NOTAM; clearance needed."});
NOTES.push({"s": 0, "topic": "Air Traffic Services", "num": 7, "order": 70, "conf": "weak", "status": "draft", "summary": "ATS (ICAO Annex 11) prevent collisions, keep traffic flowing, give information and alert search and rescue. Each airspace class sets who is separated from whom. In the UK you meet ATC (Ground, Tower, Approach), AFIS (\"Information\", no instructions in the air) and A/G (\"Radio\"). Outside controlled airspace CAP 774 gives four services: Basic, Traffic, Deconfliction and Procedural; whichever you get, avoiding traffic and terrain stays your job. Know when a flight plan is required or advisable, and the 30-minute overdue rule.", "sections": [["ICAO Annex 11: objectives of ATS", ["<b>Annex 11</b> covers airspace, ATS units and the services needed for a safe, orderly and expeditious flow of traffic", "Objectives: prevent <b>collisions in the air</b>; prevent collisions on the <b>manoeuvring area</b> (aircraft and obstructions); <b>expedite</b> and keep an orderly flow; give <b>advice and information</b>; <b>alert</b> search and rescue and assist it", "ATS are <b>not solely</b> responsible for preventing collisions: pilots and vehicle drivers keep their own responsibilities", "The need for ATS depends on the types of traffic, its density and the weather", "ATC is provided to all <b>IFR</b> flights in A to E; all <b>VFR</b> flights in B, C and D; all <b>Special VFR</b>; and all aerodrome traffic at controlled aerodromes (the book lists A for VFR too, but VFR is not allowed in Class A)"]], ["Services in each airspace class", ["<b>A</b>: IFR only; all cleared; all separated", "<b>B</b>: IFR and VFR; all cleared; all separated from each other", "<b>C</b>: all cleared; IFR separated from IFR <b>and</b> VFR; VFR separated from IFR, with traffic information on other VFR", "<b>D</b>: all cleared; IFR separated from IFR only; VFR get traffic information on <b>all</b> other flights; avoidance advice on request", "<b>E</b>: only <b>IFR</b> needs a clearance; IFR separated from IFR; traffic information as far as practical", "<b>F</b>: advisory service for participating IFR; <b>G</b>: services on request only", "Trap: in Class D, VFR are <b>not</b> separated from anyone; they get traffic information"]], ["ATS units in the UK", ["ATSUs give information before flight and keep radio contact during it; control is by <b>clearances and instructions</b>", "<b>Area Control Centre</b>: ATC on airways (IFR), FIS and alerting, and the <b>Distress and Diversion</b> service", "<b>Aerodrome ATC</b> controls aircraft in the vicinity and <b>all traffic on the manoeuvring area</b>, which needs ATC's prior permission", "<b>Ground</b>: the manoeuvring area except runways in use. <b>Tower</b>: the runway and the circuit. Small aerodromes: Tower does both", "<b>Approach</b>: departing the circuit, joining, and operating nearby. Normally departures call the <b>Tower (or Ground) first</b>; arrivals call <b>Approach first</b>", "In a radar-equipped CTR you get a <b>Radar Control Service</b>: comply with the clearance, or ask for an alternative <b>before</b> deviating", "Non-radio aircraft: light signals (also from a runway control van) and ground signals", "Near aerodromes separation may be reduced if the controller can see both aircraft, or the pilots can see each other and say they will keep their own separation, or a following pilot has the one ahead in sight"]], ["AFIS, A/G radio and Safetycom", ["<b>AFIS</b> (\"Information\"): at aerodromes without ATC, information for safe flight <b>in the ATZ</b>. <b>No instructions to aircraft in the air</b>; on the ground, instructions should be followed", "<b>A/G radio</b> (\"Radio\"): neither ATC nor AFIS; usually staff without ATC qualifications", "<b>Safetycom <code>135.480 MHz</code></b>: shared by airfields without their own frequency. Expect congestion; keep calls short", "Use Safetycom only <b>below <code>2,000 ft</code> aal</b> (or 1,000 ft above circuit height) and <b>within <code>10 nm</code></b> of your landing aerodrome"]], ["Lower Airspace Radar Service (LARS)", ["Outside controlled airspace <b>up to FL100</b>, within about <b><code>30 nm</code></b> of a participating civil or military unit", "Provides a Basic, <b>Traffic</b> or <b>Deconfliction</b> Service on request", "Three unanswered calls: assume the unit is closed", "LARS frequencies are on the 1:500,000 and 1:250,000 charts"]], ["UK Flight Information Services (CAP 774)", ["In Class G, <b>the pilot is ultimately responsible for collision avoidance and terrain clearance</b>, whatever the service", "Four services: <b>Basic, Traffic, Deconfliction, Procedural</b>. An <b>alerting service</b> comes with all of them", "Agreeing a service is a \"contract\": both sides keep to its definition", "<b>FISOs</b> can only give a <b>Basic Service</b>; the others need a controller", "You choose the service; the controller asks if you don't say. Units without radar give a Procedural Service to IFR procedures as routine", "The controller tells you when the service is <b>reduced</b> (high workload or traffic, SSR only, edge of radar cover)", "Instructions outside controlled airspace are <b>not mandatory</b>, but follow them where you can", "<b>Agreements</b> (with a controller, not a FISO, under a Basic or Traffic Service) on route, heading, level or area: don't break one without telling the controller and getting a reply, unless safety requires it"]], ["Basic Service", ["Maximum autonomy: <b>advice and information</b> for safe and efficient flight (weather, serviceability, aerodrome conditions, aerial activity)", "For IFR or VFR, but may not suit IMC", "<b>Traffic information should not be expected</b>. Outside an ATZ there is no obligation to give it", "You may be identified, but nobody is <b>monitoring</b> your flight", "You may change heading, route or level <b>without telling</b> the controller, unless you have an agreement", "You avoid other traffic <b>unaided</b>"]], ["Traffic Service", ["<b>Radar-based</b>: a Basic Service plus <b>radar-derived traffic information</b>", "IFR or VFR. If a heading or level would take you into IMC and you are not qualified, say so", "You are <b>identified</b> and told so", "Headings and levels may be given for positioning or sequencing, but <b>not to deconflict</b>", "Don't change an assigned heading or level without telling ATC and getting a response, unless safety requires it", "Still your job to avoid traffic and terrain. Want avoiding action? <b>Ask for a Deconfliction Service</b>"]], ["Deconfliction Service", ["<b>Radar-based</b>: traffic information <b>plus headings and levels</b> aimed at deconfliction minima", "Minima against unknown traffic: <b><code>5 nm</code> laterally or <code>3,000 ft</code> vertically</b>. Between aircraft with the same controller: <code>3 nm</code> and <code>1,000 ft</code> (some military units 500 ft)", "Minima are aimed at, <b>not guaranteed</b>", "For <b>IFR</b>: expect headings or levels that may put you in IMC", "Traffic avoidance is <b>still ultimately the pilot's</b>. Ignore an instruction and the avoidance of that aircraft is on you", "Only <b>at or above the unit's terrain safe level</b>; below it you get a Traffic Service instead"]], ["Procedural Service", ["<b>No radar</b>: levels, radials, tracks and times that keep you apart from <b>other aircraft taking part</b> in the Procedural Service", "Other Class G traffic need not be talking to the unit, so <b>conflicting traffic can appear without warning</b>", "Common at aerodromes with instrument procedures but no radar. For <b>IFR</b>, possibly in IMC", "You need not be identified; accurate <b>position reports</b> are essential", "Traffic information is given on aircraft receiving a Basic Service from that unit, but no deconfliction advice on them"]], ["Flight plans", ["A flight plan is an ICAO-format ATC message and the basis for a clearance. Form <b>CA48</b>, or online via <b>AFPEx</b>. Guidance: Safety Sense 20 and AIP ENR 1.10", "<b>Booking out</b> with the departure aerodrome is still required, and a flight plan is <b>not PPR</b>", "Must file: all flights in <b>Class A</b>; all IFR in controlled airspace; all flights in controlled airspace in IMC or at night; all flights in <b>Class B to D</b>; destination over <code>40 km</code> with MTOW over <code>5,700 kg</code>; flights <b>crossing the UK FIR boundary</b>", "VFR and Special VFR into a CTR usually use an <b>abbreviated flight plan</b>: the details given by radio when asking for the clearance", "<b>Advisable</b> more than <code>10 nm</code> from the coast or over sparsely populated or mountainous areas", "IFR in the Open-FIR does not need one on its own", "No ATSU at the destination: leave a <b>responsible person</b> who knows your ETA", "Not arrived <b><code>30 minutes</code> after ETA</b>: overdue action and search and rescue begin. <b>Close</b> the plan on arrival", "Delayed more than <code>60 minutes</code> (<code>30</code> if any of it is in controlled airspace): cancel and re-file"]], ["Briefing, weather and facilitation", ["AIS online: AIP, AICs and NOTAMs, provided by <b>NATS</b> for the CAA", "Weather: <b>self-briefing</b>, mainly from the Met Office. GAMET areas: North, Central, South-West, South-East. Report severe or unforecast weather to ATC", "<b>VOLMET</b>: VHF broadcasts of aerodrome weather. <b>ATIS</b>: recorded aerodrome information (separate arrival and departure ATIS at big airports)", "<b>General Aviation Report (GAR)</b>: for flights to or from the UK, including the Channel Islands, unless outbound directly to the EU (not Ireland)", "Airfields: <b>designated</b>; non-designated with a <b>Certificate of Agreement</b>; others (police permission, 12 hours' notice)", "Common Travel Area: GB, Channel Islands, Isle of Man, Northern Ireland, Republic of Ireland", "Eurocontrol charges exempt: entirely VFR flights, flights returning to the same aerodrome, MTOW under 2,000 kg"]]], "cards": [["Annex covering ATS?", "ICAO Annex 11."], ["Five objectives of ATS?", "Prevent collisions in the air and on the manoeuvring area, expedite flow, give advice and information, alert SAR."], ["Which VFR flights receive an ATC service?", "VFR in Classes B, C and D, and all Special VFR."], ["Class D: are VFR separated?", "No: they get traffic information on all other flights."], ["Class C: IFR separated from?", "Other IFR and VFR."], ["Class E: who needs a clearance?", "IFR only."], ["ACC services?", "ATC on airways, FIS and alerting, Distress and Diversion."], ["Arriving aircraft normally call?", "Approach first."], ["Departing aircraft normally call?", "Aerodrome Control (Ground or Tower) first."], ["Unsuitable clearance?", "Request an alternative before deviating."], ["AFIS callsign suffix?", "Information."], ["Can AFIS instruct an aircraft in the air?", "No: information only (instructions on the ground)."], ["A/G callsign suffix?", "Radio."], ["Safetycom frequency?", "135.480 MHz."], ["When to use Safetycom?", "Below 2,000 ft aal (or 1,000 ft above circuit height) and within 10 nm."], ["LARS limits?", "Up to FL100, within about 30 nm of the unit."], ["LARS: no answer after how many calls?", "Three: assume it is closed."], ["The four UK FIS?", "Basic, Traffic, Deconfliction, Procedural."], ["Who can give a Traffic Service?", "Only a controller with radar."], ["Which service can a FISO give?", "Only a Basic Service."], ["Basic Service: traffic information?", "Not to be expected."], ["Traffic Service: headings given to deconflict?", "No: only for positioning or sequencing."], ["Deconfliction minima vs unknown traffic?", "5 nm laterally or 3,000 ft vertically."], ["Deconfliction minima, same controller?", "3 nm and 1,000 ft."], ["Deconfliction below the terrain safe level?", "Not given: expect a Traffic Service."], ["Procedural Service: needs radar?", "No."], ["Who avoids collisions in Class G?", "The pilot, whatever the service."], ["Flight plan form?", "CA48 (or online via AFPEx)."], ["Does a flight plan count as PPR?", "No."], ["When is a flight plan advisable?", "More than 10 nm from the coast, or over sparsely populated or mountainous areas."], ["Overdue action starts when?", "30 minutes after ETA."], ["Departure delayed: when must you re-file?", "Over 60 minutes (30 if in controlled airspace)."], ["Flight plan required for MTOW over?", "5,700 kg with a destination over 40 km away."], ["What is ATIS?", "Recorded aerodrome information on a dedicated frequency."], ["What is a GAR?", "General Aviation Report for the Police and Border Force."], ["Eurocontrol charge exemptions?", "All-VFR flights, same aerodrome out and back, MTOW under 2,000 kg."]], "quiz": [["What is an alerting service?", ["A service to notify organisations of aircraft in need of search and rescue aid, and assist them", "A service from the Distress and Diversion cell only", "A network of civil and military radio stations", "A service to notify organisations of aircraft needing navigational help"], 0, "Alerting is about search and rescue. Navigational help is a different matter, and D&D is one provider, not the definition."], ["LARS is available outside controlled airspace:", ["Up to FL100, within about 30 nm, giving Traffic and Deconfliction Services", "Up to FL80, within about 30 nm, giving Traffic and Procedural Services", "Up to FL100, within about 25 nm, giving Procedural and Deconfliction Services", "Up to FL80, within about 25 nm, giving Deconfliction and Traffic Services"], 0, "FL100 and 30 nm. LARS is radar-based, so not Procedural. (Units also give a Basic Service.)"], ["An aerodrome Flight Information Service provides:", ["Information useful for safe and efficient flight within the ATZ", "Instructions and advice to aircraft in the ATZ", "Clearances to operate within the ATZ", "Information for flights in a CTR"], 0, "AFIS is information only, in the ATZ. It cannot clear or instruct aircraft in the air."], ["You receive an ATC clearance you consider unsuitable. You should:", ["Request an alternative clearance", "Ignore it and continue as planned", "Comply even though it is unsuitable", "Comply with as much as you can"], 0, "Ask for an alternative before deviating."], ["The purpose of a Basic Service is to:", ["Provide information useful for the safe and efficient conduct of flight", "Give radar-derived traffic warnings", "Deconflict aircraft outside controlled airspace", "Separate aircraft outside controlled airspace"], 0, "Basic is advice and information. Radar traffic information is a Traffic Service; deconfliction is a Deconfliction Service."], ["A flight plan was filed for a flight in controlled airspace and departure is delayed. After how long must a delay message be sent?", ["30 minutes", "45 minutes", "60 minutes", "2 hours"], 0, "30 minutes where the flight enters controlled airspace; the chapter gives 60 minutes for other flights."], ["Apart from when it is required, a flight plan is advisable when flying:", ["More than 10 nm from the coast, or over sparsely populated or mountainous areas", "More than 10 km from the coast, or over sparsely populated or mountainous areas", "Through more than one ATZ", "To a destination more than 40 km away"], 0, "10 nautical miles, not km. 40 km is part of a mandatory case (with MTOW over 5,700 kg)."], ["In Class D airspace, VFR flights:", ["Get traffic information on all other flights but are not separated", "Are separated from IFR flights", "Are separated from all other flights", "Need no clearance"], 0, "In Class D only IFR are separated from IFR. VFR get traffic information. Separation of VFR from IFR is Class C."], ["In Class C airspace, IFR flights are separated from:", ["Other IFR flights and VFR flights", "Other IFR flights only", "VFR flights only", "Nobody"], 0, "Class C: IFR from IFR and VFR. Class D and E: IFR from IFR only."], ["In Class E airspace, an ATC clearance is needed for:", ["IFR flights only", "VFR flights only", "All flights", "No flights"], 0, "Class E: IFR need a clearance; VFR do not."], ["ATC provides an air traffic control service to all VFR flights in Classes:", ["B, C and D", "A, B, C and D", "C, D and E", "D and E"], 0, "VFR is not allowed in Class A, and VFR in Class E get no ATC service."], ["At an AFIS aerodrome, an aircraft in the air may receive:", ["Information only", "Instructions to land", "A clearance to enter the ATZ", "Separation from other traffic"], 0, "AFIS gives information to aircraft in the air; on the ground it can give instructions."], ["A station calling itself \"Nottingham Radio\" provides:", ["An air/ground communication service", "Air traffic control", "An aerodrome flight information service", "A radar service"], 0, "Radio = A/G; Information = AFIS; Tower, Approach, Ground = ATC."], ["Safetycom (135.480 MHz) should only be used:", ["Below 2,000 ft aal (or 1,000 ft above circuit height) and within 10 nm of the landing aerodrome", "Below 3,000 ft and within 10 nm", "Anywhere below FL100", "Within 5 nm and below 1,000 ft"], 0, "Below 2,000 ft aal and within 10 nm, to limit congestion on a shared frequency."], ["Which service can a FISO provide?", ["Basic Service only", "Basic and Traffic", "Traffic and Deconfliction", "All four"], 0, "FISOs are not licensed for Traffic, Deconfliction or Procedural Services."], ["Under a Traffic Service, the controller may give headings:", ["For positioning or sequencing, not to deconflict", "To achieve the deconfliction minima", "Never", "Only in IMC"], 0, "Deconfliction headings are a Deconfliction Service. Under a Traffic Service, avoidance is up to you."], ["The deconfliction minima against unknown traffic are:", ["5 nm laterally or 3,000 ft vertically", "3 nm laterally or 1,000 ft vertically", "5 nm laterally and 1,000 ft vertically", "10 nm or 5,000 ft"], 0, "5 nm or 3,000 ft; between aircraft on the same controller, 3 nm and 1,000 ft."], ["Under a Deconfliction Service you decide not to follow an avoiding action instruction. Then:", ["You become responsible for avoiding that conflicting aircraft", "The controller remains responsible", "The service is cancelled automatically", "You must land at once"], 0, "Traffic avoidance is ultimately yours; ignoring the advice makes avoiding that aircraft your own task."], ["You ask to descend below the unit's terrain safe level while under a Deconfliction Service. Expect:", ["A Traffic Service instead", "The same service, with terrain warnings", "A Procedural Service", "No service at all"], 0, "Deconfliction is only given at or above the terrain safe level."], ["Under a Procedural Service:", ["You are deconflicted only from other aircraft taking part in it", "You are deconflicted from all traffic", "You receive radar traffic information", "You must be identified"], 0, "No radar: other Class G traffic may not be talking to the unit, so conflicts can appear without warning."], ["Who is ultimately responsible for collision avoidance in Class G when receiving a Deconfliction Service?", ["The pilot", "The controller", "Both equally", "The LARS unit"], 0, "In Class G the pilot is ultimately responsible for collision avoidance and terrain clearance under every service."], ["Under a Basic Service with no agreement, may you change level without telling the controller?", ["Yes", "No, never", "Only above 3,000 ft", "Only in VMC"], 0, "Basic allows maximum autonomy; only an agreement ties you to a level or route."], ["Normally, an arriving aircraft first contacts:", ["Approach Control", "Aerodrome Control (Tower)", "Ground", "The ACC"], 0, "Arrivals call Approach first; departures call the aerodrome controller first."], ["Which flight must file a flight plan?", ["Any flight crossing the UK FIR boundary", "A VFR flight in Class G over 40 km", "Any flight over the sea", "IFR in the Open-FIR"], 0, "Crossing the FIR boundary always needs one. IFR in the Open-FIR does not on its own; distance alone (without MTOW over 5,700 kg) does not."], ["You land somewhere other than your flight-plan destination. You must:", ["Tell your original destination (or parent ATSU) so overdue action is not started", "Do nothing; the plan closes itself", "Phone London Information only if it is after dark", "Re-file a new flight plan"], 0, "Overdue action starts 30 minutes after your ETA, so tell them you have landed elsewhere."], ["Does filing a flight plan give you prior permission to land at a PPR aerodrome?", ["No", "Yes", "Only if the destination has ATC", "Only for IFR flights"], 0, "PPR must be obtained separately from the aerodrome."], ["Overdue action begins if you have not arrived within:", ["30 minutes of your ETA", "15 minutes of your ETA", "60 minutes of your ETA", "2 hours of departure"], 0, "30 minutes after ETA."], ["Which flights are exempt from Eurocontrol en-route charges?", ["Flights made entirely under VFR", "Flights by aircraft over 2,000 kg", "Flights between different aerodromes under IFR", "All flights below FL100"], 0, "Exempt: all-VFR flights, flights returning to the same aerodrome, and aircraft under 2,000 kg MTOW."], ["ATIS is:", ["Recorded aerodrome information broadcast on its own frequency", "A live weather broadcast for en-route aerodromes", "A radar service", "An automatic terrain warning"], 0, "ATIS reduces load on the ATC frequency. VOLMET broadcasts weather for several aerodromes."]]});
Object.assign(SUM,{"ICAO Annex 11: objectives of ATS": "Prevent collisions, keep traffic flowing, give information, alert SAR.", "Services in each airspace class": "C separates IFR from everyone; D gives VFR traffic information only; E clears IFR only.", "ATS units in the UK": "ACC for airways; Ground, Tower and Approach at aerodromes; ask before deviating from a clearance.", "AFIS, A/G radio and Safetycom": "Information (no air instructions), Radio (A/G), Safetycom 135.480 below 2,000 ft within 10 nm.", "Lower Airspace Radar Service (LARS)": "Up to FL100, within about 30 nm; three calls then give up.", "UK Flight Information Services (CAP 774)": "Basic, Traffic, Deconfliction, Procedural; the pilot always avoids traffic and terrain.", "Basic Service": "Information only; no traffic information expected.", "Traffic Service": "Radar traffic information; headings only for sequencing.", "Deconfliction Service": "IFR; headings and levels aiming for 5 nm or 3,000 ft.", "Procedural Service": "No radar; separates only participating aircraft.", "Flight plans": "Required cases, booking out, 30 minutes overdue, re-file after 60 (30) minutes' delay.", "Briefing, weather and facilitation": "AIS, Met Office, ATIS and VOLMET; GAR and designated airports."});
NOTES.push({"s": 0, "topic": "Visual Flight Rules", "num": 8, "order": 80, "conf": "weak", "status": "draft", "summary": "VFR keeps you in sight of the ground and clear of cloud. Above FL100 you need 8 km visibility, below it 5 km, and 1,500 m horizontally and 1,000 ft vertically from cloud, except in Class F and G at or below 3,000 ft, where clear of cloud with the surface in sight will do (and 1,500 m visibility at 140 kt or less). The UK lets you fly clear of cloud in Class D below 3,000 ft by day at 140 kt or less. A CTR aerodrome needs 5 km and a 1,500 ft ceiling unless you are Special VFR. At night: ceiling 1,500 ft, ground visibility 5 km, 1,000 ft (2,000 ft over high ground) above obstacles within 8 km.", "sections": [["Visual Flight Rules (SERA.5005)", ["A basic PPL holder (no IR(R) or IR) needs <b class=\"k\">visual reference</b> outside for both <b class=\"k\">attitude</b> and <b class=\"k\">navigation</b>. Losing it, for example by entering cloud or poor visibility, can be disastrous.", "The <b class=\"k\">Visual Flight Rules (VFR)</b> set minimum <b class=\"k\">flight visibility</b> and <b class=\"k\">distance from cloud</b>. Conditions that meet them are <b class=\"k\">Visual Meteorological Conditions (VMC)</b>.", "Starting point: flight visibility <code>8 km</code>, <code>1,500 m</code> horizontally and <code>1,000 ft</code> vertically from cloud. Below <b class=\"k\">FL100</b> the visibility minimum drops to <code>5 km</code>.", "Only two flight categories exist: <b class=\"k\">VFR</b> or <b class=\"k\">IFR</b>."]], ["VMC minima by airspace class (SERA.5001)", ["<b>At and above <code>10,000 ft</code> amsl (FL100)</b>: Class A B C D E F G; Flight visibility <code>8 km</code>; Distance from cloud <code>1,500 m</code> horizontally, <code>1,000 ft</code> vertically", "<b>Below <code>10,000 ft</code>, above <code>3,000 ft</code> amsl or <code>1,000 ft</code> above terrain (whichever is higher)</b>: Class A B C D E F G; Flight visibility <code>5 km</code>; Distance from cloud <code>1,500 m</code> horizontally, <code>1,000 ft</code> vertically", "<b>At and below <code>3,000 ft</code> amsl or <code>1,000 ft</code> above terrain (whichever is higher)</b>: Class A B C D E; Flight visibility <code>5 km</code>; Distance from cloud <code>1,500 m</code> horizontally, <code>1,000 ft</code> vertically", "<b>At and below <code>3,000 ft</code> amsl or <code>1,000 ft</code> above terrain (whichever is higher)</b>: Class F G; Flight visibility <code>5 km</code> (can be less, see below); Distance from cloud <b class=\"k\">Clear of cloud</b> with the <b class=\"k\">surface in sight</b>", "Class A minima are guidance only: <b class=\"k\">VFR is not allowed in Class A</b>.", "If the transition altitude is lower than <code>10,000 ft</code>, use <b class=\"k\">FL100</b> instead of <code>10,000 ft</code>.", "In <b class=\"k\">F and G</b> the visibility may be reduced to <code>1,500 m</code> when flying at <code>140 kt</code> IAS or less (time to see and avoid traffic and obstacles), or where meeting other traffic is unlikely. <b class=\"k\">Helicopters</b> may go down to <code>800 m</code> if flown slowly enough to see and avoid.", "<code>UK Class D</code> (at or below <code>3,000 ft</code> amsl or <code>1,000 ft</code> above terrain, whichever is higher): you meet SERA.5001 if you fly <b class=\"k\">by day</b>, at <code>140 kt</code> IAS or less, <b class=\"k\">clear of cloud with the surface in sight</b>, with flight visibility at least <code>5 km</code> (helicopters <code>1,500 m</code>).", "<b>Note</b> Under VFR the pilot alone is responsible for the safety of the flight, separation from other aircraft, terrain clearance and staying far enough from cloud in adequate visibility."]], ["VFR into a control zone", ["Unless cleared <b class=\"k\">Special VFR</b>, a VFR flight must not take off or land at an aerodrome in a <b class=\"k\">control zone</b>, or enter its <b class=\"k\">ATZ or circuit</b>, when the reported ground visibility is less than <code>5 km</code> or the cloud ceiling is less than <code>1,500 ft</code>."]], ["VFR flight plan and ATC clearance", ["In <b class=\"k\">Class C and D</b>, the pilot-in-command must give flight details to the ATC unit and get an <b class=\"k\">ATC clearance</b> (the unit may waive this). The details must be enough to issue a clearance and for <b class=\"k\">search and rescue</b>.", "Keep a <b class=\"k\">continuous listening watch</b> on the frequency and <b class=\"k\">comply with ATC instructions</b>.", "Exemptions (in practice Class D only):", "– <b class=\"k\">gliders</b> with <code>8 km</code> visibility, <code>1,500 m</code> horizontally and <code>1,000 ft</code> vertically from cloud", "– <b class=\"k\">non-radio powered aircraft</b> by <b class=\"k\">day</b> with <code>5 km</code> visibility, <code>1,500 m</code> and <code>1,000 ft</code> from cloud, with <b class=\"k\">prior ATC permission</b>"]], ["Night VFR", ["<code>Night</code> (ANO): from <b class=\"k\">half an hour after sunset</b> to <b class=\"k\">half an hour before sunrise</b>, measured at the surface.", "Minima for VFR at night:", "– <b class=\"k\">cloud ceiling</b> at least <code>1,500 ft</code> (<code>450 m</code>). The book says \"AMSL\" in the licences chapter, but a ceiling is measured <b class=\"k\">above ground or water</b>.", "– <b class=\"k\">ground visibility</b> at least <code>5 km</code>", "– at or below <code>3,000 ft</code> amsl (or <code>1,000 ft</code> above terrain), keep <b class=\"k\">sight of the surface</b>", "– except taking off or landing, at least <code>1,000 ft</code> above the highest obstacle within <code>8 km</code> (<code>2,000 ft</code> over high or mountainous terrain)", "If leaving the <b class=\"k\">vicinity of the aerodrome</b>, file a <b class=\"k\">flight plan</b> (a full plan or an abbreviated one, i.e. booking out). Establish <b class=\"k\">two-way radio</b> contact.", "UK difference (book, licences chapter): you may fly below <code>1,000 ft</code> above obstacles within <code>8 km</code> if you stay at or below <code>3,000 ft</code> amsl, clear of cloud with the surface in sight, and still meet the low-flying rules (<code>1,000 ft</code> over congested areas within <code>600 m</code> or glide clear; <code>500 ft</code> from the ground elsewhere)."]], ["Notes on VFR", ["Always fly within the <b class=\"k\">privileges of your licence</b> (a basic PPL, for example, has no IMC privileges).", "Using <b class=\"k\">semicircular cruising levels</b> is advised even under VFR, though flying on the <b class=\"k\">Regional Pressure Setting</b> above <code>3,000 ft</code> is fine, especially when manoeuvring."]]], "cards": [["VFR flight visibility at and above FL100?", "8 km."], ["VFR flight visibility below FL100?", "5 km."], ["Distance from cloud, normal VFR?", "1,500 m horizontally and 1,000 ft vertically."], ["Class F/G at or below 3,000 ft amsl (or 1,000 ft agl if higher)?", "5 km, clear of cloud with the surface in sight."], ["When can Class G visibility drop to 1,500 m?", "At or below 3,000 ft at 140 kt IAS or less (or where traffic is unlikely)."], ["UK Class D alleviation below 3,000 ft?", "By day, 140 kt IAS or less, clear of cloud with the surface in sight, 5 km visibility."], ["Is VFR allowed in Class A?", "No. Its VMC minima are guidance only."], ["VFR into a CTR aerodrome: minimum ground visibility and ceiling?", "5 km and 1,500 ft, unless cleared Special VFR."], ["UK definition of night?", "From 30 minutes after sunset to 30 minutes before sunrise, at the surface."], ["Night VFR minimum ceiling?", "1,500 ft (450 m), measured above the ground."], ["Night VFR minimum height en route?", "1,000 ft above the highest obstacle within 8 km (2,000 ft over high terrain)."], ["Who keeps a VFR flight separated from other aircraft?", "The pilot alone."], ["What two things do Class C and D need from a VFR flight?", "Flight details to ATC and an ATC clearance (plus a listening watch)."]], "quiz": [["Between FL100 and 3,000 ft amsl in Class E, the VFR minima are:", ["5 km, 1,500 m horizontally and 1,000 ft vertically from cloud", "8 km, 1,500 m horizontally and 1,000 ft vertically from cloud", "5 km, 1,000 m horizontally and 1,500 ft vertically from cloud", "5 km, clear of cloud and in sight of the surface"], 0, "Below FL100 visibility drops to 5 km but the cloud distances stay 1,500 m and 1,000 ft. 8 km applies only at and above FL100, and the 1,000 m / 1,500 ft pair has the numbers swapped."], ["At 2,000 ft amsl in Class G by day at 120 kt, the lowest flight visibility allowed under VFR is:", ["1,500 m, clear of cloud with the surface in sight", "5 km, clear of cloud with the surface in sight", "1,500 m, 1,000 ft vertically from cloud", "800 m, clear of cloud"], 0, "In F and G at or below 3,000 ft the minimum is 5 km, but it may be 1,500 m at 140 kt IAS or less. Cloud distance is clear of cloud with the surface in sight; 800 m is for helicopters."], ["The UK Class D alleviation (clear of cloud, surface in sight) applies:", ["By day, at 140 kt IAS or less, at or below 3,000 ft amsl (or 1,000 ft above terrain if higher)", "By day or night, at 140 kt IAS or less, at or below 3,000 ft amsl", "By day, at any speed, at or below 3,000 ft amsl", "By day, at 140 kt IAS or less, at or below FL100"], 0, "All three conditions together: day, 140 kt or less, and at or below 3,000 ft amsl or 1,000 ft above terrain, with 5 km visibility."], ["Unless cleared Special VFR, you may not take off from an aerodrome in a CTR under VFR when:", ["The ground visibility is below 5 km or the cloud ceiling below 1,500 ft", "The flight visibility is below 8 km or the ceiling below 1,500 ft", "The ground visibility is below 5 km or the ceiling below 1,000 ft", "The ground visibility is below 1,500 m or the ceiling below 1,500 ft"], 0, "5 km ground visibility and a 1,500 ft ceiling. It is reported ground visibility, not flight visibility."], ["For night VFR, the cloud ceiling must be at least:", ["1,500 ft above the ground", "1,500 ft amsl", "1,000 ft above the ground", "2,000 ft above the ground"], 0, "450 m (1,500 ft). A ceiling is always measured above ground or water, so 'amsl' is the trap."], ["Except taking off or landing, a night VFR flight over ordinary terrain must stay at least:", ["1,000 ft above the highest obstacle within 8 km", "1,000 ft above the highest obstacle within 8 nm", "1,500 ft above the highest obstacle within 5 km", "500 ft above the highest obstacle within 150 m"], 0, "1,000 ft within 8 km (2,000 ft over high or mountainous terrain). 8 nm is the wrong unit; 500 ft within 150 m is the day low-flying rule."], ["Under VFR, who is responsible for separation from other aircraft and terrain?", ["The pilot alone", "ATC in controlled airspace, the pilot elsewhere", "The pilot, but ATC in Class C and D", "ATC whenever the aircraft has a clearance"], 0, "Under VFR the pilot is solely responsible for separation, terrain clearance and staying in VMC, even with a clearance."], ["A VFR flight into Class D must:", ["Give flight details to ATC, get a clearance, listen out and comply with instructions", "Book out only; no clearance is needed", "File a full flight plan at least 60 minutes before departure", "Have a transponder with Mode S"], 0, "Class C and D need flight details and a clearance, plus a listening watch. An abbreviated plan by radio is enough."]]});
Object.assign(SUM,{"Visual Flight Rules (SERA.5005)": "VFR sets minimum visibility and distance from cloud; meeting them is VMC. The baseline is 8 km, 1,500 m and 1,000 ft.", "VMC minima by airspace class (SERA.5001)": "5 km below FL100 (8 km above); 1,500 m and 1,000 ft from cloud, except F and G low down: clear of cloud, surface in sight.", "VFR into a control zone": "No VFR take-off, landing or circuit at a CTR aerodrome below 5 km ground visibility or a 1,500 ft ceiling, unless Special VFR.", "VFR flight plan and ATC clearance": "In Class C and D, give flight details, get a clearance, listen out and obey ATC.", "Night VFR": "Night is 30 minutes after sunset to 30 minutes before sunrise; ceiling 1,500 ft, 5 km, and 1,000 ft above obstacles within 8 km.", "Notes on VFR": "Stay within your licence privileges; semicircular levels are advised, but QNH/RPS is fine above 3,000 ft."});
NOTES.push({"s": 0, "topic": "Instrument Flight Rules", "num": 9, "order": 90, "conf": "weak", "status": "draft", "summary": "IFR lets trained pilots fly without visual reference. Outside take-off and landing, stay 1,000 ft above the highest obstacle within 8 km (2,000 ft over high or mountainous terrain). Above 3,000 ft amsl or the transition altitude, cruise at semicircular levels: magnetic track 000° to 179° odd thousands, 180° to 359° even thousands (VFR adds 500 ft). In controlled airspace an IFR flight needs a flight plan and clearance, and reports position as callsign, position, time, level, next position and estimate.", "sections": [["Instrument Flight Rules (SERA.5015)", ["VFR is too restrictive for regular air services, so properly trained pilots with suitable instruments can fly in cloud and other non-visual conditions under the <b class=\"k\">Instrument Flight Rules (IFR)</b>.", "Only two flight categories exist: <b class=\"k\">VFR</b> or <b class=\"k\">IFR</b>."]], ["The minimum height rule", ["Except for <b class=\"k\">take-off or landing</b>, or when specifically authorised, an IFR flight must not fly below the <b class=\"k\">minimum flight altitude</b> set by the State overflown. Where none is set:", "– over <b class=\"k\">high terrain or mountainous areas</b>: at least <code>2,000 ft</code> above the highest obstacle within <code>8 km</code> of the aircraft's estimated position", "– <code>elsewhere</code>: at least <code>1,000 ft</code> above the highest obstacle within <code>8 km</code>", "<b>Exam trap</b> The distance is <code>8 km</code> of the aircraft's position, not <code>600 m</code> (that is the congested-area low-flying rule) and not nautical miles."]], ["Cruising levels: the semicircular rule (SERA.5015, Appendix 3)", ["In level flight above <code>3,000 ft</code> amsl, or above the <b class=\"k\">transition altitude</b> if that is higher, choose a cruising level by the <b class=\"k\">semicircular rule</b>. Flight levels use <code>1013.2 hPa</code>.", "The level depends on <b class=\"k\">magnetic track</b>:", "– <code>000°</code> to <code>179°</code> (east): IFR at <b class=\"k\">odd</b> thousands (FL30, 50, 70, 90 ...); VFR at odd thousands <b class=\"k\">plus 500 ft</b> (FL35, 55, 75 ...)", "– <code>180°</code> to <code>359°</code> (west): IFR at <b class=\"k\">even</b> thousands (FL20, 40, 60, 80 ...); VFR at even thousands <b class=\"k\">plus 500 ft</b> (FL45, 65, 85 ...)", "Above FL290 the steps change (FL300, 310 ... with 1,000 ft RVSM spacing up to FL410).", "An IFR aircraft may cruise at another level when <b class=\"k\">ATC instructs</b> it or in a notified <b class=\"k\">holding procedure</b>.", "<b>Memory aid</b> <b class=\"k\">East is odd</b> (\"Every Odd Day\"), west is even."]], ["Flight plan and ATC clearance (SERA.5020)", ["Before any IFR flight in <b class=\"k\">controlled airspace</b>, the commander must <b class=\"k\">file a flight plan</b> (whether IMC or VMC) and get an <b class=\"k\">ATC clearance</b> based on it.", "In controlled airspace an IFR pilot must follow:", "– the <b class=\"k\">ATC clearance</b> and any further instructions", "– the published <b class=\"k\">holding and approach procedures</b> at the destination, unless ATC says otherwise", "You may <b class=\"k\">cancel IFR</b> and continue VFR if you can <b class=\"k\">stay in VMC</b> while in controlled airspace and you <b class=\"k\">tell ATC</b>, asking them to cancel your IFR flight plan.", "If you have to depart from these rules to <b class=\"k\">avoid immediate danger</b>, tell ATC <b class=\"k\">as soon as possible</b>.", "Unless the flight plan has been cancelled, tell ATC when you <b class=\"k\">land within</b> or <b class=\"k\">leave</b> controlled airspace."]], ["Position reports (SERA.5025)", ["An IFR flight in, or about to enter, controlled airspace reports <b class=\"k\">time, position and level</b> at notified reporting points or intervals, or when ATC asks.", "Order: <b class=\"k\">aircraft callsign</b>, <b class=\"k\">position</b>, <b class=\"k\">time</b>, <b class=\"k\">level</b>, <b class=\"k\">next position and estimate</b>.", "Example: \"G-ABCD, Wicken four seven, flight level four zero, Marlow five seven\"."]]], "cards": [["IFR minimum height, ordinary terrain?", "1,000 ft above the highest obstacle within 8 km of the aircraft."], ["IFR minimum height over high or mountainous terrain?", "2,000 ft above the highest obstacle within 8 km."], ["When does the semicircular rule apply?", "In level flight above 3,000 ft amsl or the transition altitude, whichever is higher."], ["IFR level for magnetic track 090°?", "Odd thousands: FL30, 50, 70 ..."], ["IFR level for magnetic track 270°?", "Even thousands: FL40, 60, 80 ..."], ["VFR semicircular level for track 045°?", "Odd plus 500 ft: FL35, 55, 75 ..."], ["What two things must an IFR flight have in controlled airspace?", "A filed flight plan and an ATC clearance."], ["Can an IFR flight switch to VFR in CAS?", "Yes, if it can stay in VMC and tells ATC to cancel its IFR flight plan."], ["Order of an IFR position report?", "Callsign, position, time, level, next position and estimate."], ["Is the semicircular rule based on true or magnetic track?", "Magnetic track."]], "quiz": [["The minimum height for IFR flight over non-mountainous terrain is:", ["1,000 ft above the highest obstacle within 8 km of the aircraft", "1,000 ft above the highest obstacle within 600 m", "1,500 ft above the highest obstacle within 10 nm", "1,000 ft above ground level"], 0, "SERA.5015: 1,000 ft within 8 km (2,000 ft over high terrain). The 600 m figure belongs to the congested-area low-flying rule."], ["Over mountainous terrain an IFR flight must be at least:", ["2,000 ft above the highest obstacle within 8 km", "2,000 ft above the highest obstacle within 8 nm", "1,000 ft above the highest obstacle within 8 km", "1,500 ft above the highest obstacle within 5 km"], 0, "Mountainous areas double the margin to 2,000 ft; the radius stays 8 km."], ["An IFR flight on a magnetic track of 175° should cruise at:", ["FL70", "FL80", "FL75", "FL60"], 0, "000° to 179° takes odd thousands, so FL70. FL75 would be a VFR level; FL80 and FL60 are for westbound tracks."], ["A VFR flight on a magnetic track of 260° following the semicircular rule would choose:", ["FL65", "FL55", "FL60", "FL70"], 0, "180° to 359° is even thousands; VFR adds 500 ft, giving FL45, 65, 85. FL60 is the IFR level."], ["Above which level does the semicircular rule apply in level flight?", ["3,000 ft amsl or the transition altitude, whichever is higher", "3,000 ft amsl or the transition altitude, whichever is lower", "FL100", "The transition level"], 0, "The higher of 3,000 ft amsl and the transition altitude."], ["Before an IFR flight in controlled airspace in VMC, the commander must:", ["File a flight plan and obtain an ATC clearance based on it", "Obtain an ATC clearance; a flight plan is needed only in IMC", "File a flight plan; no clearance is needed in VMC", "Book out with the departure aerodrome only"], 0, "SERA.5020: flight plan and clearance, whether IMC or VMC."], ["The correct order for an IFR position report is:", ["Callsign, position, time, level, next position and estimate", "Callsign, position, level, next position and estimate", "Ground station, position, time, level, next position and estimate", "Callsign, position, time, next position, level and estimate"], 0, "Time comes after position and level after time. Leaving out the time, or starting with the ground station, is the trap."], ["An IFR flight in controlled airspace in VMC wishes to continue VFR. It must:", ["Stay in VMC and tell ATC, asking them to cancel its IFR flight plan", "Leave controlled airspace first", "Simply change its squawk to 7000", "Get a Special VFR clearance"], 0, "Cancelling IFR is allowed if you can stay in VMC and tell ATC."]]});
Object.assign(SUM,{"Instrument Flight Rules (SERA.5015)": "IFR is for flight without visual reference; every flight is either VFR or IFR.", "The minimum height rule": "1,000 ft above the highest obstacle within 8 km, or 2,000 ft over high or mountainous terrain.", "Cruising levels: the semicircular rule (SERA.5015, Appendix 3)": "Track 000° to 179°: odd thousands; 180° to 359°: even thousands. VFR adds 500 ft.", "Flight plan and ATC clearance (SERA.5020)": "IFR in controlled airspace: file a flight plan and get a clearance, whatever the weather.", "Position reports (SERA.5025)": "Callsign, position, time, level, next position and estimate."});
NOTES.push({"s": 0, "topic": "Registration and Airworthiness", "num": 10, "order": 100, "conf": "weak", "status": "draft", "summary": "Annex 7 sets the registration marks: nationality mark first, a hyphen before a letter, once under the left wing (50 cm high) and on the fuselage or fin (30 cm), characters two-thirds as wide as high, plus a fireproof plate by the door. In the UK an aircraft must be registered, and changes go to the CAA in writing. Part-21 aircraft have a non-expiring CofA kept alive by an annual ARC; non-approved maintenance or modification makes the CofA invalid. Maintenance needs a Certificate of Release to Service, defects go in the tech log, logbooks are kept 2 years after the aircraft goes, and an old weight schedule 6 months.", "sections": [["Registration and Marking of Aircraft (ICAO Annex 7)", ["<b class=\"k\">Annex 7</b> sets the minimum standards for displaying <b class=\"k\">nationality and registration marks</b>."]], ["The marks", ["A group of <b class=\"k\">letter</b>s and/or numbers, e.g. <b class=\"k\">G-AGOH</b>, N7207V. The <b class=\"k\">nationality mark comes first</b>. If the registration mark starts with a letter, put a <b class=\"k\">hyphen</b> between them (F-BUDG).", "The <b class=\"k\">State of Registry</b> assigns the registration mark."]], ["Where the marks go", ["<b class=\"k\">Painted on or permanently fixed</b>, kept <b class=\"k\">clean and visible</b>.", "<code>Heavier-than-air aircraft</code>:", "– <b class=\"k\">once on the lower surface of the wing</b>, on the <b class=\"k\">left</b> half (unless across the whole wing), tops of the letters towards the <b class=\"k\">leading edge</b>, midway between leading and trailing edge", "– on <b class=\"k\">both sides of the fuselage</b> between wings and tail, <b class=\"k\">or</b> on the upper halves of the <b class=\"k\">vertical tail</b> (both sides of a single fin)", "<code>Balloons</code>: each side, near the widest part. Other lighter-than-air aircraft: visible from the sides and from the ground."]], ["Size and lettering", ["<b>Lighter-than-air aircraft</b>: <code>50 cm</code>", "<b>Wings of heavier-than-air aircraft</b>: <code>50 cm</code>", "<b>Fuselage or vertical tail</b>: <code>30 cm</code>", "<b class=\"k\">Roman capitals</b> and <b class=\"k\">Arabic numerals</b>, no ornamentation. Each character <b class=\"k\">two-thirds as wide as it is high</b> (except I and 1), solid lines, in a <b class=\"k\">contrasting colour</b>."]], ["Identification plate", ["A <b class=\"k\">fireproof</b> plate (metal or similar) with the nationality and registration marks, fixed <b class=\"k\">near the main entrance</b>."]], ["Registration in the UK (ANO Articles 24-26, Schedule 4)", ["In practice you must <b class=\"k\">not fly in the UK</b> unless the aircraft is <b class=\"k\">registered</b> (in the UK or elsewhere) and shows its marks.", "Register under the <b class=\"k\">General Classification of Aircraft</b> (ANO Schedule 4).", "Owners and part-owners must tell the CAA <b class=\"k\">in writing</b> of any change: ownership, <b class=\"k\">destruction</b>, or <b class=\"k\">permanent withdrawal</b> from use.", "Some aircraft need not be registered: non-Part-21 <b class=\"k\">gliders and hang-gliders</b>, and in some cases powered aircraft on <b class=\"k\">test, certification or demonstration</b> flights.", "Flying an unregistered aircraft does not excuse any other ANO offence on that flight."]], ["General classification of aircraft", ["<b class=\"k\">Lighter than air</b>", "– non-power-driven: <b class=\"k\">free balloon</b>, <b class=\"k\">captive balloon</b>", "– power-driven: <b class=\"k\">airship</b>", "<b class=\"k\">Heavier than air</b>", "– non-power-driven: <b class=\"k\">glider</b> (including hang-gliders), <b class=\"k\">kite</b>", "– power-driven (flying machines): <b class=\"k\">aeroplane</b> (landplane, seaplane, amphibian, self-launching motor glider; includes microlights and powered parachutes), <b class=\"k\">powered lift</b> (tilt rotor), <b class=\"k\">rotorcraft</b> (helicopter, gyroplane)"]], ["Airworthiness (ICAO Annex 8; ANO Part 4; UK Basic Regulation)", ["<b class=\"k\">Annex 8</b> sets the minimum airworthiness standards that let one State recognise another's <b class=\"k\">Certificate of Airworthiness (CofA)</b>.", "Since <b class=\"k\">1 January 2021</b> EASA rules became UK law (retained, now <b class=\"k\">assimilated</b> law). The old \"EASA\" and \"Annex I / non-EASA\" aircraft are now <b class=\"k\">Part-21</b> and <b class=\"k\">non-Part-21</b> aircraft.", "– <code>Part-21</code>: airworthiness, operations and licensing under the <b class=\"k\">UK Basic Regulation</b>", "– <code>non-Part-21</code>: the <b class=\"k\">ANO</b> and <b class=\"k\">British Civil Airworthiness Requirements (BCAR)</b>", "<code>Part-21 CofA</code>: <b class=\"k\">non-expiring</b>, kept in force by an annual <b class=\"k\">Airworthiness Review Certificate (ARC)</b>. A non-<b class=\"k\">Part-21 CofA</b> (book): issued for <b class=\"k\">3 years</b>.", "The CofA is <b class=\"k\">invalid</b> if the aircraft is <b class=\"k\">modified, repaired or maintained</b> in a <b class=\"k\">non-approved</b> way, and that can also void the <b class=\"k\">insurance</b>.", "The <b class=\"k\">Flight Manual (POH)</b> is part of the aircraft's equipment and must be available to the pilot at all times. The CAA may add supplements for aircraft built abroad.", "Fly only within the conditions of a valid CofA, e.g. towing a glider needs that approval (ANO Article 87).", "No valid CofA but needs to fly (e.g. test flights for a CofA): a <b class=\"k\">Permit to Fly</b>."]], ["Maintenance", ["<code>Part-21</code>: maintained to an approved <b class=\"k\">aircraft maintenance programme</b>.", "<code>Non-Part-21</code> (not LAA): normally the <b class=\"k\">Light Aircraft Maintenance Schedule (LAMS)</b>, with a <b class=\"k\">Certificate of Maintenance Review</b> every <b class=\"k\">12 months</b> (aircraft under <code>2,730 kg</code>). The <b class=\"k\">Part-21</b> equivalent is the <b class=\"k\">ARC</b>.", "Owners of Part-21 aircraft need the <b class=\"k\">CAMO</b>'s agreement before doing their own maintenance.", "<code>Technical Log</code>: flight times, defects and maintenance. Enter a defect <b class=\"k\">before the next pilot flies</b> or at the <b class=\"k\">end of the day</b>, whichever is earlier.", "<code>Certificate of Release to Service (CRS)</code>: needed, as well as the CofA, after the aircraft or any part needed for airworthiness is <b class=\"k\">overhauled, repaired, replaced, modified or otherwise maintained</b>. Only authorised people may sign it, though pilot-owners may do certain listed <b class=\"k\">minor maintenance</b> (Part-ML / ANGR).", "<code>Logbooks</code>: aircraft, engine and (if fitted) <b class=\"k\">variable-pitch propeller</b> logbooks, kept for <b class=\"k\">2 years</b> after the aircraft, engine or propeller is destroyed or permanently withdrawn."]], ["Temporary loss of airworthiness (Annex 8)", ["An aircraft not kept airworthy <b class=\"k\">cannot fly</b> until it is restored.", "If damaged, the <b class=\"k\">State of Registry</b> decides whether it is still airworthy. If the damage happens abroad, that State may stop the flight but must tell the State of Registry at once; the State of Registry may allow a <b class=\"k\">ferry flight</b> without fare-paying passengers to a repair base."]], ["Mass and balance (ANO Article 43)", ["The aircraft is <b class=\"k\">weighed</b> and its <b class=\"k\">centre of gravity</b> found; the operator prepares a <b class=\"k\">Weight Schedule</b>. When a new one is made, keep the old one for <b class=\"k\">6 months</b>."]], ["Flight Manual, limitations and placards (Annex 8)", ["Limitations go in the <b class=\"k\">Flight Manual</b>, on <b class=\"k\">placards</b> and as <b class=\"k\">instrument markings</b>: loading (masses, CG, floor loads), airspeeds (e.g. <b class=\"k\">VNE</b>, <b class=\"k\">VFE</b>), powerplant, systems and miscellaneous.", "Where a limit could be exceeded in flight, the crew must be able to see it on their <b class=\"k\">instruments</b>.", "<b class=\"k\">Empty mass</b> usually <b class=\"k\">excludes</b> crew, payload, usable fuel and drainable oil, and <b class=\"k\">includes</b> fixed ballast, unusable fuel, undrainable oil, engine coolant and hydraulic fluid.", "Flying outside the CofA or Flight Manual (non-permitted manoeuvres, overweight, CG out) can make the <b class=\"k\">CofA invalid</b>, void the <b class=\"k\">insurance</b> and leave the pilot open to a <b class=\"k\">fine or prison</b>."]], ["Equipment, noise and insurance", ["Minimum equipment: <b class=\"k\">ANO Schedule 5</b> (general) and <b class=\"k\">Schedule 6</b> (radio). Know what your operation needs, e.g. a harness for aerobatics.", "<code>Noise Certificate</code>: propeller aeroplanes up to <code>9,000 kg</code>, all helicopters and microlights, and other subsonic aeroplanes needing more than <code>610 m</code> to take off.", "<code>Insurance</code>: passenger and <b class=\"k\">third-party</b> liability cover is <b class=\"k\">mandatory</b>; <b class=\"k\">hull</b> cover is not, but you could lose a lot without it. Check the certificate is valid for the flight, and watch for <b class=\"k\">excesses</b>, exclusions (unlicensed strips, aerobatics) and <b class=\"k\">pilot warranties</b> (minimum hours). Military aerodromes may need much higher third-party cover.", "The PIC is still responsible (ANO Articles 68-69) for a safe and legal flight; insurance does not change that."]]], "cards": [["Which Annex covers registration marks?", "ICAO Annex 7."], ["When is a hyphen used in the marks?", "When the registration mark starts with a letter (G-ABCD)."], ["Where are the marks on the wing?", "Once on the lower surface, on the left half, tops towards the leading edge."], ["Minimum height of marks on the wing?", "50 cm."], ["Minimum height on fuselage or fin?", "30 cm."], ["Width of a character?", "Two-thirds of its height (except I and 1)."], ["What is the identification plate made of and where is it?", "Fireproof material, near the main entrance."], ["How long is a Part-21 CofA valid?", "It doesn't expire; it stays valid with a current ARC (yearly)."], ["What makes a CofA invalid?", "Modification, repair or maintenance in a non-approved way (and flying outside its limits)."], ["When is a Certificate of Release to Service needed?", "After the aircraft or any part is overhauled, repaired, replaced, modified or maintained."], ["Where does a pilot record a defect?", "In the technical log, before the next flight or the end of the day, whichever is earlier."], ["How long are aircraft and engine logbooks kept?", "2 years after the aircraft or engine is destroyed or permanently withdrawn."], ["How long is a superseded weight schedule kept?", "6 months."], ["Does empty mass include unusable fuel?", "Yes, and undrainable oil, fixed ballast, coolant and hydraulic fluid; not usable fuel or crew."], ["Is hull insurance a legal requirement?", "No; passenger and third-party liability cover is."]], "quiz": [["On a heavier-than-air aircraft, the registration marks on the wing must be at least:", ["50 cm high, once on the lower surface of the left wing", "30 cm high, once on the lower surface of the left wing", "50 cm high, on the upper surface of the right wing", "30 cm high, on both lower wing surfaces"], 0, "Wing marks are 50 cm, once under the left half. 30 cm is the fuselage and fin figure."], ["Each character in a registration mark must be:", ["Two-thirds as wide as it is high (except I and 1)", "Half as wide as it is high", "As wide as it is high", "Two-thirds as high as it is wide"], 0, "Two-thirds of the height, so the letters aren't stretched. The last option swaps width and height."], ["A Certificate of Airworthiness ceases to be valid:", ["If the aircraft is modified, repaired or maintained in a non-approved way", "After 5 years", "When the aircraft leaves its State of Registry", "At the end of each calendar year"], 0, "A Part-21 CofA doesn't expire; it stays valid with a current ARC unless non-approved work (or misuse) invalidates it."], ["A Part-21 aircraft's Certificate of Airworthiness is kept in force by:", ["An Airworthiness Review Certificate, renewed or extended each year", "A new CofA every 3 years", "A Certificate of Maintenance Review every 6 months", "The pilot's daily inspection"], 0, "The ARC is the annual check. The 3-year CofA and the CMR belong to non-Part-21 aircraft."], ["After an aircraft has been repaired it needs, in addition to its CofA:", ["A Certificate of Release to Service", "A new Certificate of Registration", "A Noise Certificate", "A new weight schedule"], 0, "Any overhaul, repair, replacement, modification or maintenance needs a CRS signed by an authorised person."], ["A pilot finds a defect during a flight. It must be recorded:", ["In the technical log, before the next flight or at the end of the day, whichever is earlier", "In the pilot's personal logbook", "On the Certificate of Release to Service", "In the technical log within 7 days"], 0, "The tech log records defects; the deadline is before the next pilot flies or the end of the day."], ["When a new weight schedule is prepared, the previous one must be kept for:", ["6 months", "3 months", "1 year", "2 years"], 0, "ANO Article 43: 6 months. 2 years is the logbook period."], ["Aircraft, engine and variable-pitch propeller logbooks must be kept until:", ["2 years after the aircraft, engine or propeller is destroyed or permanently withdrawn", "2 years after the last entry", "6 months after the aircraft is sold", "The next Airworthiness Review"], 0, "2 years after destruction or permanent withdrawal. '2 years after the last entry' is the rule for producing a pilot's personal logbook."], ["The owner of a UK-registered aircraft sells half of it. They must:", ["Tell the CAA in writing", "Tell the CAA within 28 days by phone", "Re-register the aircraft with new marks", "Do nothing; only a full sale needs reporting"], 0, "Any change of ownership or part-ownership is reported to the CAA in writing."], ["Which UK insurance cover is compulsory for a private aeroplane?", ["Passenger and third-party liability", "Hull only", "Hull and third-party", "None; it is the owner's choice"], 0, "Liability cover is compulsory; hull cover is optional, though wise."]]});
Object.assign(SUM,{"Registration and Marking of Aircraft (ICAO Annex 7)": "ICAO Annex 7 sets the minimum standards for nationality and registration marks.", "The marks": "Nationality mark first, then the registration mark, with a hyphen if it starts with a letter.", "Where the marks go": "Once under the left wing, and on both sides of the fuselage or fin.", "Size and lettering": "50 cm on the wing, 30 cm on fuselage or fin; plain capitals two-thirds as wide as high.", "Identification plate": "A fireproof plate with the marks, near the main entrance.", "Registration in the UK (ANO Articles 24-26, Schedule 4)": "You must fly a registered aircraft; tell the CAA in writing of changes of owner, destruction or withdrawal.", "General classification of aircraft": "Lighter or heavier than air, then power-driven or not: balloons, airships, gliders, aeroplanes, rotorcraft.", "Airworthiness (ICAO Annex 8; ANO Part 4; UK Basic Regulation)": "Part-21 aircraft: non-expiring CofA plus an annual ARC. Non-approved work invalidates the CofA.", "Maintenance": "Maintenance programme, tech log, Certificate of Release to Service after work, logbooks kept 2 years after the aircraft goes.", "Temporary loss of airworthiness (Annex 8)": "No flight until airworthiness is restored; the State of Registry decides after damage.", "Mass and balance (ANO Article 43)": "Weigh the aircraft, find the CG, make a weight schedule; keep the old one 6 months.", "Flight Manual, limitations and placards (Annex 8)": "Limits go in the Flight Manual, on placards and on the instruments.", "Equipment, noise and insurance": "Minimum equipment in ANO Schedules 5 and 6; third-party cover is compulsory, hull cover isn't."});
NOTES.push({"s": 0, "topic": "Pilots' Licences", "num": 11, "order": 110, "conf": "weak", "status": "draft", "summary": "UK Part-FCL licences (issued by the CAA) are for life, but you need a valid rating and medical to use them. A PPL(A) needs a Class 1 or 2 medical, 45 hours (25 dual, 10 solo with a 150 nm cross-country and two full-stop landings away), nine exams within 18 months, and a skill test; minimum age 17, solo from 16. Class 2 lasts 60 months under 40, 24 months from 40, 12 months from 50. The SEP rating lasts 24 months: revalidate by a proficiency check in the last 3 months, or by 12 hours in the last 12 months (6 PIC, 12 take-offs and landings, 1 hour with an instructor). To carry passengers, do 3 take-offs, approaches and landings in 90 days (one at night for night). Cost sharing: up to 6 on board, pilot pays a share.", "sections": [["Part-FCL and Part-MED", ["EASA licensing comes from the <b class=\"k\">Aircrew Regulation</b> (EU 1178/2011): <b class=\"k\">Annex I = Part-FCL</b> (licences), <b class=\"k\">Annex IV = Part-MED</b> (medicals).", "After Brexit these became <b class=\"k\">UK Part-FCL</b> and <b class=\"k\">Part-MED</b> (assimilated law). The <b class=\"k\">CAA</b> issues UK licences; they are no longer EASA licences.", "Aircraft that were \"EASA aircraft\" are now <b class=\"k\">Part-21</b> aircraft. Exceptions: State aircraft (military, customs, police) and <b class=\"k\">Annex I</b> types (microlights, home-builds, historic), now <b class=\"k\">non-Part-21</b>.", "Part-FCL licences are <b class=\"k\">ICAO-compliant</b> and <b class=\"k\">non-expiring</b>; using them depends on valid <b class=\"k\">ratings</b> and <b class=\"k\">medicals</b>. The <b class=\"k\">LAPL</b> is not ICAO-compliant."]], ["Part-FCL terms", ["<code>Category</code>: aeroplane, helicopter, glider, balloon.", "<code>Class rating</code>: a single-pilot aeroplane that needs no type rating (e.g. SEP land).", "<code>Type rating</code>: a specific aircraft type.", "<code>Flight time</code>: from when the aircraft <b class=\"k\">first moves</b> (own or external power) <b class=\"k\">to take off</b> until it <b class=\"k\">comes to rest</b> after the flight.", "<code>SPIC</code> (student pilot-in-command): the instructor only observes.", "<code>Solo flight time</code>: the student is the sole occupant.", "<b class=\"k\">Instrument time</b> = instrument flight time (sole reference to instruments) + instrument ground time (in a synthetic trainer).", "<code>Revalidation</code>: extends a rating that is <b class=\"k\">still valid</b>.", "<code>Renewal</code>: restores one that has <b class=\"k\">expired</b>.", "<code>Skill test</code>: for the <b class=\"k\">issue</b> of a licence or rating.", "<code>Proficiency check</code>: to <b class=\"k\">revalidate or renew</b> a rating. (The book swaps these two definitions.)", "<code>Touring motor glider (TMG)</code>: fixed, non-retractable engine and propeller; can take off and climb on its own power.", "<code>Private pilot</code>: may not be paid to fly (except instruction or examining).", "<code>Professional pilot</code>: may be paid.", "<code>Night</code>: in ICAO terms, end of evening civil twilight to start of morning civil twilight. In the <b class=\"k\">UK</b>, <b class=\"k\">30 minutes after sunset to 30 minutes before sunrise</b>."]], ["Student pilots", ["Training starts without a licence under an instructor. A student may fly <b class=\"k\">solo as PIC</b> if:", "– at least <code>16</code> years old", "– holds a <b class=\"k\">Class 1 or Class 2</b> medical and keeps to its limits (e.g. glasses)", "– carries <b class=\"k\">no one else</b>", "– is <b class=\"k\">authorised and supervised</b> by a flight instructor"]], ["Medicals (Part-MED)", ["A medical by an <b class=\"k\">Authorised Medical Examiner (AME)</b> is needed before applying for and while using a licence.", "<code>PPL(A)</code>: <b class=\"k\">Class 2</b> (or <b class=\"k\">Class 1</b>).", "<code>LAPL</code>: <b class=\"k\">LAPL</b> medical (or <b class=\"k\">Class 1</b> or 2).", "Professional pilots: <b class=\"k\">Class 1</b>."]], ["Class 2 validity", ["<b>Under <code>40</code></b>: <code>60 months</code>", "<b><code>40</code> to <code>49</code></b>: <code>24 months</code>", "<b><code>50</code> and over</b>: <code>12 months</code>", "Valid for its full period even if you move into the next age group, <b class=\"k\">but</b>: issued before <b class=\"k\">40</b> → not valid after age <b class=\"k\">42</b>; issued before <b class=\"k\">50</b> → not valid after age <b class=\"k\">51</b>.", "Renew up to <code>45 days</code> before expiry without losing time (the new one runs from the old expiry). An initial medical runs from the date of the assessment.", "<code>LAPL medical</code>: an AME or a <b class=\"k\">GP</b>; <code>60 months</code> until 40 (not valid after 42), then <code>24 months</code>."]], ["Decrease in medical fitness", ["Don't fly if you <b class=\"k\">know or suspect</b> you are unfit. Get advice from an <b class=\"k\">AME or AeMC</b> without delay after:", "– surgery or an invasive procedure", "– regular use of medication", "– significant injury or illness", "– pregnancy", "– admission to hospital or a medical clinic", "– first needing corrective lenses", "Rules of thumb: local anaesthetic <code>12 h</code>, general anaesthetic <code>48 h</code>, blood donation <code>24 h</code> (bone marrow with a general: <code>48 h</code>). Pregnancy: once assessed fit, flying up to the <b class=\"k\">26th week</b>.", "<code>Pilot Medical Declaration (PMD)</code>: for some UK licences, flying <b class=\"k\">G-registered aircraft in UK airspace</b>, if you meet the <b class=\"k\">DVLA Group 1 (car)</b> standard."]], ["The PPL(A)", ["Minimum age <code>17</code> (solo from 16). Train at an <b class=\"k\">ATO or DTO</b>. The CAA must be satisfied you are fit, knowledgeable and skilled.", "<code>Theory</code>: <b class=\"k\">9 exams</b> (Air Law, Operational Procedures, Navigation, Meteorology, Aircraft General Knowledge, Principles of Flight, Human Performance, Flight Performance and Planning, Communications), all within <code>18 months</code> from the end of the month of the first pass. Credit then lasts <code>24 months</code> for licence issue.", "Also a <b class=\"k\">radiotelephony practical</b>, and a <b class=\"k\">skill test</b> with an oral.", "<code>Flying</code>: at least <code>45 h</code>, including <code>25 h</code> dual and <code>10 h</code> supervised solo, of which <code>5 h</code> solo cross-country with one flight of at least <code>270 km</code> (<code>150 nm</code>) and <b class=\"k\">two full-stop landings</b> at other aerodromes.", "Pilots of another category (not balloons) may credit <b class=\"k\">10%</b> of their PIC time, up to <code>10 h</code> (not against the solo cross-country).", "Not valid until <b class=\"k\">signed in ink</b> by the holder. Then valid for <b class=\"k\">life</b>.", "A Part-FCL PPL(A) is also valid, with the same privileges, on <b class=\"k\">non-Part-21</b> aircraft of the same class."]], ["Privileges", ["PIC or co-pilot of <b class=\"k\">aeroplanes or TMGs</b> on <b class=\"k\">non-commercial</b> flights, with a <b class=\"k\">valid class or type rating</b> and a <b class=\"k\">valid Class 1 or 2 medical</b>.", "No pay, except as an <b class=\"k\">instructor or examiner</b> for the LAPL(A)/PPL(A).", "<code>Cost sharing</code>: allowed on private flights with up to <code>6</code> people on board, <b class=\"k\">including the pilot</b>, as long as <b class=\"k\">everyone shares the direct costs, pilot included</b>.", "Glider towing or parachute dropping for pay is commercial, except at clubs whose aim is training or promoting aviation."]], ["Passenger recency (FCL.060)", ["To carry passengers: <b class=\"k\">3 take-offs, approaches and landings</b> in the preceding <code>90 days</code>, in the same type or class (as sole manipulator of the controls).", "At <b class=\"k\">night</b>: at least <b class=\"k\">one</b> of the three at night, unless you hold an <b class=\"k\">IR</b>."]], ["FRTOL", ["A <b class=\"k\">Flight Radiotelephony Operator's Licence</b> is needed to use the radio (students have a dispensation). Pass the Communications exam before the licence; the practical can follow."]], ["Ratings", ["<code>SEP (land)</code>: almost all single-engine piston aeroplanes. Also MEP (land) and single-pilot (sea).", "<code>Differences training</code> (logged, with an instructor): variable-pitch propeller, retractable gear, turbo/supercharging, pressurisation, <b class=\"k\">tailwheel</b>, single-lever power control, glass cockpits."]], ["Revalidating the SEP class rating (valid 24 months)", ["<b class=\"k\">Either</b> a <b class=\"k\">proficiency check</b> with an examiner in the <code>3 months</code> before expiry,", "<b class=\"k\">or</b>, in the <code>12 months</code> before expiry: <code>12 h</code> in the class, including <code>6 h</code> PIC, <code>12</code> take-offs and <code>12</code> landings, and <code>1 h</code> refresher training with an <b class=\"k\">FI or CRI</b> (exempt if you passed another class or type proficiency check, skill test or assessment of competence).", "An examiner or suitably qualified instructor then <b class=\"k\">endorses</b> the licence.", "Lapsed: refresher training as required, then a proficiency check."]], ["Other ratings", ["<code>MEP</code>: <code>70 h</code> PIC first; ATO course; proficiency check in the 3 months before expiry.", "<code>Type ratings</code>: complex single-pilot turbine aeroplanes and multi-pilot aeroplanes; valid <b class=\"k\">12 months</b>.", "<code>Night rating</code>: to use the licence in <b class=\"k\">VMC at night</b>.", "<code>IR(R) / IMC rating</code> (UK only): <code>25 h</code> after PPL, <code>10 h</code> PIC (<code>5 h</code> cross-country), <code>15 h</code> instrument training (<code>10 h</code> sole reference), written exam and test. IFR anywhere <b class=\"k\">except Class A</b>, and not to take off or land with flight visibility below cloud under <code>1,500 m</code>. Valid <code>25 months</code>.", "<code>IR(A)</code>: IFR down to a decision height of <code>200 ft</code> (<code>60 m</code>).", "Also aerobatic, sailplane towing, banner towing and mountain ratings; <b class=\"k\">FI</b> certificates (an FI(R) may not authorise first solos)."]], ["Other licences", ["<code>LAPL(A)</code>: leisure, no pay; age <code>17</code>; aircraft MTOW <code>2,000 kg</code> or less, at most <code>3</code> passengers (4 on board); passengers only after <code>10 h</code> as PIC after issue. Training <code>30 h</code> minimum (book: <code>15 h</code> dual, <code>6 h</code> solo, <code>80 nm</code> cross-country). Recency: <code>12 h</code> PIC in <code>24 months</code> with <code>12</code> take-offs and landings and <code>1 h</code> with an instructor.", "<code>UK (ANO) PPL</code>: Schedule 8; a UK PPL(A) may <b class=\"k\">not</b> fly out of sight of the surface without an IMC rating or IR.", "<code>NPPL(A) SSEA/SLMG</code> (administered by the LAA): UK airspace only, <b class=\"k\">day VFR</b>, max <code>4</code> on board, MTOW <code>2,000 kg</code>, <code>140 kt</code> cruise limit; training <code>22 h</code> dual and <code>10 h</code> solo; ratings valid <code>24 months</code>.", "<code>Microlights</code>: two seats at most, Permit to Fly, weight and stall-speed limits (the book's mass limits are out of date; check the CAA's current definition).", "Also: PPL(H), PPL(As), SPL (sailplanes), BPL (balloons), UK PPL(G) (gyroplanes, not ICAO)."]], ["Personal flying logbook", ["Kept by qualified pilots and anyone training for a licence: name and address, licence details, and for each flight the <b class=\"k\">date, places, times</b>, aircraft <b class=\"k\">type and registration</b>, <b class=\"k\">capacity</b> (dual, PIC), <b class=\"k\">night/instrument</b>, and any tests.", "<b class=\"k\">Damaging, altering or falsifying</b> logbook entries is an offence (it amounts to forgery).", "Produce it to an <b class=\"k\">authorised person</b> within a reasonable time, for up to <code>2 years</code> after the last entry."]]], "cards": [["Minimum age for a PPL(A)? For solo?", "17 for the licence, 16 for solo."], ["Medical needed for a PPL(A)?", "Class 2 (or Class 1)."], ["Class 2 validity under 40?", "60 months (but not beyond age 42 if issued before 40)."], ["Class 2 validity from 40 to 49?", "24 months (not beyond 51 if issued before 50)."], ["Class 2 validity from 50?", "12 months."], ["How early can you renew a medical without losing time?", "Up to 45 days before expiry."], ["Who do you see after a significant illness or injury?", "Your AME (or an AeMC), before flying again."], ["Rule of thumb after a local / general anaesthetic?", "12 hours / 48 hours."], ["PPL(A) minimum flying hours?", "45 h, including 25 h dual and 10 h supervised solo."], ["PPL(A) qualifying cross-country?", "At least 150 nm (270 km) solo with two full-stop landings at other aerodromes."], ["How long do you have to pass the nine exams?", "18 months from the end of the month of the first pass."], ["Passenger recency?", "3 take-offs, approaches and landings in the preceding 90 days (one at night for night passengers)."], ["Cost sharing conditions?", "Private flight, up to 6 people on board including the pilot, and the pilot pays a share."], ["SEP rating validity?", "24 months."], ["SEP revalidation by experience?", "In the 12 months before expiry: 12 h, 6 h PIC, 12 take-offs and 12 landings, 1 h with an FI or CRI."], ["SEP revalidation by test?", "A proficiency check with an examiner in the 3 months before expiry."], ["LAPL(A) limits?", "MTOW 2,000 kg or less and no more than 3 passengers."], ["Revalidation vs renewal?", "Revalidation extends a valid rating; renewal restores an expired one."], ["How long must you be able to produce your logbook?", "Up to 2 years after the last entry."]], "quiz": [["A pilot who is 38 passes a Class 2 medical. It is valid for:", ["60 months, but not beyond age 42", "60 months, whatever their age", "24 months", "60 months, but not beyond age 40"], 0, "Under 40 it's 60 months, but one issued before 40 lapses at 42. Lapsing at exactly 40 is the trap."], ["A Class 2 medical issued to a 52-year-old is valid for:", ["12 months", "24 months", "60 months", "6 months"], 0, "From 50 the period is 12 months."], ["Before carrying passengers, a PPL(A) holder must have made, in the same class or type:", ["3 take-offs, approaches and landings in the preceding 90 days", "3 take-offs and landings in the preceding 60 days", "5 take-offs and landings in the preceding 90 days", "3 take-offs, approaches and landings in the preceding calendar month"], 0, "Three in 90 days, as sole manipulator of the controls. For night passengers one must be at night."], ["Which is a valid way to revalidate an SEP class rating?", ["12 h in the 12 months before expiry, with 6 h PIC, 12 take-offs and landings and 1 h with an instructor", "12 h in the 12 months before expiry, with 6 take-offs and landings and 2 h with an instructor", "A proficiency check with an examiner in the 12 months before expiry", "6 h PIC in the 6 months before expiry"], 0, "Experience route: 12 h, 6 PIC, 12 and 12, 1 h refresher. The proficiency check must fall in the last 3 months, not 12."], ["Cost sharing on a private flight is allowed when:", ["There are no more than 6 people on board and the pilot pays a share", "There are no more than 6 people on board and the passengers pay everything", "There are no more than 4 people on board and the pilot pays a share", "The pilot holds an instructor rating"], 0, "Up to 6 on board, and direct costs are shared by everyone including the pilot."], ["A student pilot may fly solo without a licence if they are at least:", ["16, hold a Class 1 or 2 medical and are authorised and supervised by an instructor", "17 and hold a Class 2 medical", "16 and hold a LAPL medical, with one passenger", "16, with written permission from the CAA"], 0, "16, a Class 1 or 2 medical, no one else on board, and an instructor's authorisation and supervision."], ["After a dental local anaesthetic, a pilot should not fly for at least:", ["12 hours", "24 hours", "48 hours", "8 hours"], 0, "12 hours for a local; 48 hours for a general anaesthetic."], ["A pilot is admitted to hospital overnight. What must they do before flying again?", ["Seek advice from their AME or an AeMC", "Wait 20 days, then resume", "Nothing, if they feel well", "Get a note from their GP"], 0, "Hospital admission is one of the triggers; the AME or AeMC decides fitness."], ["A LAPL(A) holder could act as PIC of an aeroplane with:", ["MTOW 1,950 kg and 4 seats", "MTOW 2,200 kg and 4 seats", "MTOW 1,950 kg and 6 seats", "MTOW 2,500 kg and 2 seats"], 0, "LAPL(A): 2,000 kg or less and no more than 3 passengers, so 4 seats at most."], ["Under Part-FCL, a 'proficiency check' is used to:", ["Revalidate or renew a rating", "Issue a licence for the first time", "Gain a new class rating", "Test a student before first solo"], 0, "A skill test is for issue; a proficiency check revalidates or renews. The book's glossary has these the wrong way round."]]});
Object.assign(SUM,{"Part-FCL and Part-MED": "UK Part-FCL and Part-MED, issued by the CAA, cover Part-21 aircraft; licences are for life.", "Part-FCL terms": "Key definitions: class and type ratings, flight time, revalidation versus renewal, skill test versus proficiency check.", "Student pilots": "Solo from 16 with a Class 1 or 2 medical, nobody else on board, authorised by an instructor.", "Medicals (Part-MED)": "PPL needs Class 2 (or Class 1); LAPL can use a LAPL medical.", "Class 2 validity": "60 months under 40, 24 months from 40, 12 months from 50; renew up to 45 days early.", "Decrease in medical fitness": "Unfit or in doubt: don't fly, see your AME. Local anaesthetic 12 h, general 48 h, blood 24 h.", "The PPL(A)": "Age 17; 45 h with 25 dual and 10 solo; nine exams in 18 months; signed in ink and valid for life.", "Privileges": "Non-commercial PIC or co-pilot; cost sharing with up to 6 on board, pilot pays a share.", "Passenger recency (FCL.060)": "3 take-offs, approaches and landings in 90 days; one at night for night passengers.", "FRTOL": "You need a radio licence to use the aircraft radio.", "Ratings": "Class ratings like SEP (land); differences training for things like retractable gear, VP props and tailwheels.", "Revalidating the SEP class rating (valid 24 months)": "Proficiency check in the last 3 months, or 12 h in the last 12 months with 6 PIC, 12 landings and 1 h with an instructor.", "Other ratings": "Night, IR(R)/IMC (UK only, 25 months), IR, type ratings (12 months) and instructor certificates.", "Other licences": "LAPL: 2,000 kg, 3 passengers, Europe. NPPL: UK day VFR, 4 on board. Plus PPL(H), SPL, BPL.", "Personal flying logbook": "Record every flight; falsifying it is an offence; produce it for 2 years after the last entry."});
NOTES.push({"s": 0, "topic": "Operation of Aircraft", "num": 12, "order": 120, "conf": "weak", "status": "draft", "summary": "Before every flight the PIC checks weather, route, equipment, airworthiness, load, fuel with a margin, and performance, then briefs passengers on exits, belts, and oxygen or life jackets if carried. In flight, everyone obeys the commander, a pilot stays at the controls, and nobody flies impaired (20 mg alcohol per 100 ml of blood; at least 8 hours after drinking). Towing, dropping and parachuting need CofA or CAA approval. Carry the documents Part-NCO lists, or leave items 2 to 8 on the ground for an A-to-A flight. Know the squawks (7700, 7600, 7500, 7000), report an Airprox by radio and confirm within 7 days, and know the equipment rules for over-water flight and oxygen.", "sections": [["Operational rules (UK ANO and Part-NCO)", ["ICAO <b class=\"k\">Annex 6</b> (international GA) differs in places from the <b class=\"k\">ANO</b>, so the ANO rules come first, then the Annex 6 extracts for international flights. Air operations: <b class=\"k\">Regulation (EU) 965/2012</b> (Part-NCO for private flights in other-than-complex aircraft)."]], ["Pre-flight actions of the PIC (NCO.GEN.105, ANO Articles 69 and 75)", ["Before each flight, be satisfied that:", "– the flight can be made <b class=\"k\">safely</b>, with the latest route, aerodrome and <b class=\"k\">weather</b> information, and <b class=\"k\">options</b> if it can't be completed as planned", "– required <b class=\"k\">equipment</b> (including radio) is carried and working, with suitable <b class=\"k\">maps, charts</b> and navigation equipment", "– the aircraft is <b class=\"k\">fit to fly</b>, with a valid <b class=\"k\">ARC</b> or Certificate of Maintenance Review where needed", "– the <b class=\"k\">load</b> is safe for weight, distribution and security", "– there is enough <b class=\"k\">fuel, oil, coolant</b> (and ballast), <b class=\"k\">with a margin</b>", "– <b class=\"k\">performance</b> allows a safe take-off, climb, cruise and landing at the destination", "– all <b class=\"k\">pre-flight checks</b> are done", "Rough take-off distance factors (use the aircraft's charts for real numbers):", "– <code>10%</code> more weight → about <code>20%</code> more take-off distance", "– <b class=\"k\">tailwind</b> of <code>10%</code> of lift-off speed (about <code>5 kt</code>) → about <code>20%</code> more", "– <code>10°C</code> warmer or <code>1,000 ft</code> higher → about <code>10%</code> more"]], ["Passenger briefing (ANO Article 73)", ["Before take-off, brief passengers on <b class=\"k\">emergency exits</b>, <b class=\"k\">seat belts or harnesses</b>, and <b class=\"k\">oxygen</b> and <b class=\"k\">life jackets</b> when carried."]], ["In flight", ["<code>Commander's authority</code> (Article 244): everyone on board must obey the commander's <b class=\"k\">lawful commands</b> for safety.", "<code>Crew composition</code> (Article 66): must meet the rules of the <b class=\"k\">State of Registry</b>.", "<code>Pilots at the controls</code> (Article 70): <b class=\"k\">one pilot at the controls</b> at all times; both during take-off and landing if two are required; <b class=\"k\">belt or harness worn</b> at the controls (harness for take-off and landing when one is fitted).", "<code>Carriage of persons</code>: nobody in a part of the aircraft <b class=\"k\">not designed for people</b>, or on anything towed, except brief access for safety or to a designed cargo area.", "<code>Smoking</code> (Article 243): obey no-smoking signs; the commander can ban it at any time.", "<code>Alcohol</code> (Article 242): not drunk on board; crew not impaired by <b class=\"k\">drink or drugs</b>. Legal limit <code>20 mg</code> per <code>100 ml</code> of blood (a quarter of the England and Wales driving limit). Rule of thumb: at least <code>8 hours</code> \"bottle to throttle\", more after heavy drinking.", "<b class=\"k\">Disruptive behaviour</b> (Article 245) and <b class=\"k\">endangering</b> aircraft, people or property recklessly or negligently (Articles 240-241) are offences, e.g. flying dangerously low or with too little fuel.", "<code>Radio</code> (Article 79): the operator needs an <b class=\"k\">R/T licence</b> and the radio its own licence.", "<code>Flight recorders</code> (Article 231): aeroplanes over <code>5,700 kg</code> and helicopters over <code>2,700 kg</code> in some cases."]], ["Towing, dropping and parachuting", ["<b class=\"k\">Towing gliders</b> (Article 87) and <b class=\"k\">towing or picking up</b> people or articles (Article 88): only if the <b class=\"k\">CofA expressly allows</b> it. Part-SPO covers the EASA rules.", "<code>Dropping articles or animals</code> (Article 89): never so as to <b class=\"k\">endanger</b> anyone; otherwise only with <b class=\"k\">CAA written approval</b>, except e.g. life-saving equipment or <b class=\"k\">jettisoning</b> in an emergency.", "<code>Dropping persons</code> (Article 90): except escaping in an emergency, only with <b class=\"k\">CAA written permission</b>, a CofA that allows it, and the Parachuting Manual.", "<code>Weapons</code> (Article 98): operator's consent, <b class=\"k\">unloaded</b>, not accessible to passengers.", "<code>Munitions of war</code>: CAA <b class=\"k\">written permission</b>.", "<code>Dangerous goods</code> (Article 97, NCO.GEN.140): harmless items on the ground can be dangerous at altitude in a small cabin (aerosols, lighters, gas cylinders, batteries, fire lighters). <b class=\"k\">If in doubt, leave it out.</b> <b class=\"k\">Mobile phones</b> off before engine start; portable electronic devices: NCO.GEN.125."]], ["Balloons, kites, airships and winch launches (Articles 92-93)", ["A <b class=\"k\">captive balloon or kite</b> must not fly higher than <code>60 m</code> agl, within <code>60 m</code> of a vessel, vehicle or structure, or <b class=\"k\">within an ATZ</b>.", "A balloon over <code>2 m</code> in any dimension must not fly in notified controlled airspace.", "Gliders and parascending parachutes: no winch or ground-tow launch above <code>60 m</code> agl. The CAA can vary any of these in writing."]], ["Documents to be carried (NCO.GEN.135, ANO Article 229)", ["Aircraft <b class=\"k\">Flight Manual</b> (or equivalent)", "Original <b class=\"k\">certificate of registration</b>", "Original <b class=\"k\">CofA</b>", "<b class=\"k\">Noise certificate</b>, if applicable", "List of <b class=\"k\">specific approvals</b>, if applicable", "Aircraft <b class=\"k\">radio licence</b>", "<b class=\"k\">Insurance</b> certificate", "<b class=\"k\">Journey log</b>", "Details of the <b class=\"k\">filed flight plan</b>, if applicable", "Current, suitable <b class=\"k\">charts</b> for the route and likely diversions", "<b class=\"k\">Interception</b> procedures and visual signals", "<b class=\"k\">MEL</b>, if applicable", "Anything else pertinent to the flight", "Taking off and landing at the <b class=\"k\">same aerodrome</b> (staying in UK airspace): items <b class=\"k\">2 to 8</b> may stay on the ground.", "<b class=\"k\">Non-Part-21</b> aircraft within the UK: only <b class=\"k\">navigation charts</b> are required.", "Using a <b class=\"k\">Part-FCL licence</b>: carry the <b class=\"k\">licence</b> and <b class=\"k\">photo ID</b> (passport or driving licence), and your medical."]], ["Production of documents (Article 235)", ["Within a <b class=\"k\">reasonable time</b> of a request from an <b class=\"k\">authorised person</b> (police, CAA, Secretary of State), produce the <b class=\"k\">registration and airworthiness certificates</b>, <b class=\"k\">crew licences</b>, <b class=\"k\">personal logbooks</b> (up to <code>2 years</code> after the last entry), and other documents that should be carried."]], ["Offences (Article 256)", ["Using a <b class=\"k\">forged, altered, revoked or suspended</b> document, or one you're not entitled to; <b class=\"k\">lending</b> one with intent to deceive; forging, defacing or <b class=\"k\">falsifying a logbook</b> or record, or destroying it while it must be kept. Entries in <b class=\"k\">ink or indelible pencil</b>."]], ["SSR transponders", ["<code>Mode A</code>: 4,096 four-digit codes.", "<code>Mode C</code>: adds <b class=\"k\">pressure altitude</b> (from an encoding altimeter).", "<code>Mode S</code>: individual aircraft address and identity, better detection.", "The book's carriage rules are the old Mode A/C ones. Today the UK AIP (<b class=\"k\">ENR 1.6</b>) requires <b class=\"k\">Mode S</b> at and above <b class=\"k\">FL100</b>, in <b class=\"k\">Transponder Mandatory Zones (TMZs)</b> and in much controlled airspace; check ENR 1.6.", "Where not mandatory, squawk <code>7000</code> with <b class=\"k\">ALT</b> (Mode C) unless ATC gives you a code.", "Without a transponder, expect not to be let into a <b class=\"k\">TMZ</b>.", "<b><code>7700</code></b>: <b class=\"k\">Emergency</b> (keep an assigned code if already in contact with a unit)", "<b><code>7600</code></b>: <b class=\"k\">Radio failure</b>", "<b><code>7500</code></b>: <b class=\"k\">Unlawful interference</b>", "<b><code>7000</code></b>: <b class=\"k\">VFR conspicuity</b>", "<b><code>2000</code></b>: IFR conspicuity / no code assigned", "<b><code>7004</code></b>: <b class=\"k\">Aerobatics</b> and display", "<b><code>0033</code></b>: <b class=\"k\">Parachute dropping</b> (from 5 minutes before until parachutists are down)", "<b><code>0030</code></b>: <b class=\"k\">Lost</b> (UK)", "Select <b class=\"k\">Mode C</b> with all of them. Don't pass through <b class=\"k\">7500/7600/7700</b> when changing codes."]], ["Airprox", ["If you think your aircraft was <b class=\"k\">endangered by another aircraft's proximity</b>, report an <b class=\"k\">Airprox</b>: first <b class=\"k\">by radio</b> to the ATSU you're talking to (or by phone after landing, preferably to an ACC), then confirm within <code>7 days</code> online on <b class=\"k\">CA Form 1094</b>. AIP ENR 1.14."]], ["International flights (ICAO Annex 6)", ["Obey the laws of each <b class=\"k\">State</b> you fly in. The <b class=\"k\">PIC</b> is responsible for the operation and <b class=\"k\">safety</b> of the aeroplane and everyone on board.", "If an <b class=\"k\">emergency</b> forces you to break local rules, tell the authority <b class=\"k\">as soon as possible</b> (some want a report within <b class=\"k\">10 days</b>).", "<b class=\"k\">Accident</b> with serious injury, death or substantial damage: the PIC notifies the authority as quickly as possible.", "Carry <b class=\"k\">search and rescue</b> information for the areas overflown (recommended).", "Before flight, check <b class=\"k\">facilities</b> (aerodromes, communications, navaids) are adequate; don't fly below <b class=\"k\">aerodrome operating minima</b>.", "Brief crew and passengers on <b class=\"k\">seat belts, exits, life jackets, oxygen</b> and other emergency equipment, including life rafts.", "Aeroplane <b class=\"k\">airworthy, registered</b>, certificates on board, suitable <b class=\"k\">instruments</b>, maintenance done, <b class=\"k\">mass and balance</b> in limits, <b class=\"k\">cargo secured</b>, Flight Manual limits respected.", "<code>VFR</code>: don't start unless current reports and forecasts show <b class=\"k\">VMC along the route</b>; don't continue unless the destination or <b class=\"k\">an alternate</b> is at or above minima. No flight into <b class=\"k\">known icing</b> without suitable equipment.", "Enough <b class=\"k\">fuel and oil</b> for the weather and expected delays.", "<b class=\"k\">Report</b> weather or hazards (volcanic ash, dust storms) likely to affect other flights.", "<code>Taxiing</code>: only if authorised, competent, radio-qualified where needed, and briefed on the aerodrome's layout, signs and procedures.", "<code>Refuelling with passengers on board</code>: only with the PIC or a qualified person ready to organise an <b class=\"k\">evacuation</b>."]], ["Part-NCO aeroplanes", ["<b class=\"k\">First-aid kit</b>, kept up to date", "At least one <b class=\"k\">hand fire extinguisher</b>", "<b class=\"k\">Spare fuses</b> (if fuses, not circuit breakers)", "A <b class=\"k\">seat</b> and <b class=\"k\">seat belt</b> for each person (above an age set by the State)", "<b class=\"k\">ELT</b>: any type if the first CofA was on or before <b class=\"k\">1 July 2008</b>; an <b class=\"k\">automatic ELT</b> if later; or, for aircraft with <b class=\"k\">six seats or fewer</b>, a <b class=\"k\">survival ELT or PLB</b> carried by someone on board. They transmit on <code>121.5 MHz</code> and <code>406 MHz</code>."]], ["Instruments", ["<code>VFR by day</code>: <b class=\"k\">magnetic heading</b>, <b class=\"k\">time</b> (hours, minutes, seconds), <b class=\"k\">pressure altitude</b>, <b class=\"k\">indicated airspeed</b>.", "<b class=\"k\">VFR at night</b> (or where instruments are needed to hold a flight path), also: <b class=\"k\">turn and slip</b>, <b class=\"k\">attitude</b>, <b class=\"k\">vertical speed</b>, <b class=\"k\">stabilised heading</b>, and a warning when <b class=\"k\">gyro power</b> is inadequate. Where instruments are needed: <b class=\"k\">pitot heat</b>."]], ["Over water (Part-NCO)", ["<b class=\"k\">Single-engine</b> aeroplanes: a <b class=\"k\">life jacket</b> for each person (or a flotation device for those under <b class=\"k\">24 months</b>) when <b class=\"k\">beyond gliding distance from land</b>, or taking off or landing where the path over water makes a <b class=\"k\">ditching</b> likely. In a single, wear it (uninflated).", "More than <code>30 minutes</code> at cruise or <code>50 nm</code> from land suitable for an emergency landing, <b class=\"k\">whichever is less</b>: the PIC assesses the <b class=\"k\">survival risk</b> and decides on <b class=\"k\">life rafts</b>, <b class=\"k\">distress signals</b> and life-saving equipment.", "ICAO Annex 6 (book): life rafts beyond <code>100 nm</code> (single-engine) or <code>200 nm</code> (multi-engine).", "Areas where search and rescue would be <b class=\"k\">especially difficult</b>: signalling and survival equipment."]], ["Oxygen (unpressurised)", ["<code>Crew</code>: continuously above <code>10,000 ft</code> for more than <code>30 minutes</code>, and at all times above <code>13,000 ft</code>.", "<code>Passengers</code>: above <code>13,000 ft</code>."]]], "cards": [["What must a PIC brief passengers on before take-off?", "Emergency exits, seat belts or harnesses, and oxygen and life jackets if carried."], ["Rough effect of 10% extra weight on take-off distance?", "About 20% more."], ["Rough effect of a 10°C rise or 1,000 ft higher aerodrome?", "About 10% more take-off distance."], ["Legal blood alcohol limit for crew?", "20 mg per 100 ml of blood."], ["Rule of thumb after drinking?", "At least 8 hours, longer after heavy drinking."], ["Who has final authority over the safe conduct of a flight?", "The pilot-in-command (commander)."], ["Can an aircraft tow a glider?", "Only if its CofA expressly allows it."], ["Captive balloon or kite height limit?", "60 m agl, and not within 60 m of a structure or inside an ATZ."], ["Documents that may stay on the ground for an A-to-A flight?", "Items 2 to 8: registration, CofA, noise certificate, approvals, radio licence, insurance, journey log."], ["Squawk for radio failure?", "7600."], ["Squawk for an emergency?", "7700 (keep an assigned code if already with a unit)."], ["Squawk for unlawful interference?", "7500."], ["UK lost code?", "0030."], ["Parachute dropping squawk?", "0033, from 5 minutes before the drop until the parachutists are down."], ["How do you confirm an Airprox?", "Online on CA Form 1094 within 7 days."], ["ELT frequencies?", "121.5 MHz and 406 MHz."], ["Day VFR instruments?", "Magnetic heading, time (h, min, s), pressure altitude, indicated airspeed."], ["When must single-engine aeroplanes carry life jackets?", "Beyond gliding distance from land, or where take-off or approach is over water and a ditching is likely."], ["Crew oxygen rule?", "Above 10,000 ft for more than 30 minutes, and at all times above 13,000 ft."]], "quiz": [["Before take-off the pilot-in-command must brief passengers on:", ["Emergency exits, seat belts or harnesses, and oxygen and life jackets when carried", "Emergency exits only", "Seat belts and the aircraft's performance", "The route and the weather"], 0, "ANO Article 73: exits, belts or harnesses, and oxygen and life jackets when they are carried."], ["The legal blood alcohol limit for a pilot is:", ["20 mg per 100 ml of blood", "80 mg per 100 ml of blood", "50 mg per 100 ml of blood", "9 mg per 100 ml of blood"], 0, "20 mg, a quarter of the England and Wales drink-driving limit of 80 mg."], ["The transponder code for radio failure is:", ["7600", "7700", "7500", "7000"], 0, "7600 is radio failure; 7700 emergency; 7500 unlawful interference; 7000 conspicuity."], ["Below FL100 a VFR pilot should squawk 7000 with ALT unless:", ["ATC has assigned a code, or a special-purpose code applies", "Flying in Class G", "The visibility is over 10 km", "The aircraft has Mode S"], 0, "Use 7000 unless you have been given a code or need a special one (emergency, lost, parachuting, aerobatics)."], ["An Airprox reported by radio must be confirmed:", ["Within 7 days on CA Form 1094", "Within 24 hours by phone", "Within 28 days in writing", "Only if ATC asks"], 0, "Report by radio at once, then confirm within 7 days online (CA1094)."], ["The final authority for the safe conduct of a flight rests with:", ["The pilot-in-command", "The aircraft operator", "The person at the controls", "ATC in controlled airspace"], 0, "Annex 6 and the ANO: the PIC. The person at the controls may not be the PIC, and ATC never takes over that authority."], ["A pilot plans a local flight, taking off and landing at the same aerodrome within the UK, in a Part-21 aeroplane. Which document may stay on the ground?", ["The certificate of insurance", "The aircraft Flight Manual", "Current charts", "The interception procedures"], 0, "Items 2 to 8 (registration, CofA, noise certificate, approvals, radio licence, insurance, journey log) may stay at the aerodrome. The Flight Manual, charts and interception procedures still fly."], ["A captive balloon or kite must not be flown:", ["Higher than 60 m agl, within 60 m of a structure, or inside an ATZ", "Higher than 150 m agl or within 150 m of a structure", "Higher than 60 m agl only", "Within 600 m of a congested area"], 0, "All three limits apply: 60 m agl, 60 m from vessels, vehicles or structures, and not in an ATZ."], ["Under Part-NCO, a single-engine aeroplane flying further from land than 30 minutes at cruise or 50 nm (whichever is less):", ["The PIC must assess the survival risk and decide on life rafts and distress signals", "Must carry a life raft for everyone on board", "Needs no extra equipment if life jackets are worn", "Must file a flight plan with D&D"], 0, "Part-NCO leaves the raft decision to the PIC's risk assessment beyond 30 minutes or 50 nm. The book's 100 nm raft rule is ICAO Annex 6."], ["In an unpressurised aeroplane the crew must use oxygen:", ["Above 10,000 ft for more than 30 minutes, and at all times above 13,000 ft", "At all times above 10,000 ft", "Above 13,000 ft for more than 30 minutes", "Above 8,000 ft at night"], 0, "The 30-minute allowance applies between 10,000 and 13,000 ft; above 13,000 ft oxygen is needed all the time."]]});
Object.assign(SUM,{"Operational rules (UK ANO and Part-NCO)": "ANO rules first, then ICAO Annex 6 for international flights; Part-NCO covers private flights.", "Pre-flight actions of the PIC (NCO.GEN.105, ANO Articles 69 and 75)": "Weather, equipment, airworthiness, load, fuel with a margin, performance and checks, before every flight.", "Passenger briefing (ANO Article 73)": "Exits, belts or harnesses, and oxygen and life jackets when carried.", "In flight": "Obey the commander, a pilot at the controls, belts on, no drink or drugs.", "Towing, dropping and parachuting": "Only if the CofA or the CAA allows it; never endanger people or property.", "Balloons, kites, airships and winch launches (Articles 92-93)": "Captive balloons and kites: 60 m agl, 60 m from structures, not in an ATZ.", "Documents to be carried (NCO.GEN.135, ANO Article 229)": "Thirteen items under Part-NCO; for an A-to-A flight items 2 to 8 can stay on the ground.", "Production of documents (Article 235)": "Produce certificates, licences and logbooks to an authorised person within a reasonable time.", "Offences (Article 256)": "Forging, lending or falsifying documents and logbooks is an offence.", "SSR transponders": "7700 emergency, 7600 radio failure, 7500 unlawful interference, 7000 conspicuity; select ALT.", "Airprox": "Report by radio straight away and confirm within 7 days on CA1094.", "International flights (ICAO Annex 6)": "Obey local law, check facilities and minima, VMC along the route, enough fuel, report hazards.", "Part-NCO aeroplanes": "First-aid kit, fire extinguisher, seats and belts, and an ELT or PLB.", "Instruments": "Day VFR: compass heading, time, pressure altitude, airspeed. Night adds attitude, turn and slip, VSI, heading.", "Over water (Part-NCO)": "Life jackets beyond gliding distance; beyond 30 minutes or 50 nm the PIC decides on rafts.", "Oxygen (unpressurised)": "Crew above 10,000 ft for over 30 minutes and always above 13,000 ft; passengers above 13,000 ft."});
NOTES.push({"s": 0, "topic": "Distress, Urgency, Safety and Warning Signals", "num": 13, "order": 130, "conf": "weak", "status": "draft", "summary": "There are two states of emergency. Distress (MAYDAY) is grave and imminent danger needing immediate help; urgency (PAN PAN) is a safety concern without immediate danger. Call first on the frequency in use, otherwise 121.5 MHz, and squawk 7700. Visual distress signals are SOS, red flares or a red parachute flare; flashing landing or navigation lights and white flares mean 'I must land but don't need help'; XXX is an urgent safety message. Student pilots say STUDENT. If you stray into a danger area, leave it as fast as possible without descending. Low on fuel and in danger: declare a MAYDAY.", "sections": [["The two states of emergency", ["<code>Distress</code>: threatened by <b class=\"k\">grave and/or imminent danger</b>, needing <b class=\"k\">immediate assistance</b>. Prefix <b class=\"k\">\"MAYDAY MAYDAY MAYDAY\"</b>.", "<code>Urgency</code>: a condition concerning the safety of an aircraft, vehicle or person on board or in sight, <b class=\"k\">not</b> needing immediate assistance. Prefix <b class=\"k\">\"PAN PAN, PAN PAN, PAN PAN\"</b>.", "Transmit first on the <b class=\"k\">frequency in use</b>; if you're not in contact with anyone, or get no reply, use <code>121.5 MHz</code>."]], ["Distress signals", ["<code>Radio</code>: \"MAYDAY MAYDAY MAYDAY\", then the message. Example order:", "– station addressed (\"London Centre\", or the unit you are talking to)", "– callsign (and type)", "– nature of the emergency (\"engine has failed\")", "– intentions (\"making a forced landing\")", "– position, level and heading (\"five miles north of the field, three thousand feet descending, heading two eight zero\")", "– <b class=\"k\">pilot qualification</b> (\"student pilot\"), not an ICAO requirement but it helps the controller plan", "<b class=\"k\">Student pilots</b> add <b class=\"k\">\"STUDENT\"</b> to their callsign when solo and in an emergency message on any frequency, so instructions are kept simple.", "<code>Visual</code>: <b class=\"k\">SOS</b> in Morse (· · · − − − · · ·) by light; a <b class=\"k\">succession of red pyrotechnics</b> at short intervals; a <b class=\"k\">red parachute flare</b>.", "<code>Sound</code>: SOS in Morse; a <b class=\"k\">continuous sound</b> from any apparatus."]], ["Urgency signals", ["An aircraft in difficulties that <b class=\"k\">compel it to land</b>, but not needing immediate help:", "– <b class=\"k\">repeated switching on and off of the landing lights</b>", "– <b class=\"k\">repeated switching on and off of the navigation lights</b> (distinguishable from normal flashing)", "– a <b class=\"k\">succession of white pyrotechnic lights</b>", "An aircraft with an <b class=\"k\">urgent message</b> about the safety of a ship, aircraft, vehicle, property or person (on board or <b class=\"k\">in sight</b>):", "– <code>Radio</code>: \"PAN PAN\" ×3, e.g. reporting another aircraft that has force-landed and its occupants", "– <code>Visual or sound</code>: <b class=\"k\">XXX</b> in Morse (− · · − ×3)", "<b>Exam trap</b> Flashing landing lights or white flares mean <b class=\"k\">\"I must land, but don't need help now\"</b>; red flares mean distress."]], ["Using the transponder", ["<code>7700</code> emergency, <code>7600</code> radio failure, <code>7500</code> unlawful interference, with <b class=\"k\">Mode C</b> selected.", "If you're already squawking a code given by a unit you're talking to, normally <b class=\"k\">keep it</b>."]], ["Danger areas", ["<code>DACS</code> (Danger Area <b class=\"k\">Crossing</b> Service): a unit can tell you whether a danger area is active and may give a <b class=\"k\">crossing clearance</b>. Marked on the 1:500,000 chart with a prefix symbol.", "<code>DAAIS</code> (Danger Area <b class=\"k\">Activity Information</b> Service): tells you whether an area is active, but is <b class=\"k\">not a clearance</b> to cross.", "Details: <b class=\"k\">AIP ENR 5</b>, the chart's list of danger areas and Pooley's.", "If you <b class=\"k\">inadvertently enter</b> a danger or prohibited area, <b class=\"k\">leave it as quickly as possible without descending</b>, even without a radio instruction."]], ["Low fuel", ["If the fuel state means you need <b class=\"k\">priority</b>, declare a <b class=\"k\">MAYDAY</b> (ICAO phraseology: \"MAYDAY MAYDAY MAYDAY FUEL\"), but only if you believe the aircraft is <b class=\"k\">in danger</b>, and make it match the real fuel state.", "The book recommends arriving over the destination with enough to <b class=\"k\">approach</b>, <b class=\"k\">go around</b>, fly to an <b class=\"k\">alternate</b>, land there and hold for <code>45 minutes</code>. For Part-NCO VFR flights the legal final reserve is <code>30 minutes</code> by day and <code>45 minutes</code> at night; plan for more."]]], "cards": [["The two states of emergency?", "Distress and urgency."], ["Distress means?", "Grave and/or imminent danger, needing immediate assistance."], ["Urgency means?", "A safety concern for an aircraft, vehicle or person, not needing immediate assistance."], ["First frequency for a MAYDAY?", "The frequency in use; 121.5 MHz if not in contact or no reply."], ["Visual distress signals?", "SOS by light, red pyrotechnics at short intervals, a red parachute flare."], ["Flashing landing lights or white flares mean?", "Difficulties compel me to land, but I don't need immediate help."], ["XXX in Morse means?", "An urgent message about the safety of a ship, aircraft, vehicle or person."], ["Why say 'STUDENT'?", "So the controller keeps instructions simple."], ["DACS vs DAAIS?", "DACS: crossing service, may give a clearance. DAAIS: activity information only, not a clearance."], ["Strayed into a danger area?", "Leave as quickly as possible without descending."], ["Low fuel and in danger?", "Declare a MAYDAY (MAYDAY FUEL)."]], "quiz": [["The two states of emergency are:", ["Distress and urgency", "Mayday and pan pan", "Difficulty and urgency", "Distress and danger"], 0, "The states are distress and urgency; MAYDAY and PAN PAN are their radio prefixes, not the states."], ["A MAYDAY should first be transmitted on:", ["The frequency in use", "121.5 MHz", "The nearest MATZ frequency", "The London Information frequency"], 0, "The unit you're talking to can help fastest. Use 121.5 MHz if you're not with anyone or get no reply."], ["Distress is defined as:", ["Threatened by grave and/or imminent danger and needing immediate assistance", "A condition concerning safety that does not need immediate assistance", "Any engine failure", "Being unsure of your position"], 0, "Distress needs immediate assistance; the second option is urgency."], ["You see an aircraft repeatedly switching its landing lights on and off. It means:", ["It must land but does not need immediate assistance", "It is in distress and needs immediate help", "It is warning you of a collision", "It has an urgent message about another aircraft"], 0, "Flashing landing or navigation lights (or white flares) are the 'must land, no immediate help' signal. Red flares are distress; XXX is the urgent-message signal."], ["XXX sent by light in Morse means:", ["An urgent message about the safety of a ship, aircraft, vehicle or person", "Distress: immediate assistance needed", "Radio failure", "Land at this aerodrome"], 0, "XXX is the urgency signal for an urgent safety message. SOS is distress."], ["Which of these is a distress signal?", ["A red parachute flare", "A succession of white pyrotechnics", "Repeated switching of navigation lights", "XXX in Morse"], 0, "Red flares and SOS are distress. White flares and flashing lights are urgency (must land)."], ["DACS stands for:", ["Danger Area Crossing Service", "Danger Area Clearance Service", "Danger Area Activity Service", "Danger Area Coordination Service"], 0, "Crossing Service; it may give you a clearance. DAAIS is the Activity Information Service."], ["You realise you have entered an active danger area. You should:", ["Leave as quickly as possible without descending", "Descend below its base at once", "Orbit and call the controlling unit", "Climb to the upper limit and continue"], 0, "Leave by the quickest route without descending, even with no radio instruction."], ["Your fuel state means you will land with less than your final reserve. You should:", ["Declare a MAYDAY to get priority", "Call PAN PAN and ask for a direct route", "Say nothing until overhead", "Squawk 7600"], 0, "Fuel at or below reserve puts the aircraft in danger: MAYDAY (ICAO: 'MAYDAY FUEL'). 7600 is radio failure."]]});
Object.assign(SUM,{"The two states of emergency": "Distress (MAYDAY): grave and imminent danger. Urgency (PAN PAN): a concern, no immediate danger.", "Distress signals": "MAYDAY ×3 then the message; SOS, red flares or a red parachute flare; a continuous sound.", "Urgency signals": "Flashing landing or nav lights and white flares: must land, no help needed. XXX or PAN PAN: urgent safety message.", "Using the transponder": "7700 emergency, 7600 radio failure, 7500 unlawful interference, with Mode C.", "Danger areas": "DACS can clear you across; DAAIS only says if an area is active. Strayed in? Leave without descending.", "Low fuel": "Declare a MAYDAY if the fuel state puts you in danger; Part-NCO reserves are 30 min day, 45 min night."});
NOTES.push({"s": 0, "topic": "Search and Rescue", "num": 14, "order": 140, "conf": "weak", "status": "draft", "summary": "An RCC runs search and rescue; 121.5 MHz is watched continuously, and the ATSU last in contact normally starts alerting action. For a SAR watch, file a flight plan, which is advisable more than 10 nm from the coast, over remote areas or without a suitable radio. Diverting? Tell the original destination before ETA plus 30 minutes or SAR action begins. The phases are uncertainty, alert and distress. If you see a craft in distress, keep it in sight, fix your position and report what you see. Ground signals: V assistance, X medical, arrow direction, Y yes, N no; the aircraft rocks its wings (day) or flashes its landing lights twice (night) to show it understood.", "sections": [["Search and rescue in the UK", ["SAR is controlled by a <b class=\"k\">Rescue Coordination Centre (RCC)</b>, acting on reports from any source; the response may be joint civil and military. Details: <b class=\"k\">AIP GEN 3.6</b>.", "A <b class=\"k\">continuous listening watch</b> is kept on <code>121.5 MHz</code>. If you can't make a Mayday, Pan or \"lost\" call on the frequency in use, call on 121.5."]], ["Alerting service", ["Available to <b class=\"k\">all aircraft known to ATS</b> in the UK FIRs. Action is normally started by the <b class=\"k\">ATSU last in contact</b> with the aircraft, or the one that receives the information."]], ["Position fixing on 121.5 MHz", ["The book describes <b class=\"k\">autotriangulation</b> (direction-finding fixes) on 121.5 MHz over much of England south and east of Manchester above <code>3,000 ft</code> (down to <code>2,000 ft</code> near London), triggered just by calling. The D&amp;D cell can also use radar; check AIP GEN 3.6 for what's available now."]], ["Transponder in an emergency", ["<code>7700</code> emergency (keep an assigned code if already with a unit), <code>7600</code> radio failure, <code>7500</code> unlawful interference, with <b class=\"k\">Mode C</b>."]], ["SAR watch", ["For a constant SAR watch, <b class=\"k\">file a flight plan</b>. Advisable when:", "– flying more than <code>10 nm</code> from the coast", "– over <b class=\"k\">remote or hazardous areas</b> (northern Scotland, much of the west coast down to Cornwall)", "– in an aircraft <b class=\"k\">without a suitable radio</b>", "If you are expected at an aerodrome, tell its ATC unit (or the authority there) <b class=\"k\">as soon as possible</b> of:", "– any <b class=\"k\">change of destination</b>", "– any expected delay of <code>30 minutes</code> or more", "Diverting en route: tell the <b class=\"k\">original destination</b> (or ask ATC to) before your ETA plus <code>30 minutes</code>, or <b class=\"k\">SAR action will begin</b>."]], ["ICAO Annex 12", ["States provide SAR <b class=\"k\">24 hours a day</b> in their territory, <b class=\"k\">whatever the nationality</b> of the aircraft or occupants.", "Each State defines <b class=\"k\">SAR regions</b> (not overlapping) with a <b class=\"k\">rescue coordination centre</b> in each, coordinates with <b class=\"k\">neighbouring States</b>, and arranges for aircraft, ships and local services outside the SAR organisation to help.", "Anyone who believes an aircraft is in an emergency passes <b class=\"k\">all available information</b> to the RCC <b class=\"k\">immediately</b>."]], ["Emergency phases", ["<b class=\"k\">Uncertainty phase</b>: doubt about the safety of the aircraft. The RCC works with ATSUs to <b class=\"k\">evaluate reports</b> quickly.", "<b class=\"k\">Alert phase</b>: <b class=\"k\">concern</b> for its safety. The RCC <b class=\"k\">alerts SAR units</b> and starts action.", "<b class=\"k\">Distress phase</b>: <b class=\"k\">reasonably certain</b> the aircraft needs <b class=\"k\">immediate assistance</b> or faces grave and imminent danger. The RCC, in order:", "– starts action by <b class=\"k\">SAR units</b>", "– fixes the aircraft's <b class=\"k\">position</b>, its uncertainty and the <b class=\"k\">search area</b>", "– notifies the <b class=\"k\">operator</b>, and <b class=\"k\">adjacent RCCs</b> if needed", "– tells the ATSU about information from other sources", "– asks <b class=\"k\">aircraft, ships and coastal stations</b> to listen for the aircraft or its <b class=\"k\">ELT</b>, help it and report", "– makes and updates a <b class=\"k\">SAR plan</b>", "– notifies the <b class=\"k\">State of Registry</b> and the <b class=\"k\">accident investigation</b> authorities"]], ["If you see an aircraft or vessel in distress (5.8)", ["Unless unable, or it's unnecessary:", "– <b class=\"k\">keep it in sight</b> as long as needed", "– <b class=\"k\">fix your own position</b> precisely", "– <b class=\"k\">report</b> to the RCC or ATSU: type, identification and <b class=\"k\">condition</b>; its <b class=\"k\">position</b> (coordinates, or distance and <b class=\"k\">true</b> bearing from a landmark or navaid); <b class=\"k\">time (UTC)</b>; <b class=\"k\">number of people</b> seen; whether they have <b class=\"k\">abandoned</b> it; number <b class=\"k\">afloat</b>; survivors' apparent condition", "– <b class=\"k\">act as instructed</b>", "The <b class=\"k\">first aircraft on scene</b>, if not a SAR aircraft, takes <b class=\"k\">charge of on-scene activity</b> until the first SAR aircraft arrives (or hands over to a capable aircraft if it can't talk to the RCC).", "Directing a <b class=\"k\">surface craft</b> to the scene: give precise instructions by any means available."]], ["If you intercept a distress call (5.9)", ["<b class=\"k\">Record</b> the aircraft's position if given; <b class=\"k\">take a bearing</b> if you can; <b class=\"k\">inform</b> the RCC or ATSU with all the information; at your discretion, <b class=\"k\">head for the position</b> while awaiting instructions."]], ["Signals from survivors", ["Radio if it works, or: <b class=\"k\">flares</b>, a <b class=\"k\">heliograph</b> (mirror) flash, a flashing <b class=\"k\">light</b>, a <b class=\"k\">flag</b> (with a ball above or below it: the international distress signal), <b class=\"k\">whistles</b>, <b class=\"k\">sea dye markers</b>.", "<b class=\"k\">Ground-to-air signals</b>, at least <code>2-3 m</code> long, contrasting with the ground:", "<b>V</b>: <b class=\"k\">Require assistance</b>", "<b>X</b>: <b class=\"k\">Require medical assistance</b>", "<b>↑ (arrow)</b>: <b class=\"k\">Proceeding in this direction</b>", "<b>Y</b>: <b class=\"k\">Yes</b> (affirmative)", "<b>N</b>: <b class=\"k\">No</b> (negative)", "<b class=\"k\">Aircraft reply</b> that the signal is <b class=\"k\">understood</b>: by <b class=\"k\">day</b>, <b class=\"k\">rock the wings</b>; at <b class=\"k\">night</b>, <b class=\"k\">flash the landing lights on and off twice</b> (or the navigation lights). No reply = <b class=\"k\">not understood</b>.", "<b>Memory aid</b> V for \"Very much need help\", X marks a doctor's cross."]]], "cards": [["Who controls SAR in the UK?", "A Rescue Coordination Centre (RCC)."], ["Emergency frequency watched continuously?", "121.5 MHz."], ["Who normally starts alerting action?", "The ATSU last in contact with the aircraft."], ["How do you get a SAR watch?", "File a flight plan."], ["When is a flight plan advisable for SAR?", "More than 10 nm from the coast, over remote or hazardous areas, or without a suitable radio."], ["Diverting en route: deadline to tell the original destination?", "Before ETA plus 30 minutes, or SAR action starts."], ["The three emergency phases?", "Uncertainty, alert, distress."], ["Distress phase means?", "Reasonably certain the aircraft needs immediate help or faces grave and imminent danger."], ["First non-SAR aircraft at a scene?", "Takes charge on scene until the first SAR aircraft arrives."], ["Ground signal V?", "Require assistance."], ["Ground signal X?", "Require medical assistance."], ["Ground signal arrow?", "Proceeding in this direction."], ["Ground signals Y and N?", "Yes and No."], ["Aircraft acknowledging a ground signal by day?", "Rocks its wings."], ["By night?", "Flashes its landing lights (or nav lights) on and off twice."]], "quiz": [["A survivor lays out a large 'X' on the ground. It means:", ["Require medical assistance", "Require assistance", "Proceeding in this direction", "No"], 0, "X is medical assistance; V is general assistance. The two are easy to swap."], ["A survivor lays out a 'V'. It means:", ["Require assistance", "Require medical assistance", "Yes", "Proceeding in this direction"], 0, "V = require assistance."], ["By day, a pilot shows that a ground signal has been understood by:", ["Rocking the wings", "Flashing the landing lights twice", "Circling twice to the left", "Lowering the undercarriage"], 0, "Rocking the wings by day; flashing the landing or navigation lights twice at night. No reply means not understood."], ["To get a constant SAR watch, a pilot should:", ["File a flight plan", "Book out with the aerodrome", "Call 121.5 MHz every 30 minutes", "Squawk 7000 with Mode C"], 0, "Filing a flight plan sets up the overdue action that triggers SAR."], ["A flight plan is advisable for SAR purposes when flying:", ["More than 10 nm from the coast, over remote areas, or without a suitable radio", "More than 20 nm from the coast or over congested areas", "Outside controlled airspace for more than an hour", "More than 10 km from the coast"], 0, "10 nm (not km, not 20 nm), remote or hazardous areas, or no suitable radio."], ["You decide en route to land somewhere other than your flight-planned destination. You must tell the original destination:", ["Before your ETA there plus 30 minutes", "Before your ETA there plus 60 minutes", "Within 24 hours of landing", "Only if you were in controlled airspace"], 0, "Otherwise overdue action and SAR start at ETA plus 30 minutes."], ["Which emergency phase is declared when there is concern for an aircraft's safety?", ["The alert phase", "The uncertainty phase", "The distress phase", "The urgency phase"], 0, "Uncertainty is doubt, alert is concern, distress is reasonable certainty of grave danger. 'Urgency' is a state of emergency, not a phase."], ["You see a boat sinking and you are the first aircraft on scene. You should:", ["Keep it in sight, fix your position and report to the RCC or ATSU", "Land nearby to help", "Leave the area so as not to hinder rescuers", "Circle until you see the occupants rescued, without reporting"], 0, "Keep sight, fix your own position, report type, position, time, numbers and condition, then act as instructed. You also take charge on scene until a SAR aircraft arrives."], ["An alerting service is provided by ATS to:", ["All aircraft known to ATS in the UK FIRs", "Only aircraft on a flight plan", "Only aircraft in controlled airspace", "Only IFR flights"], 0, "It is for all aircraft known to ATS; a flight plan just makes you known in advance."]]});
Object.assign(SUM,{"Search and rescue in the UK": "A Rescue Coordination Centre controls SAR; 121.5 MHz is watched continuously.", "Alerting service": "For all aircraft known to ATS; the ATSU last in contact normally starts it.", "Position fixing on 121.5 MHz": "Calling on 121.5 MHz lets the D&D cell fix your position.", "Transponder in an emergency": "7700, 7600 and 7500 with Mode C.", "SAR watch": "File a flight plan for a SAR watch; tell your destination of a diversion before ETA plus 30 minutes.", "ICAO Annex 12": "SAR 24 hours a day for any nationality, in non-overlapping regions each with an RCC.", "Emergency phases": "Uncertainty, then alert, then distress, each with more RCC action.", "If you see an aircraft or vessel in distress (5.8)": "Keep it in sight, fix your position, report what you see, follow instructions.", "If you intercept a distress call (5.9)": "Record the position, take a bearing, pass it on, and head there if appropriate.", "Signals from survivors": "V assistance, X medical, arrow direction, Y yes, N no. Rock wings by day, flash lights twice at night."});
NOTES.push({"s": 0, "topic": "Accident Investigation Regulations", "num": 15, "order": 150, "conf": "weak", "status": "draft", "summary": "An accident happens between boarding with the intention of flight and everyone getting off, when someone is killed or seriously injured by the aircraft (including parts that fall off, and jet blast), when the aircraft suffers structural damage needing major repair (damage only to the engine, propeller, wingtips, aerials, tyres, brakes or small dents doesn't count), or when it is missing. The commander tells the AAIB (Chief Inspector of Air Accidents) and the police by the quickest means. The State where it happens investigates, to find the cause and prevent a repeat, never to blame. Report all bird strikes, and MORs through the CAA's portal.", "sections": [["What counts as an accident", ["An occurrence between the time <b class=\"k\">anyone boards with the intention of flight</b> and the time <b class=\"k\">all have left</b>, in which:", "– someone is <b class=\"k\">killed or seriously injured</b>: in or on the aircraft, by <b class=\"k\">direct contact</b> with any part of it (including parts that have <b class=\"k\">come off</b>), or by <b class=\"k\">jet blast</b>. Not if from <b class=\"k\">natural causes</b>, <b class=\"k\">self-inflicted</b>, inflicted by <b class=\"k\">others</b>, or a <b class=\"k\">stowaway</b> outside the normal areas.", "– the aircraft has <b class=\"k\">damage or structural failure</b> that <b class=\"k\">affects its strength, performance or flight characteristics</b> and would normally need <b class=\"k\">major repair or replacement</b>. <b class=\"k\">Not</b> an accident: damage limited to the <b class=\"k\">engine</b>, its cowlings or accessories; or to <b class=\"k\">propellers, wingtips, aerials, tyres, brakes, fairings</b>, small dents or punctures.", "– the aircraft is <b class=\"k\">missing</b> or <b class=\"k\">completely inaccessible</b> (missing = the official search has ended without finding the wreckage).", "<b>Exam trap</b> A person on the ground hit by a part that <b class=\"k\">fell off</b> an aircraft in flight → <b class=\"k\">accident</b>. A person on the apron hit by the wingtip of a <b class=\"k\">taxiing</b> aircraft → accident (someone boarded with the intention of flight)."]], ["Serious injury", ["Hospital for more than <code>48 hours</code>, starting within <code>7 days</code>", "a <b class=\"k\">fracture</b> (except simple fractures of fingers, toes or nose)", "<b class=\"k\">lacerations</b> causing severe bleeding or nerve, muscle or tendon damage", "injury to an <b class=\"k\">internal organ</b>", "<b class=\"k\">second or third-degree burns</b>, or burns over <code>5%</code> of the body", "verified exposure to <b class=\"k\">infectious substances</b> or harmful <b class=\"k\">radiation</b>"]], ["Notifying an accident", ["The <b class=\"k\">commander</b> (or the <b class=\"k\">operator</b> if the commander is killed or incapacitated) tells, <b class=\"k\">by the quickest means</b>:", "– the <b class=\"k\">Chief Inspector of Air Accidents</b> (the <b class=\"k\">AAIB</b>)", "– the <b class=\"k\">local police</b>, if it happened in or over the UK", "The <b class=\"k\">State in which the accident happens</b> starts the investigation."]], ["Incidents", ["An occurrence, <b class=\"k\">other than an accident</b>, that <b class=\"k\">affected or could have affected</b> safety. Examples: an <b class=\"k\">Airprox</b>, a near miss with the <b class=\"k\">ground</b>, <b class=\"k\">undershooting or overshooting</b> a runway, a structural or engine failure that isn't an accident, <b class=\"k\">crew incapacitation</b>, <b class=\"k\">low fuel</b> leading to a Mayday.", "<code>Serious incident</code>: one that <b class=\"k\">almost</b> resulted in an accident. Damage or injury = accident; <b class=\"k\">could have</b> = incident."]], ["Purpose of an investigation", ["<b class=\"k\">Only</b> to find the <b class=\"k\">cause</b> and <b class=\"k\">prevent recurrence</b>. Investigators do <b class=\"k\">not</b> apportion <b class=\"k\">blame or liability</b>.", "The commander must <b class=\"k\">assist</b> the investigators.", "The <b class=\"k\">CAA</b> is legally responsible for implementing safety recommendations.", "<b class=\"k\">CHIRP</b> (the Confidential Human Factors <b class=\"k\">Incident</b> Reporting Programme) takes confidential reports; its <b class=\"k\">GA Feedback</b> is published online."]], ["ICAO Annex 13", ["Procedures for States investigating accidents and incidents, so experts from different States cooperate and the lessons are shared worldwide.", "An accredited investigator may: <b class=\"k\">visit the scene</b>, examine the <b class=\"k\">wreckage</b>, get <b class=\"k\">witness</b> information, have access to all relevant <b class=\"k\">evidence</b>, take part in tests and simulations, and make <b class=\"k\">submissions</b>."]], ["Reporting", ["<code>Bird strikes</code>: report <b class=\"k\">all</b> of them, <b class=\"k\">damage or not</b>. Near misses are welcome too.", "<code>Mandatory Occurrence Reports (MOR)</code>: the events listed in <b class=\"k\">Regulation 2015/1018</b> (under Regulation 376/2014). Anything else can go in as a <b class=\"k\">voluntary</b> report.", "The book gives the EU's online portal; UK pilots report to the <b class=\"k\">CAA</b> through its own online occurrence-reporting portal (check the CAA website for the current link)."]]], "cards": [["When does the accident 'window' start and end?", "From when anyone boards with the intention of flight until all have left."], ["Is a person on the ground hit by a part that fell off an aircraft an accident?", "Yes."], ["Is damage limited to the propeller an accident?", "No (nor engine-only damage, wingtips, aerials, tyres, brakes, small dents)."], ["Is a missing aircraft an accident?", "Yes, once the official search ends without finding the wreckage."], ["Who must be told of a UK accident, and how?", "The Chief Inspector of Air Accidents (AAIB) and the local police, by the quickest means."], ["Who tells them if the commander is killed?", "The operator."], ["Which State starts the investigation?", "The State in which the accident happens."], ["Purpose of an accident investigation?", "To find the cause and prevent recurrence; not to apportion blame or liability."], ["Serious injury: hospital time?", "More than 48 hours, starting within 7 days."], ["Which fractures don't count as serious injury?", "Simple fractures of fingers, toes or nose."], ["Accident vs serious incident?", "An accident has the damage or injury; a serious incident nearly did."], ["Which bird strikes must be reported?", "All of them, damage or not."], ["What does CHIRP stand for?", "Confidential Human Factors Incident Reporting Programme."]], "quiz": [["Which of these is an aircraft accident?", ["A person on the ground is seriously injured by a part that falls off an aircraft in flight", "A tyre bursts on landing", "An aerial breaks off in flight", "A bird strike leaves a small dent in the wing"], 0, "Injury from a detached part is an accident. Tyres, aerials and small dents are listed exceptions."], ["An engine fails in the circuit and the aircraft lands safely on the runway. Damage is limited to the engine. This is:", ["Not an accident; engine-only damage is excluded", "An accident", "A serious injury occurrence", "An accident only if the engine must be replaced"], 0, "Damage limited to the engine, its cowlings or accessories is excluded. It is still reportable as an occurrence."], ["A person on the apron is seriously injured by the wingtip of an aircraft taxiing for departure. This is:", ["An accident", "An incident", "Not reportable", "An accident only if the aircraft is damaged"], 0, "People had boarded with the intention of flight, and a person was seriously injured by direct contact with the aircraft."], ["A UK accident must be reported by the quickest means to:", ["The Chief Inspector of Air Accidents and the local police", "The CAA and the AAIB", "The CAA and the police", "The operator and the insurer"], 0, "AAIB (the Chief Inspector) and the police. The CAA is the trap."], ["Who is responsible for starting the investigation of an accident?", ["The authority of the State in which it occurred", "The State of Registry", "The CAA, wherever it happens", "The aircraft's operator"], 0, "The State of Occurrence starts the investigation; other States may take part."], ["The purpose of an accident investigation is to:", ["Find the cause and prevent recurrence", "Decide who was to blame", "Assess liability for insurers", "Decide whether to prosecute the pilot"], 0, "Investigators do not apportion blame or liability."], ["Which of these counts as a serious injury?", ["A broken arm", "A simple fracture of a finger", "A night in hospital for observation", "A small cut"], 0, "Most fractures count, but not simple fractures of fingers, toes or nose. Hospital must be more than 48 hours."], ["Which bird strikes should be reported?", ["All of them, whether or not there is damage", "Only those that cause damage", "Only those that cause an accident", "Only those at controlled aerodromes"], 0, "Every bird strike, and near misses are welcome too."]]});
Object.assign(SUM,{"What counts as an accident": "Death or serious injury, structural damage needing major repair, or a missing aircraft, between boarding and everyone getting off.", "Serious injury": "Over 48 hours in hospital, most fractures, serious cuts, organ damage, bad burns, infection or radiation.", "Notifying an accident": "Commander tells the AAIB and the police by the quickest means; the State of Occurrence investigates.", "Incidents": "Anything else that affected or could have affected safety; a serious incident almost became an accident.", "Purpose of an investigation": "To find the cause and prevent recurrence, not to blame; the commander must help.", "ICAO Annex 13": "How States investigate and share the lessons.", "Reporting": "Report every bird strike; MORs and voluntary reports go to the CAA online."});
NOTES.push({"s": 0, "topic": "ICAO Annex Terminology", "num": 16, "order": 160, "conf": "weak", "status": "draft", "summary": "The exam uses ICAO's definitions exactly. Know the aerodrome areas (manoeuvring area excludes aprons, movement area includes them), the declared distances (TODA = TORA + clearway, ASDA = TORA + stopway), and the vertical words (altitude from sea level, height from a datum, elevation of a point on the ground, flight level on 1013.2 hPa). A cloud ceiling is the lowest layer below 20,000 ft covering more than half the sky. A CTR starts at the surface, a CTA above it. Flight time runs from first moving to take off until coming to rest. The emergency phases are uncertainty, alert and distress.", "sections": [["ICAO Annex terminology", ["Terms used in the ICAO Annexes and in the PPL exams, grouped by theme. See also the Part-FCL terms in Pilots Licences."]], ["Aircraft", ["<code>Aircraft</code>: any machine that can derive support in the atmosphere from the reactions of the air, <b class=\"k\">other than</b> reactions against the earth's surface (so not a hovercraft).", "<code>Heavier-than-air</code>: lift mainly from <b class=\"k\">aerodynamic</b> forces.", "<code>Lighter-than-air</code>: supported mainly by <b class=\"k\">buoyancy</b>.", "<code>Aeroplane</code>: <b class=\"k\">power-driven</b>, heavier than air, lift from <b class=\"k\">fixed</b> wings.", "<code>Glider</code>: the same but <b class=\"k\">not</b> <b class=\"k\">power-driven</b>.", "<code>Rotorcraft</code>: <b class=\"k\">power-driven</b>, lift from one or more rotors.", "<code>Helicopter</code>: lift <b class=\"k\">and control</b> from <b class=\"k\">power-driven</b> rotors on substantially vertical axes.", "<code>Gyroplane</code>: lift from a <b class=\"k\">freely rotating</b> rotor, thrust from a propeller.", "<code>Airship</code>: power-driven lighter than air.", "<code>Balloon</code>: non-power-driven lighter than air."]], ["Aerodromes", ["<code>Aerodrome</code>: a defined area on land or water for the <b class=\"k\">arrival, departure and surface movement</b> of aircraft.", "<code>Heliport</code>: the same for helicopters.", "<code>Aerodrome elevation</code>: the elevation of the <b class=\"k\">highest point of the landing area</b>.", "<code>Aerodrome reference point</code>: its designated geographical location.", "<code>Aerodrome traffic</code>: all traffic on the <b class=\"k\">manoeuvring area</b> and all aircraft <b class=\"k\">in the vicinity</b>, which means <b class=\"k\">in, entering or leaving the traffic circuit</b>.", "<code>Manoeuvring area</code>: used for <b class=\"k\">taxiing, take-off and landing</b>, <b class=\"k\">excluding aprons</b>.", "<code>Movement area</code>: the manoeuvring area <b class=\"k\">plus aprons</b>.", "<code>Apron</code>: for parking, loading, refuelling and maintenance.", "<code>Aircraft stand</code>: a parking place on the apron.", "<code>Runway</code>: a defined rectangular area for take-off and landing.", "<code>Threshold</code>: the beginning of the usable runway (normally the piano keys).", "<code>Touchdown zone</code>: just beyond it, where landing aircraft first touch down.", "<b class=\"k\">Taxiway</b>, <b class=\"k\">taxi-holding position</b> (where you may be held before entering or crossing a runway), <b class=\"k\">holding bay</b>.", "<code>Signal area</code>: where ground signals are displayed.", "<code>Marking</code>: a symbol on the movement area surface.", "<code>Marker</code>: an object above ground showing an obstacle or boundary.", "<code>Runway guard lights</code>: warn that you are about to enter an active runway.", "<code>Aerodrome beacon</code>: shows the aerodrome's location from the air.", "<code>Identification beacon</code>: flashes a code to identify the location.", "<code>Hazard beacon</code>: marks a danger.", "<code>Obstacle</code>: any fixed or mobile object on the movement area, or one that sticks up through a protected surface, above a defined height."]], ["Declared distances", ["<code>TORA</code> (take-off run available): runway length available for the <b class=\"k\">ground run</b>.", "<code>TODA</code> (take-off distance available): <b class=\"k\">TORA + clearway</b>.", "<code>ASDA</code> (accelerate-stop distance available): <b class=\"k\">TORA + stopway</b>.", "<code>LDA</code> (landing distance available): runway available for the landing ground run (may start at a <b class=\"k\">displaced threshold</b>).", "<code>Clearway</code>: an area beyond the runway, under the aerodrome's control, suitable for the <b class=\"k\">initial climb</b>.", "<code>Stopway</code>: a prepared area beyond the runway for <b class=\"k\">stopping</b> after an abandoned take-off.", "The CAA agrees declared distances; they are published in <b class=\"k\">AIP AD</b>."]], ["Heights and levels", ["<code>Altitude</code>: vertical distance of a point from <b class=\"k\">mean sea level</b>.", "<code>Elevation</code>: of a point <b class=\"k\">on the earth's surface</b> from <b class=\"k\">mean sea level</b>.", "<code>Height</code>: from a <b class=\"k\">specified datum</b> (e.g. the aerodrome).", "<code>Level</code>: a generic term for <b class=\"k\">height, altitude or flight level</b>.", "<code>Flight level</code>: a surface of constant pressure related to <code>1013.2 hPa</code>, in hundreds of feet (FL180 = 18,000 ft on 1013).", "<code>Pressure altitude</code>: altitude in the standard atmosphere for that pressure (1013.2 set).", "<code>Transition altitude</code>: at or below it, vertical position is by <b class=\"k\">altitude</b> (QNH); <code>3,000 ft</code> at most UK aerodromes outside CAS, higher in some CAS (18,000 ft in the USA).", "<code>Transition level</code>: the <b class=\"k\">lowest flight level</b> usable above it.", "<code>Transition layer</code>: between the two.", "<code>Cruising level</code>: held for a large part of the flight."]], ["Weather and visibility", ["<code>Cloud ceiling</code>: height above ground or water of the base of the lowest layer below <code>20,000 ft</code> covering <b class=\"k\">more than half the sky</b>.", "<code>Visibility</code>: how far prominent <b class=\"k\">unlit objects by day</b> and <b class=\"k\">lit objects by night</b> can be seen.", "<code>Flight visibility</code>: forward from the cockpit in flight.", "<code>Ground visibility</code>: at an aerodrome, reported by an observer.", "<code>Runway visual range (RVR)</code>: how far a pilot on the <b class=\"k\">centreline</b> can see the runway markings or lights.", "<code>VMC</code>: visibility, cloud distance and ceiling <b class=\"k\">equal to or better than</b> the minima.", "<code>IMC</code>: <b class=\"k\">less than</b> them.", "<code>SIGMET</code>: hazardous weather information for flights. <b class=\"k\">AIRMET</b> (now <b class=\"k\">GAMET</b> in the UK) for low-level flights.", "<code>Meteorological report</code>: observed conditions at a place and time.", "<code>Forecast</code>: expected conditions.", "<code>Air-report</code>: a report from an aircraft in flight.", "<code>Slush</code>: water-saturated snow that splatters underfoot.", "<code>Dry snow</code>: blows when loose, falls apart when squeezed.", "<code>Wet snow</code>: sticks into a snowball.", "<code>Compacted snow</code>: pressed into a solid mass."]], ["ATS and airspace", ["<code>Air traffic service</code>: <b class=\"k\">flight information</b>, <b class=\"k\">alerting</b>, <b class=\"k\">air traffic advisory</b> or <b class=\"k\">air traffic control</b> service.", "<code>Air traffic control service</code>: to <b class=\"k\">prevent collisions</b> (in the air, and on the manoeuvring area with obstructions) and <b class=\"k\">expedite</b> an orderly flow.", "<code>ATC clearance</code>: <b class=\"k\">authorisation</b> to proceed under conditions set by ATC.", "<code>ATC instruction</code>: a <b class=\"k\">directive</b> requiring a specific action.", "<code>Clearance limit</code>: the point the clearance runs to.", "<code>Flight information service</code>: advice and information for safe and efficient flight.", "<code>Alerting service</code>: notifies organisations of aircraft needing SAR, and assists them.", "<code>Control zone (CTR)</code>: controlled airspace from the <b class=\"k\">surface</b> up to a specified limit.", "<code>Control area (CTA)</code>: controlled airspace from a specified height <b class=\"k\">above the surface</b>.", "<code>Terminal control area (TMA)</code>: a control area normally around major aerodromes.", "<code>Airway</code>: a control area in the form of a <b class=\"k\">corridor</b>.", "<code>Controlled airspace</code>: ATC is provided to IFR and VFR flights in line with its class.", "<code>Controlled aerodrome</code>: ATC is provided to aerodrome traffic (not necessarily inside a CTR).", "<code>Controlled flight</code>: any flight subject to an ATC clearance.", "<code>Advisory airspace / advisory route</code>: air traffic advisory service available (none in the UK now).", "<code>Flight information region (FIR)</code>: FIS and alerting available.", "<code>Flight information centre</code>: the unit that provides them.", "<code>ATS unit</code>: ATC unit, flight information centre or ATS reporting office.", "<code>Special VFR flight</code>: a VFR flight <b class=\"k\">cleared by ATC</b> to operate in a <b class=\"k\">control zone</b> in conditions <b class=\"k\">below VMC</b>.", "<code>Traffic information</code>: from ATC about known traffic nearby.", "<code>Traffic avoidance advice</code>: advice to help avoid a collision.", "<code>ATIS</code>: continuous recorded broadcast of routine aerodrome information.", "<code>Holding fix</code> (the book calls it a \"<b class=\"k\">holding point</b>\"): a location around which an aircraft flies a standard holding pattern. In UK radio a holding point is the place you stop before a runway.", "<code>Expected approach time</code>: when ATC expects a holding aircraft to leave the hold for its approach.", "<code>Approach sequence</code>: the order of aircraft cleared to approach."]], ["Radar", ["<code>Primary radar</code>: uses <b class=\"k\">reflected</b> radio signals.", "<code>Secondary surveillance radar (SSR)</code>: an interrogator prompts a <b class=\"k\">reply</b> from the aircraft's <b class=\"k\">transponder</b>.", "<code>Radar contact</code>: the aircraft's position seen and identified on the display.", "<code>Radar identification</code>: positively identified by the controller.", "<code>Radar vectoring</code>: headings given from radar.", "<code>Radar monitoring</code>: radar used to tell aircraft about deviations from their route or clearance.", "<code>ACAS</code>: airborne collision avoidance from transponder signals, independent of the ground."]], ["Flight plans and times", ["<code>Flight plan</code>: specified information given to ATS about an intended flight.", "<code>Filed flight plan</code>: as submitted, before any changes.", "<code>ETA</code>: VFR, arrival <b class=\"k\">over the destination aerodrome</b>; IFR, arrival over the point where the instrument approach begins.", "<code>Estimated off-block time</code>: when the aircraft will start moving for departure.", "<code>Estimated elapsed time</code>: from one significant point to another.", "<code>Flight time</code>: the total time from when the aircraft <b class=\"k\">first moves for the purpose of taking off</b> until it <b class=\"k\">finally comes to rest</b> at the end of the flight (\"chock to chock\"). The book says \"from the beginning of the take-off roll\", which contradicts its own note.", "<code>Pilot-in-command</code>: responsible for the <b class=\"k\">operation and safety</b> of the aircraft during flight time.", "<code>Operator</code>: a person or organisation engaged in aircraft operation.", "<code>Alternate aerodrome</code>: where you can go if landing at the destination becomes impossible or inadvisable (en-route or destination alternate)."]], ["Emergencies, accidents and SAR", ["<code>Emergency phase</code>: <b class=\"k\">uncertainty</b>, <b class=\"k\">alert</b> or <b class=\"k\">distress</b> phase.", "<code>Uncertainty</code>: safety uncertain.", "<code>Alert</code>: concern for safety.", "<code>Distress</code>: reasonably certain of <b class=\"k\">grave and imminent danger</b> or need of immediate assistance.", "<code>Ditching</code>: a forced landing <b class=\"k\">on water</b>.", "<b class=\"k\">Accident</b>, <b class=\"k\">serious incident</b>, <b class=\"k\">serious injury</b>: see Accident Investigation Regulations.", "<code>Rescue coordination centre</code>: organises SAR in a <b class=\"k\">search and rescue region</b>.", "<code>Rescue unit</code>: trained and equipped people.", "<code>Dangerous goods</code>: articles or substances that pose significant risk to health, safety or property when carried by air.", "<code>Fireproof material</code>: withstands heat <b class=\"k\">as well as or better than steel</b>."]], ["States", ["<code>State of Registry</code>: where the aircraft is registered.", "<code>State of the Operator</code>: the operator's principal place of business. <b class=\"k\">State of Design</b> and <b class=\"k\">State of Manufacture</b>: responsible for the type design and final assembly.", "<code>State of Occurrence</code>: where the accident or incident happens.", "<code>Appropriate authority</code>: over the high seas, the <b class=\"k\">State of Registry</b>; over a State's territory, <b class=\"k\">that State</b>."]], ["Communications", ["<code>Blind transmission</code>: sent when two-way contact can't be made but the station is believed to receive it.", "<code>Broadcast</code>: an \"all stations\" transmission.", "<code>Aeronautical fixed service</code>: between fixed points (e.g. the AFTN).", "<code>Aeronautical station</code>: a ground or sea station in the aeronautical mobile service.", "<code>Location indicator</code>: the four-letter code of an aeronautical fixed station (e.g. <b class=\"k\">EGKK</b>).", "<code>Air-taxiing</code>: a helicopter moving above an aerodrome surface, normally in ground effect, below <code>20 kt</code> groundspeed."]]], "cards": [["Manoeuvring area?", "For taxiing, take-off and landing, excluding aprons."], ["Movement area?", "The manoeuvring area plus aprons."], ["Aerodrome elevation?", "The elevation of the highest point of the landing area."], ["Aerodrome traffic?", "All traffic on the manoeuvring area and all aircraft in the vicinity (in, entering or leaving the circuit)."], ["TODA?", "TORA plus clearway."], ["ASDA?", "TORA plus stopway."], ["Altitude?", "Vertical distance of a point from mean sea level."], ["Height?", "Vertical distance from a specified datum."], ["Elevation?", "Vertical distance of a point on the earth's surface from mean sea level."], ["Transition level?", "The lowest flight level available above the transition altitude."], ["Cloud ceiling?", "Base of the lowest layer below 20,000 ft covering more than half the sky."], ["Control zone vs control area?", "CTR from the surface up; CTA from a specified height above the surface."], ["ATC clearance vs instruction?", "A clearance authorises you to proceed under conditions; an instruction directs a specific action."], ["Special VFR flight?", "A VFR flight cleared by ATC to operate in a CTR below VMC."], ["Flight time?", "From first moving for the purpose of taking off until coming to rest after the flight."], ["The emergency phases?", "Uncertainty, alert, distress."], ["Fireproof material?", "Withstands heat as well as or better than steel."], ["Air-taxiing?", "Helicopter movement above an aerodrome surface, normally in ground effect, below 20 kt groundspeed."]], "quiz": [["The movement area of an aerodrome is:", ["The manoeuvring area plus the aprons", "The manoeuvring area, excluding aprons", "The runways only", "The aprons and taxiways only"], 0, "Movement includes aprons; manoeuvring excludes them. The exam swaps these often."], ["TODA is:", ["TORA plus clearway", "TORA plus stopway", "TORA plus stopway plus clearway", "The landing distance available"], 0, "Clearway is for the climb-out, so it extends the take-off distance. Stopway extends ASDA."], ["ASDA is:", ["TORA plus stopway", "TORA plus clearway", "TODA plus stopway", "The runway length less any displaced threshold"], 0, "Accelerate-stop: you need somewhere to stop, so stopway."], ["Aerodrome elevation is the elevation of:", ["The highest point of the landing area", "The aerodrome reference point", "The threshold of the main runway", "The control tower base"], 0, "ICAO uses the highest point of the landing area."], ["The vertical distance of an aircraft from mean sea level is its:", ["Altitude", "Height", "Elevation", "Flight level"], 0, "Altitude is from MSL. Height is from a datum such as the aerodrome; elevation is for a point on the ground; flight levels use 1013.2 hPa."], ["A cloud ceiling is the height of the base of the lowest cloud layer:", ["Below 20,000 ft covering more than half the sky", "Below 10,000 ft covering more than half the sky", "Below 20,000 ft covering at least a quarter of the sky", "Of any amount below 5,000 ft"], 0, "More than half the sky (BKN or OVC) and below 20,000 ft."], ["A control zone is controlled airspace extending:", ["Upwards from the surface to a specified upper limit", "Upwards from a specified height above the surface", "From FL100 to FL195", "Only along a corridor between navaids"], 0, "A CTR starts at the surface. A CTA starts at a height above it; an airway is a corridor-shaped CTA."], ["Under ICAO and Part-FCL, flight time starts when the aircraft:", ["First moves for the purpose of taking off", "Begins its take-off roll", "Becomes airborne", "Has its engine started"], 0, "It runs from first moving to take off until it comes to rest. The book's glossary says 'take-off roll', which is wrong."], ["The transition level is:", ["The lowest flight level available for use above the transition altitude", "The highest altitude flown on QNH", "The airspace between transition altitude and transition level", "Always FL40 in the UK"], 0, "The transition altitude is the top of QNH flying; the transition level is the lowest usable FL above it; between them is the transition layer."], ["An area at the end of the runway prepared for stopping after an abandoned take-off is a:", ["Stopway", "Clearway", "Runway end safety area", "Holding bay"], 0, "Stopway is for stopping (in ASDA). Clearway is for the initial climb (in TODA)."]]});
Object.assign(SUM,{"ICAO Annex terminology": "The definitions the exam uses, grouped by theme.", "Aircraft": "Lighter or heavier than air, power-driven or not: aeroplane, glider, helicopter, gyroplane, airship, balloon.", "Aerodromes": "Manoeuvring area excludes aprons; movement area includes them. Elevation is the highest point of the landing area.", "Declared distances": "TORA; TODA = TORA + clearway; ASDA = TORA + stopway; LDA.", "Heights and levels": "Altitude from MSL, height from a datum, elevation of a ground point, flight levels on 1013.2 hPa.", "Weather and visibility": "Ceiling: lowest layer below 20,000 ft covering more than half the sky.", "ATS and airspace": "CTR from the surface, CTA from a height above it; a clearance authorises, an instruction directs.", "Radar": "Primary radar uses reflections; SSR gets replies from transponders.", "Flight plans and times": "Flight time runs chock to chock; ETA for VFR is over the destination aerodrome.", "Emergencies, accidents and SAR": "Uncertainty, alert and distress phases; ditching is a forced landing on water.", "States": "State of Registry, of the Operator, of Design, of Manufacture and of Occurrence.", "Communications": "Blind transmission, broadcast, location indicators (EGKK) and air-taxiing."});
